window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_040"]={"n":"李孙宸","dyn":"明","poems":[{"t":"自君之出矣 其一","f":"五言绝句","c":["自君之出矣，妆匣久不开。","思君如落叶，重重扫复堆。"]},{"t":"自君之出矣 其二","f":"五言绝句","c":["自君之出矣，怀抱向谁说。","思君如织梭，牵丝何日绝。"]},{"t":"白云谣","f":"古风","c":["白云西垂，罡风在耳。","东土悠远，陵谷间之。","将子复来，桃熟为期。"]},{"t":"徐人歌","f":"楚辞体","c":["延陵季子兮，不负故。","挂邱墓之剑兮，为心许。"]},{"t":"越人歌","f":"楚辞体","c":["今夕何夕兮乘青翰舟，今日何日兮载王子于中流。","含情欲诉兮怀羞复止，魂荡泆而不禁兮竟为痴。","使山有桥兮隰有荷，悦王子兮可奈何。"]},{"t":"秋风词","f":"楚辞体","c":["秋风生兮白露霏，百卉萎落兮玄鸟归。","采有兰兮佩有香，遗美人兮隔汾阳。","击鼍鼓兮美遨游，挟飞龙兮横中流。","饮宴张兮乐未休，憾慨系兮转烦忧，盛年不再兮哪可留。"]},{"t":"李夫人歌","f":"古风","c":["死耶生耶，惠然而来者，灯宛宛其若明。","生耶死耶，霎然而去者，风萧萧其未止。"]},{"t":"鸡鸣歌","f":"七言古诗","c":["海日欲吐东方熹，帘栊未曙晨鸡知。","严更罢报停虱箭，晨飔飒飒夜色微。","宫殿初传鱼钥来，万户千门次第开。"]},{"t":"将进酒","f":"古风","c":["将进酒，酾羽卮。","酣佳哉，君莫辞。","曷侑之，奏雅诗。","启皓齿，扬妙词。","使国良工和者稀。"]},{"t":"有所思","f":"古风","c":["有所思，乃在碧云端。","何以托精诚，长揖招青鸾。","附我尺素词，闻君不我欲，拉杂碎裂之。","碎裂之，当风扬其丝。","一刀两断，割此相思。","相思从此绝，天长地久，山海有推移。","晨鸣鸡，冷风飒飒星斗稀，东方渐白君不知。"]},{"t":"雉子斑","f":"古风","c":["雉子斑，同母生长草泽间。","毛羽初成相比匹，我斑不如尔斑斑。","须臾群飞戏江干，王孙见之择而弹。","斑者先残。","雉子惊飞去向其母言：母生我曷斑，速为我擢毛毁羽免受王孙弹。"]},{"t":"捉袅歌四首 其一","f":"七言绝句","c":["有粟不舂附杵臼，有女不嫁问媒妇。","长安车马自朝暮，若个路歧不走错。"]},{"t":"捉袅歌四首 其二","f":"七言绝句","c":["谁家儿郎骑白马，往来只在青楼下。","男女两个自不假，六礼百两何为者。"]},{"t":"捉袅歌四首 其三","f":"七言绝句","c":["鸳鸯美锦人皆羡，暗里机丝哪得见。","上堂日日好会面，谁识归房脉脉怨。"]},{"t":"捉袅歌四首 其四","f":"七言绝句","c":["洗头盘在华山顶，十丈莲花开玉井。","女儿淡妆矜素影，不著脂粉饰项领。"]},{"t":"折杨柳歌 其一","f":"五言绝句","c":["欢边杨柳树，叶叶郁葳蕤。","妾家折杨柳，但爱绾别离。"]},{"t":"折杨柳歌 其二","f":"五言绝句","c":["饮马孟津河，河水冻结冰。","虏儿听汉歌，不识歌中情。"]},{"t":"折杨柳歌 其三","f":"五言绝句","c":["阿母遣女织，织作嫁女衣。","嫁衣色已变，嫁女定几时。"]},{"t":"折杨柳歌 其四","f":"五言绝句","c":["妾心如鸟飞，飞傍郎身转。","飞得到咸阳，郎又往沙苑。"]},{"t":"乌生八九子","f":"古风","c":["乌生八九子，哺子生毒荼。","拮据为巢，乃在城巅高树隅。","得食不下咽，衔之吻间饲诸雏。","毛羽摧颓宁暇顾，腹饥骨瘁尾毕逋。","八九子，羽翼齐，分飞各东西。","老鸟哑哑巢中啼，风雨飘摇何处栖。","吁嗟乎，豺虎噬人犹有亲，虫类蜂蚁识君臣。","乌不反哺，不如羊跪乳之仁。"]},{"t":"长歌行","f":"五言古诗","c":["浥浥薤上露，朝朝望日零。","园林有百卉，当春敷其荣。","秋气日夕至，蟋蟀床下鸣。","繁华有衰谢，严霜皓以盈。","黄河以东注，白日以西倾。","去去理无返，少壮何能恒。","所愿逮良辰，勉竖功与名。","无为空迟暮，叹羡彼后生。"]},{"t":"短歌行","f":"古风","c":["嘉宾在堂，旨酒盈觞。","何以乐之，鼓瑟吹簧。","衣不如新，乃有布素。","子有新人，莫忘其故。","高高者天，明明者月。","忧心殷殷，不可以说。","鸣鹤在阴，其子和之。","有美一人，寤寐求之。","鸟乐同材，鱼乐同渊。","与子交亲，可以年年。"]},{"t":"燕歌行 其一","f":"七言古诗","c":["忆年十五发初长，为君许嫁登君堂。","蘼芜薜荔裁衣裳，步移珊珊响明珰。","扬蛾宛转入兰房，一心持赠无相忘。","百年比翼两鸳鸯，谁知底事固难量。","良人行役去他乡，含情不敢诉衷肠。","送君出门独徬徨，春花一别又秋霜。","去时君道出衡阳，昨得音书又朔方。","君行飘梗何能常，年年妾自守空床。","愿为双燕向君翔，衔坭巢君屋上梁。"]},{"t":"燕歌行 其二","f":"七言古诗","c":["明月濯濯扬清辉，金风瑟瑟华叶衰。","蟋蟀夜深床下啼，起观银汉夜何其。","二十八宿罗参差，为君中夜理桐丝。","大弦凄急小弦悲，不能终曲涕交垂。","人生春华能几时，那能离别长如斯。","入门各媚当告谁，噭噭鸿雁向南飞，何不游子偕来归。"]},{"t":"君子行","f":"五言古诗","c":["君子秉明哲，不受世垢氛。","廉隅防缺折，坚白慎淄磷。","枉直一以混，寻尺宁言伸。","仲尼千秋圣，富贵如浮云。","矫矫龙神性，何能为人驯。","卓哉鲁连子，长揖谢千金。"]},{"t":"猛虎行","f":"古风","c":["猛虎生在深山，额胡白，文胡斑。","竟日攫人充肠腹，樵采无敢出其间。","乃托巫咸，往诉山神。","山神怒责虎，上天好生虎食人。","猛虎俯首向神言，山南有鹿山北麋，爪牙不足卫其身。","朝游林莽，暮充鼎珍。","虎若不食人，将久同鹿麋烹。","吁嗟，畏恶残善人情非，乃尚欲愚猛虎为。"]},{"t":"相逢行","f":"五言古诗","c":["相逢狭道上，狭道不容鞭。","不知何年少，驱马气翩翩。","问君家远近，乃在城南隅。","翠幕垂珠箔，白玉砌庭除。","华堂锦瑟张，次第奏名姝。","庭前长玉树，芳香四序敷。","兄弟两三人，奕叶承华腴。","伯子殿中郎，仲子列金吾。","小子薄宦职，任侠倾国都。","五日一休沐，观者溢路衢。","入门开绮筵，珠履三千馀。","大妇织绮缟，中妇织流苏。","小妇尚骄小，临妆理粉朱。","大人且陶陶，安坐为欢娱。"]},{"t":"秋胡行四首 其一","f":"古风","c":["卑微易处，居高难为胜。","卑微易处，居高难为胜。","民恶其上，鬼瞰高明。","日中则昃，天地忌盈。","宁为曳尾，无为牺牲。","歌以言之，居高难为胜。"]},{"t":"秋胡行四首 其二","f":"古风","c":["千秋可垂，百年不易全。","千秋可垂，百年不易全。","宣尼大圣，毁者武孙。","姬旦祚周，四国流言。","蹠犬吠尧，孰否孰贤。","歌以言之，百年不易全。"]},{"t":"秋胡行四首 其三","f":"古风","c":["感恩易得，知己一何稀。","感恩易得，知己一何稀。","左骖见德，越石请辞。","羊舌免难，不谢祁奚。","寥寥管鲍，生我同之。","歌以言之，知己一何稀。"]},{"t":"秋胡行四首 其四","f":"古风","c":["毁誉何常，权势易为名。","毁誉何常，权势易为名。","乘风呼长，非疾其声。","窈国侯门，仁义所并。","兰生幽谷，孰扬其馨。","歌以言之，权势易为名。"]},{"t":"西门行","f":"古风","c":["出西门，步慢移。","相逢不尽欢，明日安知。","知尽欢，今日已迟迟。","车中有斗酒，与子各尽卮。","何能朝田暮，舍桎梏。","夫翁为杨花飞，马蹄滑。","请问冢中枯，今朝几行客。","生年苦不长，死年苦不短。","万岁与千秋，去者无再转。","及时行乐不须疑，崦嵫日暮夫何远。"]},{"t":"东门行","f":"古风","c":["出东门，望洛阳。","来入门，惨欲伤。","釜中无宿粒，回视桁上无悬裳。","绝裾出门去，妻子思徬徨。","他家自图富贵贱，妾与君，甘糟糠。","甘糟糠，上用青冥天，下为儿女成行。","时清法严，吏议难完。","君应记取莫相忘，行前路苦忙望君行慎行藏。"]},{"t":"门有万里客","f":"五言古诗","c":["门有万里客，风尘何苦颜。","执手前致问，果得心所欢。","含词未及吐，慷慨先长叹。","自离江南土，十载走长安。","复当从此别，故乡何日还。"]},{"t":"白头吟","f":"五言古诗","c":["昔者凤求凰，翱翔归故乡。","今者呼凤凰，颉颃乃无常。","新人枝上花，旧人花落枝。","花落无再好，枝是旧花枝。","与君久当炉，梳头不对镜。","君心有改移，开镜始自省。","君家绿绮琴，可以扬清音。","今朝弹一曲，一弦觉一心。","不见昨流水，今朝流水是。","愿得新人欢，无如旧人弃。","竹竿何袅袅，鱼尾何筛筛。","锦江西下水，一去何时归。"]},{"t":"子夜歌 六首 其一","f":"五言绝句","c":["门外马蹄响，窥帘日瞩欢。","不知欢见否，空遗气若兰。"]},{"t":"子夜歌 六首 其二","f":"五言绝句","c":["芙蓉种横浦，绿叶初田田。","一心望成藕，一心望见莲。"]},{"t":"子夜歌 六首 其三","f":"五言绝句","c":["侬发初覆肩，含羞与郎好。","所急岂少年，白头誓相保。"]},{"t":"子夜歌 六首 其四","f":"五言绝句","c":["欢负侬已多，岂不念侬故。","侬心不怨欢，欢被傍人误。"]},{"t":"子夜歌 六首 其五","f":"五言绝句","c":["侬似江上山，日日立江中。","欢心江流水，晨西夕又东。"]},{"t":"子夜歌 六首 其六","f":"五言绝句","c":["一自别欢来，无心种花药。","但种黄蘖生，苦心得相托。"]},{"t":"子夜春歌 其一","f":"五言绝句","c":["家家爱春嬉，侬却被春懊。","夫君未归来，风光总不好。"]},{"t":"子夜春歌 其二","f":"五言绝句","c":["不复怨东风，东风吹落花。","多少落锦裀，多少委坭沙。"]},{"t":"子夜春歌 其三","f":"五言绝句","c":["百卉有芳心，谢得春风吹。","如何侬心事，春风却不知。"]},{"t":"子夜春歌 其四","f":"五言绝句","c":["采花过春园，低回不忍折。","红者花颜妍，白者花心洁。"]},{"t":"子夜夏歌 其一","f":"五言绝句","c":["水榭施华妆，晚风透枕凉。","不辨荷花气，只道郎汗香。"]},{"t":"子夜夏歌 其二","f":"五言绝句","c":["郎言三伏热，岂无绿阴凉。","只怕郎心热，无处乞寒浆。"]},{"t":"子夜夏歌 其三","f":"五言绝句","c":["人采莲花妍，侬摘莲子苦。","但得郎知味，岂惮涉横浦。"]},{"t":"子夜夏歌 其四","f":"五言绝句","c":["纳凉褪罗裳，反侧睡迟迟。","所欢特底来，唐突就侬嬉。"]},{"t":"子夜秋歌 其一","f":"五言绝句","c":["秉烛照兰房，忽见明月光。","灭烛延明月，月光照朔方。"]},{"t":"子夜秋歌 其二","f":"五言绝句","c":["几夜怨西风，梧桐落阶戺。","落多桐叶稀，分明见梧子。"]},{"t":"子夜秋歌 其三","f":"五言绝句","c":["征衣须寄早，对月织流黄。","若得著郎体，不嫌作下裳。"]},{"t":"子夜秋歌 其四","f":"五言绝句","c":["既苦秋夜长，亦怯秋气凉。","无人可解说，岂复厌啼螀。"]},{"t":"子夜冬歌 其一","f":"五言绝句","c":["一夜雪皑皑，门前忽盈尺。","欢心如畏来，勿复比松柏。"]},{"t":"子夜冬歌 其二","f":"五言绝句","c":["与郎面拥炉，背后北风吹。","不须相借问，冷暖各自知。"]},{"t":"子夜冬歌 其三","f":"五言绝句","c":["冻雪飞鸟尽，忽闻朔雁声。","若非寄郎书，何用送悲鸣。"]},{"t":"子夜冬歌 其四","f":"五言绝句","c":["絮绵葺残袄，聊以禦严霜。","辛苦度岁寒，与郎乐春光。"]},{"t":"华山畿","f":"古风","c":["华山畿，蔽膝吞已死，同心结未迟。","鬼神为情痴，葬车相见期。"]},{"t":"乌栖曲 其一","f":"七言绝句","c":["白玉流苏翡翠床，不辨灯光与月光。","谁道城乌解报曙，三更乱啼误欢去。"]},{"t":"乌栖曲 其二","f":"七言绝句","c":["幅幅高帆大艑船，年年岁岁浮湘川。","城乌亦有双飞羽，何不飞啼湘川去。"]},{"t":"乌栖曲 其三","f":"七言绝句","c":["郎骑玉勒青骢马，相邀侠客青楼下。","百转梁州夜未阑，家有愁人独凭栏。"]},{"t":"乌栖曲 其四","f":"七言绝句","c":["淡月朦胧华烛残，清歌乍吐气如兰。","莲步未前心不持，秋波微盼许相知。"]},{"t":"朝云曲 其一","f":"古风","c":["阳台雨气蔼氤氲，高高巫山高入云。","容光晻暖梦中分。","梦中分，意未息。","万年游，欢无极。"]},{"t":"朝云曲 其二","f":"古风","c":["高唐春色昼迟迟，为雨为云入梦思。","荐君枕席致君辞，致君辞，去翩翩。","阳台下，心惘然。"]},{"t":"采莲曲","f":"古风","c":["中流惊散紫鸳鸯，花比朱颜叶比裳。","为君艳歌君莫忘。","君莫忘，山复河。","江南弄，采莲歌。"]},{"t":"凤笙曲","f":"古风","c":["燕音凤翼紫鸾笙，皓齿丹唇发凤鸣，切切来应云和声。","云和声，听未足。","为君弹，终一曲。"]},{"t":"赵瑟曲","f":"古风","c":["赵女朱丝发艳情，湘灵曲罢数峰青，为君破弦不成声。","不成声，心自苦。","紫鳞跃，朱凤舞。"]},{"t":"白纻舞歌 二首 其一","f":"七言古诗","c":["吴宫初制白纻衣，轻如薄雾色如脂。","遗赠佳人称体宜，舞袖未举烟云霏。","凝睇流盼光容仪，掌上轻盈态欲欹。","应节投袂不自知，腾空绝迹纷陆离。","舞馀抗身自矜奇，四座咄咄鬼神疑。","春心挑荡君好持，为君更酌金羽卮。"]},{"t":"白纻舞歌 二首 其二","f":"七言古诗","c":["春阳明媚风花香，君王无事永歌昌。","馆娃趋步响瑶珰，徵歌按拍杂笙簧。","逸态徐舒回鸾凰，将行复引声为长。","中曲再变听不遑，流风回雪乃无常。","鸣丝奋肉满中堂，颓然放体任纵横。","万岁千秋乐未央，愿君蹋歌及年光。"]},{"t":"雉朝飞操","f":"楚辞体","c":["雉朝飞兮雊相从，绥绥濈濈兮群雌雄。","我欲求匹兮谁与同，阳春布德兮蹇独茕茕。","嗟嗟布德兮蹇独茕茕。"]},{"t":"枯鱼过河泣","f":"五言古诗","c":["河伯泛洪涛，奋鬣扬䰄逝。","笑彼鲤与鲂，胡为潜渊泥。","涛落乃无常，翻为蝼蚁制。","湿沫谁相濡，中厨供甘脆。","寄语旧匹俦，白龙以为诫。"]},{"t":"陇头","f":"五言律诗","c":["陇山久成客，行吟私自怜。","春风不到处，冻雪动经年。","交河饮羸马，峻阪绝飞鸢。","四面流尘杂，乡关何处边。"]},{"t":"关山月","f":"五言律诗","c":["关山明月夜，虏骑报祁连。","清光几万里，偏照玉关前。","雪归系雁帛，冰坚饮马泉。","鼓角凄凉后，愁看欲曙天。"]},{"t":"折杨柳","f":"五言律诗","c":["青青夹道傍，垂柳复垂杨。","飞花乱飞絮，自折还自伤。","征夫归未得，贱妾梦空长。","更听吹横笛，谁不泪沾裳。"]},{"t":"刘生","f":"五言律诗","c":["少年矜节侠，籍甚有刘生。","报仇宁畏势，施德不留名。","一诺千金重，片心九死轻。","英雄原有骨，不是冶游情。"]},{"t":"出塞","f":"五言绝句","c":["铁骑出西京，长嘶入虏庭。","雷殷鼓鼙响，雪照宝刀瑩。"]},{"t":"入塞","f":"五言律诗","c":["暂息征尘苦，旋从奏凯归。","山川佳气回，楼台宿雾晞。","冲雪驱雕骑，当风解铁衣。","功成报天子，讵敢望恩辉。"]},{"t":"洛阳道","f":"五言律诗","c":["八达开佳丽，春风紫陌长。","铜街斜月照，金谷媚花光。","玉车满掷果，罗袖试提筐。","别有嵩高上，吹笙事渺茫。"]},{"t":"长安道","f":"五言律诗","c":["雄图号天府，甲乙起楼台。","落日飞轩映，朝霞绣箔开。","斗鸡新丰罢，校猎渭桥回。","相逢狭斜路，喧喧驺御催。"]},{"t":"雨雪曲","f":"五言律诗","c":["绝域阳关道，阴云冻不飞。","绕榆难辨色，傍垒暗生辉。","同怀挟纩煖，犹想向阳晞。","何日重围解，故园万里归。"]},{"t":"赠马伯起 其一","f":"五言古诗","c":["东南有高山，寂寂山之麓。","上有雨露滋，下无往来躅。","芳兰宛自生，惠风扬其馥。","采之贻美人，可以充佩服。","岂无园中葩，懿此出幽谷。"]},{"t":"赠马伯起 其二","f":"五言古诗","c":["名都富游冶，大道临青楼。","烨烨彼姝子，奇质无与俦。","顾盼溢光媚，歌曲和且柔。","东家有贫女，不饰翠与球。","觕衣蔽韶质，深闺閒春秋。","寄言游冶子，宁知彼所求。"]},{"t":"寄梁明叔黎君献","f":"五言古诗","c":["日月何奄忽，雪霜凄以霏。","朔风直北来，百卉萎华滋。","念此岁云暮，之子系所思。","缅昔携手好，欢会及良时。","含情无以喻，中夜理朱丝。","哀音振林木，繁响逐云移。","齐心领高唱，自谓无人知。","合离在俛仰，风波不可期。","双龙乖羽翼，各在天一涯。","袖中有瑶草，芳洁将遗谁。","报尔加餐食，慰我长渴饥。"]},{"t":"十六夜同诸子饮欧华玉湖上草堂因与子建伯乔二子荡舟观海尽兴而返得清字","f":"五言古诗","c":["清穹飘商风，凉露皓以盈。","林薄有爽气，日夕悠然生。","新鸿遵渚唳，玄蝉含风鸣。","主人眷嘉赏，高宴敞湖亭。","中怀既以惬，一石且未倾。","百年亦何常，胜会在良朋。","况此秋色好，澄潭映空清。","荡桨纡枉渚，弭棹薄寒汀。","抚景欢无斁，揽胜意俱停。","日落理返楫，舍舟林月明。","晤言华堂下，痛饮忍独醒。"]},{"t":"赠姚约 其一","f":"五言古诗","c":["有鸟名长离，耀彩东南涯。","灵文焕初日，九苞以自奇。","遐瞩遍中土，悠悠当何依。","岂无野雀林，托处非所宜。","峨峨千仞冈，上有椅桐枝。","迢迢沧海隔，厉翮起高飞。","朔风凄大壑，顾侣相追随。","会当际朝阳，振响以来仪。"]},{"t":"赠姚约 其二","f":"五言古诗","c":["郁郁南山松，亭亭千空青。","结根既以固，天籁自为鸣。","雨露不成滋，冰雪莫为零。","鸾凤朝暮栖，虬龙宛自惊。","匠石构明堂，思采以作楹。","作楹非不好，无乃彫吾贞。","谁识入地脂，已作千岁苓。"]},{"t":"三子诗何襄武","f":"五言古诗","c":["何生我懿亲，童稚肩相比。","令德奋鸿响，识曲听其旨。","既壮历周览，所遇无知己。","寥寥天壤间，落落竟复尔。","无乃眷吾徒，慷慨一相视。","及此理素业，含情各自媚。","荡涤喻中怀，愿言不朽事。","古道日以夷，谁复能察此。"]},{"t":"戴公纶","f":"五言古诗","c":["戴子含芳姿，婉彼幽兰质。","采在水一方，晤言结同室。","习习惠风扬，美誉云端溢。","荣华岂不好，而乃耽著述。","伸纸弄柔翰，冥心如有失。","古道当告谁，徬徨求侣匹。","去去东流水，杳杳西倾日。","努力振斯文，贻彼后死得。"]},{"t":"伍长卿","f":"五言古诗","c":["长卿秉逸尚，妙龄事幽讨。","灼彼春华姿，被服纨与缟。","时援绿绮琴，一理清商操。","中怀那可喻，含情欲谁告。","申言属所欢，勖哉维此道。","大音一以倡，颓风日以扫。","人生易奄忽，长夜漫浩浩。","千秋良在兹，胡宁但衰老。"]},{"t":"抵家 其一","f":"五言古诗","c":["行役非我意，驾言返故庐。","故庐列隘巷，观者溢路衢。","下马入堂前，夜已二更初。","骨肉次相视，涕下沾衣袪。","离家三四载，悠悠日以疏。","今兹远来归，恍然寤寐馀。","阿弟具酒浆，鸡黍出中厨。","语多卒莫陈，但慰行路劬。","饮中语阿儿，汝知汝父无。","汝欢汝父归，汝父父何徂。","语罢益涕零，满堂尽欷歔。"]},{"t":"抵家 其二","f":"五言古诗","c":["诘旦盥漱罢，父老纷来看。","亲昵短服过，疏者具衣冠。","拜揖失行序，问答无绪端。","行役倏四载，风尘多苦颜。","乡曲近来事，卒卒述难殚。","生齿有凋谢，人情有波澜。","岁俭徵求急，鸡犬靡得安。","无论享乐利，亦复多辛酸。","一闻父老言，怆然伤脾肝。","不敢说向人，但叹行路难。"]},{"t":"抵家 其三","f":"五言古诗","c":["生平缔亲友，所重在襟期。","闻我返故园，各来话别离。","开尊命杯酌，促膝致我词。","与子旧同怀，分飞各路歧。","薰莸以习化，子心宁久持。","长跪谢故人，故人当我知。","夙昔丘壑意，误逐风波驰。","交游满四海，寥寥中所私。","胶漆坚可解，蕙兰臭岂移。","客止勿复陈，与子且尽卮。","相期自今始，斗酒日相随。"]},{"t":"抵家 其四","f":"五言古诗","c":["少小事呫哔，杜门好楼居。","既辟墙东园，诛茅自结庐。","羁旅苦不归，无乃鞠邱墟。","狸鼪穴中宇，蛛网封四隅。","架上残编帙，狼藉供蠹鱼。","檐树经手植，忽已拱把馀。","出门面洲渚，泛泛鸥与凫。","恍焉喻中怀，谋生久已迂。","一身伤局促，五亩何荒芜。","来者犹可追，为乐复奚如。"]},{"t":"送刘觐国少参之任武昌","f":"五言古诗","c":["十载同怀子，行役各徬徨。","风萍飘复合，眷言聚故乡。","故乡虽云乐，欢会那能常。","炎地寒威少，十月未零霜。","仆夫戒斗酒，送子上河梁。","轸发粤王城，目望荆楚疆。","明时重屏翰，所怀在召棠。","致身事圣主，遭世幸虞唐。","愿言崇令德，懋绩纪旂常。"]},{"t":"送韩孟郁北上","f":"五言古诗","c":["缅惟二三子，正始振奇音。","玄风既以畅，兰味乃逾深。","调与时趋违，交抗古人心。","生逢昭明代，那能久陆沈。","我昔别子去，释褐忝华簪。","三载乞休沐，眷言返旧林。","绸缪方未已，分飞复异寻。","别子庾关路，停望阻且深。","北风惨以慄，慎保雪霜侵。","努力策清时，燕台有悬金。","风云会遇合，无为叹商参。"]},{"t":"卢一清韩孟郁李烟客诸子过访村居同赋","f":"五言古诗","c":["归来厌城市，屏居清溪湄。","亦协嘉遁心，寂寞故不怡。","眷此同声友，命驾酬相思。","夙契结绸缪，况复投新知。","残夜追灯宴，中堂理桐丝。","鸡黍出常羞，痛饮乃忘疲。","登高览幽豁，临水爱涟漪。","人生非木石，谁不念襟期。","会面不尽欢，别离安可知。","申言二三子，当尊莫苟辞。"]},{"t":"同卢韩李诸子泛舟作","f":"五言古诗","c":["春风荡微和，积阴亦云熙。","徵徒既缤郁，驾言采江蓠。","遥空望无际，四面来清辉。","荡桨遵枉渚，弭棹薄修湄。","沿洄虽不远，爱此清涟漪。","何以佐盘餐，江鳞春正肥。","命酌长松下，清音宛竹丝。","菰芦得生计，鸥鸟更何机。","泛泛忘归路，冥烟失鱼矶。","愿子惜欢会，念此流光移。"]},{"t":"春园雨后漫赋","f":"五言古诗","c":["时序递催迁，人事何能常。","幸兹休假馀，聊以恣徜徉。","园林有百卉，当春发其芳。","抽红亦吐白，间杂固无行。","数日苦霖潦，主人卧匡床。","不得恣游赏，兼亦负壶觞。","归云收绪雨，晚飔开微阳。","会心岂在远，即此足回翔。","信履悦情志，应接如苦忙。","偶得谢物役，因之媚景光。","悠悠世上名，于我亦何当。"]},{"t":"三月三日与客泛舟","f":"五言古诗","c":["又是暮春初，和畅来惠风。","远寻脩禊迹，遵渚扬小艟。","何必会兰亭，少长亦已同。","水满混天高，舟行坐镜中。","虽复在桑梓，俨与灵境通。","海鲔跃旋湍，风鹘磔深丛。","鳞羽各自欣，人生复何庸。","彭殇不待齐，委运得从容。","斯意苟冥会，当尊莫放空。"]},{"t":"花县霞觞八景为王明府赋 其一 委羽淩霄","f":"五言古诗","c":["尝读道书言，兹山大有天。","霞光建标起，赤城紫气连。","中有神仙人，跨鹤淩苍烟。","苍烟不可扪，遗响九皋传。","会当排阊阖，霓裳朝至尊。"]},{"t":"花县霞觞八景为王明府赋 其二 灵洞桃花","f":"五言古诗","c":["蟠桃不可植，茫茫度索山。","何似兹天台，灵洞辟人间。","桃花四运然，流水常潺潺。","灵媛嘉良觌，手贻胡麻餐。","快哉仙灵居，长生安足言。"]},{"t":"花县霞觞八景为王明府赋 其三 罗浮炼丹","f":"五言古诗","c":["东南富名山，罗浮佐衡霍。","悠邈涨海外，仙灵于焉托。","眷兹神仙令，栖真炼大药。","觉世有真言，要旨在抱朴。","穆如播仙风，岭表畅玄漠。"]},{"t":"花县霞觞八景为王明府赋 其四 天汉飞凫","f":"五言古诗","c":["峨峨宫与阙，迢迢望玉京。","泠风难为御，羽翼不可生。","翩翩飞双凫，振翮淩青冥。","网之但朱舄，灵蜕已化形。","相将朝玉皇，香案侍太清。"]},{"t":"花县霞觞八景为王明府赋 其五 松门耸翠","f":"五言古诗","c":["南山多老人，邀游东海间。","化身为苍松，风涛响佩环。","下有琥珀脂，上有虬龙颜。","世上辟谷儿，从之相往还。","右军纪游辙，千载映兹山。"]},{"t":"花县霞觞八景为王明府赋 其六 天台应宿","f":"五言古诗","c":["山岳奠坤维，星辰散乾精。","超然天台山，奇挺指天庭。","上应中台尊，元气混象形。","迎曦启万始，潜景昔群灵。","宁为百里耀，会见泰阶平。"]},{"t":"花县霞觞八景为王明府赋 其七 箨山献瑞","f":"五言古诗","c":["凤凰有至性，非竹实不食。","灵文衔九苞，出为邦家瑞。","寂寥高冈后，竹山显灵异。","乃发明王梦，览德而下视。","谁道王风遥，请看凤鸟至。"]},{"t":"花县霞觞八景为王明府赋 其八 玉京芝草","f":"五言古诗","c":["金庭表临海，华芝产其阳。","覆云纷五色，浥露炫九光。","何当辟火粒，采拾随风翔。","仙人字远游，寄语王家郎。","服食理无误，携手入紫房。"]},{"t":"三月初十日见盘莲花贻伍子","f":"五言古诗","c":["百卉含生意，应候乃发萌。","暮春启初月，春花吐其英。","桃李及杏柳，华林递主盟。","赏未罄春敷，望岂逮夏荣。","眷言此泽芝，天留绚朱明。","斗芳一何忙，早挺当春茎。","露凝犹苦寒，水映初泮冰。","欲制以为裳，将嫌春服轻。","西施在若耶，春游炫相矜。","昨岁爱花好，白花红绿骈。","今岁怜花早，花神有何灵。","寄与褰芳人，涉江若为情。"]},{"t":"洗耳泉","f":"五言古诗","c":["我闻唐虞代，乃有巢与由。","逃荣若避垢，洗耳谢九州。","罗山多飞瀑，鸣玉漱清幽。","岩石俨异搆，眷言隐士邱。","坐听尘嚣尽，岂必濯其流。","我来景高风，咫尺不可求。","因思咏沧浪，清浊各自酬。"]},{"t":"罗浮杂咏 其一","f":"五言古诗","c":["罗山奠南岳，高高与云齐。","浮来有灵迹，托体合蓬莱。","上界无垢尘，中阪分丹荑。","脩炼诸仙人，飙车白日驰。","我无化龙杖，安能登云梯。","长歌聊采芝，眩然心已迷。"]},{"t":"罗浮杂咏 其二","f":"五言古诗","c":["久矣困物役，兹焉出人寰。","数日住兹山，俨在蓬瀛间。","虽复费登陟，不碍幽意閒。","朝竞樵采往，暮伴牛羊还。","归洞不闭门，夜听流水潺。"]},{"t":"罗浮杂咏 其三","f":"五言古诗","c":["飞云高际天，上有两石楼。","大小遥相望，宫阙与云浮。","鸾驭倏飘举，恍见烟客游。","杖策一振衣，俯视淩沧洲。","神州与赤县，何乃不盈坏。"]},{"t":"罗浮杂咏 其四","f":"五言律诗","c":["凤凰浴西谷，文彩何相鲜。","五色承云气，饮食常自然。","在昔圣人出，尔乃鸣岐山。","千载览德辉，会当复来还。"]},{"t":"罗浮杂咏 其五","f":"五言古诗","c":["昔日稚川子，勾漏远求丹。","大药不误人，九还得驻颜。","荣途信自膻，中怀非所安。","薤露望晨晞，那能复盘桓。","大运一以去，临期但长叹。"]},{"t":"罗浮杂咏 其六","f":"五言古诗","c":["行行御凉风，乃过铁桥西。","落照映彩霞，石梁跨虹霓。","我欲往从之，烟雾急以迷。","安得徒步女，携手驾云螭。","长怀采药人，日暮当何归。"]},{"t":"罗浮杂咏 其七","f":"五言古诗","c":["灵乳漱云根，奔流百道咽。","悬泻垂珠帘，激飞纷玉屑。","叩斧更负铛，斸云煮山月。","幽籁因风答，清商四垂发。","一啜烦渴消，冷然中心悦。"]},{"t":"罗浮杂咏 其八","f":"五言律诗","c":["反步梅花村，徘徊意萧索。","翠羽自喧喧，淡妆人己寂。","玉女向余笑，皓齿启历历。","蹇修时不来，怀思竟何益。"]},{"t":"罗浮杂咏 其九","f":"五言古诗","c":["凉风吹日夕，瑟瑟洞门阴。","零霜彫百卉，菁华苦寒侵。","我生无根荄，老至谁能任。","羲和不可顿，已秋非复春。","愿作淮海禽，变此朝露身。"]},{"t":"罗浮杂咏 其十","f":"五言古诗","c":["桂树生神湖，花开白于玉。","不为寒风零，岂受膏雨沃。","陋彼东园卉，繁葩何簇簇。","润泽不可常，栽培有倾覆。","卓哉世外姿，君子固所服。"]},{"t":"西樵山中偶成","f":"五言古诗","c":["于时泛长策，眷怀在山水。","自与缨绂违，幽奇恣探采。","昔陟罗浮东，句曲溯仙胏。","兹复西入樵，林峦洵云美。","息徒野老家，数椽万山里。","日落列峰高，天寒归鸟驶。","看云扬妙词，听泉涤尘耳。","同行畅欢踪，独往味深旨。","顿觉寡云为，中怀澹于洗。","寄语市朝人，岩穴足高趾。"]},{"t":"白云洞","f":"五言古诗","c":["坠危意几疲，遘奇情乍适。","所遘非一态，风日饶异色。","登陟未忍竟，徬徨坐水石。","冥搜意转增，乃穷神怪极。","木末度孤亭，穿云及山眷。","蒙泉有妙理，泠泠分崖滴。","万丈长虹垂，阴岩寒气逼。","穴石流逾驶，泛觞界为席。","念奢希遍收，耳目时若失。","彼美应有托，予来乃无得。","日夕逐侣归，徘徊意不释。"]},{"t":"碧玉洞","f":"古风","c":["幻窅通一鏬，混沌辟何年。","目贪神怪观，刺衣下层巅。","猿缘矜巧捷，鼓壮若无先。","疲足毕欹险，骇目忽洞天。","石门长不关，浮梁架蜿蜓。","纳云俨奇搆，选石漾清涟。","仰视激飞湍，万仞泻溅溅。","映日金膏闪，晴檐霏雨烟。","泠泠时中赏，瀰瀰使众怜。","天乐俨?谹，奚必竹与纮。","胜纷目屡换，神往虑亦迁。","安得长兹游，身世两相捐。"]},{"t":"与伍国开游仙隐岩","f":"五言古诗","c":["混沌閟幽奇，元气未开扩。","瀑虹万丈倾，泠泠潴深壑。","仰视半岩扉，一线通微凿。","俯入别有天，万巧纷然作。","日光闪金铺，蒸霞成丹艧。","嵌空玉玲珑，神工何代削。","灏气羃濛濛，寒色生回薄。","山灵若待人，兹游应有托。"]},{"t":"留别定国侄","f":"五言古诗","c":["从子吾家彦，气骨负高奇。","少小同铅椠，古道相与期。","及予返休沐，竹林日追随。","两雏赖教植，余亦借箴规。","兹余复行役，相别出江湄。","江湄深且浩，不及中所私。","予游云已倦，汝策未逢时。","日月不待人，行路苦逶迤。","鴳飞抢榆枋，鸿羽渐云逵。","黾勉事功名，莫使叹衰迟。"]},{"t":"结客少年场","f":"五言古诗","c":["驽骀恋皂栈，骐骥怀鞭弭。","丈夫志四方，那能牖下死。","羞食五侯鲭，宁倒七贵屣。","一片热肠肝，所重酬知己。","宝剑千金装，解赠不留视。","杀人睚眦间，腥血染刀几。","一朝赴国难，捐躯以自矢。","朝出蓟门城，夕斫单于垒。","荡寇指顾间，无烦折尺箠。","功成解铁衣，伏阙报天子。","鹊印不愿垂，受赏乃所耻。","愿戴边胡缨，遨游贵戚里。","叱吒风云生，金貂供役使。"]},{"t":"谒严祠因登钓台二首 其一","f":"五言古诗","c":["陟彼富春山，紫翠何重重。","荒祠奠幽趾，高台倚晴空。","缅昔白水兴，群策起从龙。","夫子秉逸尚，垂纶抗高踪。","人远云山新，世异江水同。","我来一振衣，万里披清风。","斯人不可作，三叹将何从。"]},{"t":"谒严祠因登钓台二首 其二","f":"五言古诗","c":["凤凰起高冈，千仞翔漻泬。","陋彼鸱与鸮，乃为腐鼠嚇。","卓哉尘外踪，中区何窘窄。","唐虞总刍狗，箕颍亦戏剧。","所贵达人心，不留空中迹。","一笑桐江丝，中怀自脉脉。","千载仰辉光，江湖星是客。"]},{"t":"既出都门望西路发有作 其一","f":"五言古诗","c":["靖端肃王程，驱车向西骛。","既惬游梁情，亦适归欤趣。","岂复惮倭迟，孤征昔所屡。","晨徂每侵星，兼途轻薄暮。","时序如崩波，黾勉促脩路。","朔风剥我肤，宁论衣改素。"]},{"t":"既出都门望西路发有作 其二","f":"五言古诗","c":["谁令渝高蹈，怀禄入承明。","十载铅与椠，悠悠竟何成。","情澹圭组薄，恋深犬马轻。","远辞承华侧，秖役潞子城。","衔命俨陨越，敕躬每屏营。","揽衣遵遥渚，整辔骛脩坰。","岭南隔天末，何日抗归旌。"]},{"t":"留别示两儿","f":"五言古诗","c":["吾家代力耕，繄予忝禄仕。","五世有遗泽，浚发将在此。","五十而无闻，祖德惭济美。","饰躬良已难，何能逮小子。","孩抱重相违，况兹八千里。","我行难久留，汝还敦素履。","尘案有缣缃，北堂有甘旨。","稼好课田畴，兰宜植庭戺。","饮酒俨立监，披书穷杪理。","少壮能几何，流光去若驶。","令德抗前旌，周道平如砥。","庭训苟不渝，天涯膝下尔。"]},{"t":"圯上怀留侯","f":"五言古诗","c":["骊颔不探珠，空拳不搏虎。","如何张子房，愤激不返顾。","危哉博浪椎，幸脱秦刀俎。","鬼神发素书，授以圯桥父。","六韬运奇筹，亡秦而蹙楚。","区区一片心，侯封非所慕。","长谢隆准公，终逐赤松去。","千载迹未陈，经行景高矩。"]},{"t":"初秋同王季重李立素游莫愁湖","f":"五言古诗","c":["嘉陟讵云逖，有美湖上台。","驾言送远行，复得旷中怀。","朋好来不速，徒御亦无猜。","主人眷佳会，日晏出尊罍。","微飔涤烦暑，命酌尘襟开。","吴童发妙讴，丝肉终宴谐。","抚景能无赋，愧乏和客才。","含情俱未申，眄晷忽已颓。","何以永兹游，长歌意徘徊。"]},{"t":"餐菊","f":"五言古诗","c":["秋深严候早，百卉望霜零。","挺此东篱花，灿灿抽芳荣。","气为淩寒健，香以饮露清。","开尊酬嘉宾，采采此日情。","金光炫琥珀，芳馥沁心灵。","昔闻甘谷水，饮者体能轻。","亦有朱孺子，服之乘云升。","幽香自吾媚，岂必慕长生。","聊学楚骚人，日夕餐其英。","时念柴桑下，悠然处士情。"]},{"t":"送陈子明归省","f":"七言古诗","c":["我昔读书仙石城，与君一见快平生。","别来荏苒六七载，自结烟霞物外盟。","宾鸿社燕遥相望，剡曲多君移雪舫。","春来水国百花开，舍北舍南俱共往。","遂令意气转雄飞，登坛鞭弭托驱驰。","看花题鸟怀俱适，玩水登山乐忘归。","自许襟期真不负，那知风雨易前期。","浊醪几向习池尽，白日不为鲁阳挥。","朔风一夜寒江阁，吹君归梦绕乡国，脂车秣马不迟回。","执手歌骊空索寞，满眼江梅未著花，赠行虚折一枝斜。","花开后会谁同赏，翘首三城隔暮霞。"]},{"t":"赠唐寅仲先生","f":"古风","c":["君不见，严陵披裘大泽中，蒲轮三反至帝宫。","汉家天子不能屈，自言远慕巢由踪。","富春山中把钓去，高风千载何轩举。","凤凰自是淩霄姿，肯与鸣鸮争腐鼠。","先生一代之人伦，高致严陵可共论。","早制荷衣返初服，翛然挥手谢时人。","平生侠气更无伍，睨傲不趋丞相府。","将军折柬不能招，俗吏一挥何足数。","年来嘉遁在青门，身隐名藏道逾尊。","经翻柱下五千字，草拟玄亭几万言。","吾生自叹时已后，风流先辈多彫朽。","橐鞬今得奉先生，犹向前修识领袖。","流水钟期调未遐，及门文举是通家。","石床读罢西游草，松林如起赤城霞。","十载登龙恨不早，宁得交欢还草草。","眼前世事未堪论，杯底清言且绝倒。","吁嗟人生万事总浮尘，蜥蜴为龙恐未真。","呼马呼牛何足问，先生定是千秋人。"]},{"t":"赠邓伯乔","f":"古风","c":["一时文藻盛炎陬，作者纷纷大雅俦。","到处珠光誇合浦，握中谁更擅随候。","眼底之人皆若此，意气吾怜邓伯子。","世人铅刀子镆铘，断犀剸兕毫光紫。","任是星文在匣中，四射精光谁可迩。","我本烟霞落拓一狂夫，混身久作高阳徒。","壮怀未惬千秋赏，逢人双眼但糊模。","与君会面胡不早，把臂片言便倾倒。","流水何期遇赏音，挥杯兼得开怀抱。","春风载酒越王台，秋日题诗仙石岛。","越台仙石事已非，感时怀古一歔欷。","丹砂葛稚今何在，黄鹤安期去不辟。","何况荣华过眼电泡耳，逐逐营营何所为。","怜君本是冥搜士，我亦风尘高逸致。","有身肯受樊笼羁，有心会解幽中意。","鱼乐唯应惠庄知，濠梁且共论秋水。"]},{"t":"自五羊馆归伍国开有开招同何詹冯诸子饮山下园亭","f":"古风","c":["西风萧瑟秋气清，明霞片片落江亭。","主人载酒园林里，旧好新知喜合并。","忆昔别君芳草尚青青，君留驼岭梅花宅，我访仙人五石城。","每恨春花不同咏，何期秋月照人明。","春花秋月须臾易，回首韶光真可惜。","此日相逢当尽欢，何况饮中尽是高阳之狂客。","何生荦荦迥无伦，酒后凭陵气愈振。","君家风雅驰声早，散发披头也自好。","詹生潇洒拔俗姿，冯生楚楚亦慕奇。","风流已自足千古，意气飞扬复一时。","我欲为君洒酒问东篱，桂花已发菊花何迟。","我欲为君舞长剑，剑光四射何陆离。","银河倒压星辰垂，值此秋光烂醉复何辞。","只恐白龙今已驾，六蛟羲和控驭去如飞，对酒当歌易转悲。","不若与尔乘风上天，直把白帝羁长系，清光照酒卮。","更须尽挽天河水，洗尽人间是与非，不违红尘一事违。"]},{"t":"送黄与东上春官","f":"古风","c":["黄生负才何豪雄，风姿矫矫如虬龙。","三十明经贡上国，四十贤书奏海东。","丈夫逢时何必早，电泡荣华安足道。","君今出山未是迟，肯使世人嗤小草。","忆昔与君结社粤山傍，鞭弭同时有二黄。","联翩已决青云去，落落予犹愧雁行。","年来事异时逾改，生计飘零未可耐。","苫块伤心万事灰，虚论龙剑馀光彩。","浮云日夜东南驰，谁道河流清可待。","看君老骥复骄嘶，云逵万里试霜蹄。","碣石之宫何嵂崒，黄金台上草菲菲。","君去谈天谁可拟，炙毂雕龙枉自奇。","送君行，酌君酒。","功名拾芥君何有，丈夫所志还不朽。","眼底悠悠荣利儿，请君还问千秋后。","一别宁堪雨坠天，雄心忽复觉翘然。","柳色蓟门春又绿，好音早寄慰风烟。"]},{"t":"送何龙友赴公车","f":"古风","c":["何生负气何昂藏，弱冠挟策游帝乡。","浮名唾手未足数，横襟一世神飞扬。","忆昔与君结社事文章，抗怀真欲溯羲皇。","居然一日千秋事，雕虫肯竞少年场。","君原神物韬逾烁，我亦雄心挫不降。","浮云苍狗怜生事，瞬忽令予百感伤。","三秋伏块馀鸡骨，九折行路叹羊肠。","雌伏雄飞浑不定，青云且喜尔翱翔。","囊携一剑芙蓉色，侠气凭陵燕市傍。","公车不少挥毫士，决江排海非其长。","珷玞荆璞从教混，周客终然辨夜光。","榆枋飞抢自斥鴳，千仞翱翔美凤凰。","送君此日上河梁。","浊酒勤君再一行，十载同君共梓桑。","君先壮游事四方，俯仰宇宙何茫茫。","丈夫所志岂但功名富贵，文绣膏梁努力共期三不朽，铭勋彝鼎与旂常。","天明酒尽君当往，彩虹十丈吐光芒，君行聊赠作帆樯。"]},{"t":"初夏与戴公纶伍国开有开暨定国安国侄泛艇随意泊饮即事放歌","f":"古风","c":["入夏半月炎已多，故人挥汗来相过。","避暑好寻河朔饮，况爱前溪新绿波。","小僮撑艇未惯习，颇嗔潮流太驶疾。","沿岸时将荻苇牵，乘凉聊借榕阴集。","儿童群戏浴江隈，田家作苦晚归来。","邂逅量晴还较雨，便呼浊酒倒深杯。","盘餐野外何所有，虾菜还堪村妪市。","尊中有酒幸不空，鼎食华堂亦复尔。","君不见来时隔浦生白云，滃郁变幻何缤纷。","晚风吹入沙汀去，长空如洗净无尘。","又不见此时隔岸归巢鸟，茂林争集枯林少。","浦云江树本无期，聚散升沈已若斯。","今日与君扁舟对举卮，当歌不醉更何为。","人生行乐会有数，百年枉受樊笼羁。","迩来颇悟谋身术，便欲长歌与世辞。","昨摇桂楫访南墅，今鼓兰桡向西渚。","日日菰芦寄此身，幽怀莫共时人语。","饭煮香芹腹果然，夜乘清风且归船。","江鸥相对休相讶，吾曹已结海翁缘。"]},{"t":"伍徵君有驯鹤纵其飞集虽数十武外闻主人呼声即返因赋","f":"七言古诗","c":["青田之野孕灵姿，胎化仙禽种自奇。","暂游小泽离江海，旋掩云罗遂见羁。","临风未铩淩霄翅，作玩人间亦偶尔。","稻粱虽重肯怀恩，延伫阶墀顿脩趾。","相怜不用卫轩乘，回首辽城路杳冥。","喜有开笼当夜月，何妨轩举振脩翎。","横空一叫声嘹唳，四望苍茫失洲屿。","顾影时追旧侣群，闻声还认主人语。","主人负质水仙灵，王子曾传相鹤经。","他日吹笙缑氏岭，跨尔烟霞物外行。"]},{"t":"送韩绪仲太史先生还朝","f":"七言古诗","c":["传道上林花事好，何似罗浮花更早。","未腊山梅万树开，应知是处春先到。","羡君家在罗浮西，焚鱼三载碧山栖。","看花忽忆上林苑，驿路风光催马蹄。","蹇余托乘交游后，月下诗篇花下酒。","此日从君到上林，春花能与同看否。"]},{"t":"度岭寄呈座师陆从先先生","f":"七言古诗","c":["昔年梦想庾关胜，此日初探岭上春。","驿路渐看征骑远，梅枝先寄授经人。","忆余少小怀孤尚，雄心直抗千秋上。","风尘落落十馀年，谁复百金酬澼絖。","明月从教按剑疑，白雪终投郢客知。","不但风云逢遇合，还将山水对襟期。","从此孙阳垂一顾，骥尾青云高自附。","万里初腾伏枥躯，八荒任纵追风步。","辞行犹未入增江，缟带先投珠浦傍。","近腊沐霜随处满，遥天鸿雁自成行。","庾关此去长安迩，黄金依旧悬燕市。","敢道浮名致此身，且抗前旌报国士。","珍重缄题转自怜，绛帷回首思茫然。","帝城夜望郎星耀，南海应知凤凰传。"]},{"t":"玉署读书歌","f":"古风","c":["玉堂去天近咫尺，缭绕卿云常五色。","晓来丽日映花砖，铃索无声清昼寂。","人间别自有蓬瀛，灵文秘轴满檐楹。","东壁图书真有府，西园翰墨岂虚名。","繄余夙昔怀微尚，十载菰芦徒向往。","此时趾美预英游，一任玄珠探象罔。","鸾坡通籍尽名流，师儒更是吕伊俦。","帝里德星容易聚，真人紫气望来浮。","校籍藜光回太乙，抽毫文藻盛千秋。","明时肯重浮誇士，书麓□人徒尔尔。","平生壮志敢轻酬，况有高山堪仰止。","堪仰止，更何疑，努力云霄致此身，夔龙勋业彼谁子。"]},{"t":"金台行","f":"七言古诗","c":["广阳城东古燕都，春风吹绿乱平芜。","山河灵气有迁换，万年定鼎见雄图。","大漠天高风雨暗，胜迹前朝未可呼。","昔日燕昭好贤士，黄金筑台从隗始。","碣石谈天事有无，能使君王勤拥彗。","乐生一鼓下齐城，故鼎大吕入燕庭。","誓屠莒墨酬恩遇，骑劫何来代绾兵。","飞书恨绝聊城矢，千载虚悬下士名。","黄金已没骏骨朽，汉晋茫茫岁月久。","扶舆有待閟精灵，代历金元豺虎吼。","皇家开运应中天，明良际遇信无前。","八弦顿掩三驱网，何用黄金招儶贤。","麒麟钟鼎人应有，斗大黄金系于肘。","千里骅骝会致身，台中之人今在否。"]},{"t":"初寒念边戍","f":"七言古诗","c":["边关十月朔风起，吹冰夜合滹沱水。","极望阴云冻不飞，白草黄砂连万里。","久戍征人马少肥，祁连山下雁鸿稀。","闺中少妇无消息，节过寒霜未授衣。","胡笳断续声凄咽，一听一回魂欲绝。","幕府朝朝奏羽书，戍楼夜夜披金铁。","更值匈奴数犯疆，缘边烽火接长杨。","孤军度碛行还蹶，万马嘶风起复僵。","蓟门城外君恩远，蓟门城中春光满。","侯家韎韐紫貂轻，戚里氍毹绣凤煖。","紫貂绣凤岂知寒，霜威不到画栏干。","谁念征人凄堕指，长嗟生入玉关难。","上将提军先作忾，挟纩投醪多猛士。","筹边圣主正宵衣，内帑金钱应早赐。"]},{"t":"邹县谒孟夫子","f":"古风","c":["邹峄城南二三里，土垣茅屋多倾圯。","岿然丹垩庙貌存，云祀邾公孟夫子。","夫子生当战国年，凋残圣绪已如线。","砥柱澜回洙泗脉，分庭礼抗侯王前。","提醒人心起大寐，直在鸡鸣夜气先。","谁云五世泽旋改，绝学微言开万代。","千秋遗像切瞻依，岩岩璧立风犹在。","散步庭除重所思，森森桧柏影参差。","修干昂霄枝复偃，谡谡清风晚更吹。","奔涛似听风雷走，夭矫尽作虬龙姿。","乔木由来称故国，鬼神呵护有如斯。","君不见死士垄，犹胜生王头。","贵贱枯荣总一邱，何物人间称不朽，宫墙宇宙共悠悠。","又不见当日雪宫与齐囿，独乐何知民疾首。","只今芳草尽离离，惟见牛羊牧竖走。","夫子屈伸道合时，位是宾师身布衣。","后车未厌传餐侈，滕馆从教窃屦疑。","始知众人不识，道固委蛇。","我来稽首亲瞻百世师，何必闻风想惠彝。"]},{"t":"冬日同何似公伍国开有开暨仁伯弟定国安国侄驼山寻梅赋","f":"古风","c":["昔曾京国看梅树，盘里疏条映雪清。","一枝两枝移近案，四筵宾客酒同倾。","尔时作客空相忆，梦魂几越驼山侧。","驿使迢遥书寄稀，罗浮月冷无消息。","自从休沐返林邱，赏心还逐旧同游。","同游多住梅花畔，千花万花开陇头。","地无冻雪香风暖，近腊冲寒枝乱抽。","与君携斗酒，日暮访山门。","命酌梅花下，繁香扑酒尊。","花神莫笑归来客，芳尊无恙对芳园。","年年花事看仍好，及此同游人未老。","少壮几何已及强，宁得看花还草草。","已愁飘落晚风欺，莫更前溪长笛吹。"]},{"t":"明月篇","f":"古风","c":["长安月，盈盈上宫阙。","始看东岭吐灵辉，渐见中天流景烨。","寂寞三秋望河汉，迢遥万里亘晴空。","长衢绮陌三千户，大道青楼十二重。","澹云疏皎皎，红蕊漾溶溶。","澹云红蕊中宵湿，尽借月华生彩色。","卢龙塞外玉为砂，鳷鹊鹳头金作翼。","杨柳笼烟万缕寒，芙蓉濯露千茎出。","飞盖西园夜夜招，开尊北海年年客。","年年夜夜美遨游，绝胜清光在九秋。","微茫锦渚烟初散，澰滟金塘波乱流。","鹤笙未过缑山驭，凤管先吹弄玉楼。","吴女临风歌白纻，燕姬隔岸奏箜篌。","别有深宫深似海，长年长照孤轮在。","葳蕤空自锁春风，玉辇何由望光采。","沟畔虚劳红叶题，长门误托黄金贿。","千年灵药姮娥奔，七夕明河织女待。","银蟾捣练影成空，乌鹊填桥云散彩。","人间天上两茫茫，秋月秋风总断肠。","谁家思妇能安寝，若个征人不望乡。","可怜塞上眠沙漠，可怜闺里罢流黄。","掩映画屏张孔雀，参差碧瓦甃鸳鸯。","此夜空房那忍归，此时玉箸一双啼。","啼痕但渍香闺枕，缄书不到玉门西。","书寄刀头犹可待，梅发罗浮梦已迷。","三五团圆难得久，二八盈亏当自守。","任教霜露冷沾衣，恨少清辉览盈手。","手揽清辉独倚阑，屋梁斜照夜初残。","低徊更听关山月，魂断千山与万山。"]},{"t":"仲夏与安国侄泛舟访伍国开兄弟因携酌前林大醉放歌","f":"古风","c":["炎天五月胜炮烙，行人挥汗如泉落。","伹见摩肩向市门，若个持杯问河朔。","河朔风流事杳然，空有避暑杯堪传。","当时袁景升辈碌碌何足数，始知解饮亦称贤。","伍生与予共桑梓，天下一人足知己。","琴歌酒德日相呼，时日不见萌吝鄙。","怜予习懒掩柴关，生亦高卧飞驼间。","偶命扁舟过一水，访戴宁教兴尽还。","舍舟缓步寻所适，短桥过去稀人迹。","与生林下解衣冠，分得海鸥一半席。","远山隐隐送鸣泉，长松落落凝寒色。","侍儿调喉叶清丝，谱入词人乐府诗。","曲罢黄鹂答睍睆，谡谡清风林外披。","伍生伍生好为听，我拚为汝醉金罂。","来时赤日方亭午，俄看皓魄东方升。","从君千日戒涓滴，小伍常戒酒今夕何堪负月明。","世路风波浑不定，升沈聚散总浮萍。","天生七尺会有用，斥鴳榆枋何足菅。","伍生伍生不用忧成名，只今辽阳蓟北处处勤天兵。","纵然前席轻年少，未必关门负请缨。","看君怀才何峥嵘，看君负气何纵横。","谩论出则为小草，我辈所愿非浮荣。","黄石赤松终有分，会使侯封脱屣轻。","脱屣侯封亦何有，容易故园今聚首。","痛饮兹宵肯作难，兴剧应尽十千斗。","醉来送我出前山，旷野茫茫星汉走。"]},{"t":"寄何龙友","f":"古风","c":["君不见，南山玄豹雨雾藏，七日不食泽文章。","又不见，羽翼缡褷双凤皇，灵文哕哕鸣朝阳。","丈夫出处自有时，时俗之眼讵能量。","与君共乡闾，少小敦意气。","共许百年身，无负千秋事。","屈首为文章，调必追正始。","双眼不肯向时人，时人但谓此狂耳。","呼马呼牛任此身，十年落落在风尘。","我怜匏系青襟后，君亦公车困几春。","六载之前予献策，忝窃金门待诏客。","不那烟霞疾转生，翻向秋风理归翮。","去年君复上公车，气色青云倍发舒。","赠句雁行吾分让，伫君龙跃起天衢。","君才早负千人敌，一奏淩云薄子虚。","春风得意长安道，马蹄蹀躞看花早。","捷书三月到菰芦，菰芦有人欢欲倒。","千载贡王事岂遥，弹冠意气为谁骄。","功名富贵祇长物，何物不朽垂壤霄。","看君期许非流俗，会作夔龙翼圣朝。","独有野人高卧癖，一别金门岁几易。","老大空怜报主身，疏慵未策追风力。","若逢故人问野人，为语蒲团已枯寂。"]},{"t":"鳌顶云峰","f":"古风","c":["君不闻渤海之东几万里，大壑之下深无底。","五山上下随波摇，巨鳌戴之始列峙。","龙伯大人太无聊，举足一钓连六鳌。","六鳌移住关山下，擎出仙山万仞高。","仙山万仞表灵胜，峰峦奇绝非人境。","丹炉一秘几千秋，时出白云相掩映。","中有仙人学驻颜，曾为云云施人寰。","鳌柱大明擎日月，功成拂衣归故山。","只今秋风渐长秋山蕨，丹枫白云几起忽。","西母时传周穆谣，居人但解自怡悦。","白云岁岁自鳌峰，圣朝何用侈登封。","老相未教云卧稳，更看风雨促从龙。"]},{"t":"龙潭瀑布","f":"七言古诗","c":["黄蘖山高高压云，香炉矗天天氤氲。","上接银河三千尺，澎湃奔流万壑分。","潜通地轴昆崙底，惊醒龙湫龙卧起。","洪涛一喷万灵从，散为浓雾遍囊中。","春耕千里怜赤土，雨雾处处足三农。","阴旸辘轳任舒卷，忽尔澄空天宇见。","随云出岫木无心，乘风归山意更远。","山灵开凿自天奇，雪窦泠泠镇日垂。","青崖似激疏星落，阴洞疑连细雨飞。","真人高卧山之麓，勋名撒手还初服。","漱流枕石有馀閒，万里龙潭供濯足。","洗耳何须傲颖箕，乘槎还欲访支机。","仙源未遣跨龙去，圣代犹思载渭罴。"]},{"t":"宿飞云顶放歌","f":"古风","c":["绝巘邈无伦，罡风通上界。","仙家鸡犬隔尘寰，物外烟霞开罨画。","我来红日下山阿，千山万山发光怪。","俯视长虹百道奔，峰峦四百如儿孙。","金光玉乳相闪烁，一一倒景射天门。","神怪搜穷耳目换，耸身大诧天地昏。","尘中讵肯轻回首，苍苍之色如可扪。","奇石堪帏草堪席，余亦意尽聊偃息。","别有神游非梦游，子期鲍靓如相识。","问子何事闹仙都，踏破飞云纷五色。","稚川仙后谁复来，将子白日能生翼。","余谢身前本列真，谪向人间几度春。","朝簪虽贵非所适，愿返三清礼玉宸。","凭君指点来时路，相逢云水亦前因。","二真闻词颔而许，一笑解颜重致语。","之子无忘旧本根，花落水流终有处。","再向阎浮了世缘，清浅蓬莱终待汝。","觉后相疑思未安，复惊海日涌红澜。","山腰四望犹昏黑，下界三更更未阑。","因知俗骨予未了，山鹤一声天渐晓。","强寻旧路再下山，赢得烟云衣袂绕。"]},{"t":"登麻姑台","f":"古风","c":["杖藜随意出花间，散步麻姑百丈潭。","潭上琪花与瑶草，一一金光映客颜。","云舆凤辇不可即，空听天风落佩环。","手自揖麻姑，长笑振衣起东望。","蓬莱浅且清，阅世沧桑聊复尔。","我生安敢望神仙，野性由来厌俗缘。","此曾登临何地复何日，只见秋山历历楼台白玉淩苍烟。","四十劳生虚自度，到此不觉心茫然。","须臾红日已西昃，览眺徘徊重叹息。","四大此身何所归，安得淩风就双翼。","神楼灵散若可逢，长与人间辞谷食。"]},{"t":"赋得卫敬瑜妻为姚太史节母","f":"古风","c":["兰蕙为芳柏为节，机杼盈霜襭盈月。","卫家有妇年十馀，夫婿一朝成死别。","植来墓树尽连枝，岁月春秋屡改移。","自去自来江上燕，年年还向屋梁飞。","生命不辰那复怨，偏栖并及飞来燕。","含情相念转相怜，密意隔年传缕线。","岂为酬恩感故人，由来匪石心难转。","卓哉妇义挺千秋，纲常道丧世悠悠。","谁似姚家生太史，母德岂但襄阳俦。","二十藁砧亡，诸姑在乳哺。","非难地下从衰门悬一缕，艰虞况复百忧煎。","未亡之人当门户，茫茫谁为问穹苍。","手鞠遗孤日正长，孤理遗编母理织。","相对寒檠夜未央，跳丸得似流光疾。","四十馀年如一日，一朝太史振家声。","天赉皇家作良弼，始知大贤奋迹自多奇。","是母故能生是儿，鸿鹄育成苞凤彩，此志宁教燕雀知。"]},{"t":"将出都留别董玄宰先生","f":"七言古诗","c":["玉皇香篆隔云间，掌篆仙人第一班。","因风吹落人间世，霓裳五佩声珊珊。","胸罗十方金世界，掌挥寸管莲花斑。","灵驱丁甲山魈走，光寒鲛浦夜珠还。","万言虎观倾多士，片字鸡林购百锾。","娥眉自诲宫中妒，宦迹烟霞随杖屦。","作赋翻缘览胜工，抽簪未遣谋身误。","一朝撒手谢时人，洞庭归领烟蓑去。","世事总如敝屣轻，生涯且向团蕉悟。","域内名山处处探，天边羽盖时时遇。","君心欲结赤松盟，世轴终需岩筑雨。","一诏东山起谢安，草堂人去薜萝寒。","猿鹤三秋惊蕙帐，凤皇千仞振苞翰。","一夔自典虞庭乐，六馆人沾化雨宽。","于时圣主在承明，金门玉署满群英。","未论黄阁丝纶倚，且喜词林气色生。","人间山斗归韩愈，天下龙门仰李膺。","繄予束发怀微尚，希心远抗黄初上。","踪迹虽怜世网婴，襟期未肯时人傍。","平生闻有董先生，吴粤迢遥空伫望。","金马何期此聚星，骥尾青云堪鼓壮。","一见翻轻万户侯，兰茝兼怜意气投。","物外白云期有待，握中明月许相酬。","朅来神物无常合，又看风雨判吴钩。","暂借星华窥泰华，终谋远志卧罗浮。","君是三朝旧名宿，舟楫盐梅今有属。","世去宁妨出世身，会调元气归衡轴。","子房范伯彼何人，霸越兴刘何赫煜。","一从黄石一鸱夷，神仙岂受勋名刺。","饶余汗漫二十春，绿野君归堂正新。","倘许扁舟寻匹练，共向吴山学隐沦。"]},{"t":"太行山放歌","f":"古风","c":["君不见，神工开凿留禹迹，太行恒山至碣石。","西北天倾补未完，芙蓉片片破空碧。","山形雄跨卫通燕，星野横分室与璧。","仰视崛岉盘郁纡，矗上去天不满尺。","朔风泠泠万古寒，阴崖冻壑长夏雪花霏不息。","南望仙山隔五台，九折何人叱驭来。","猿猱攀援尚不得过，周家穆天子，胡为驾八骏而至哉。","景阳石英今已矣，王烈青坭不可遇。","山中寂寂，谁从东北更闻雷。","服食求仙多所误，到此三叹使人哀。","怜予小草别罗浮，曾从匡庐天目游。","皇州西樵石室几席耳，洞庭彭蠡供糟邱。","玉节今回自上党，经过此地，顿开生平未见之双眸。","呼吸通玄真，有谷下俯翠屏，五封昼锦封龙，何啻海上之浮沤。","生来两足耐崄巇，惯骖虎豹狎蛟螭。","瘦马邅迥僵复起，坠磴倾崖任所之。","吾生闻有命在天，岂必太行羊肠之险能死人为？","万盘历尽天渐黑，驻马山中问颓驿。","王程万里故乡遥，高枕山门聊此夕。"]},{"t":"送黄亮垣先生还朝","f":"七言古诗","c":["凉飔飒飒惊秋节，三城官柳鸣蝉咽。","越王台倚越山云，王气千秋可揽结。","传呼候馆抗前旌，夜来南斗避文星。","津亭冠盖不知数，共言祖送黄先生。","先生三朝旧名德，神庙贤良策第一。","藉冠宫寮侍从班，身依子舍承欢日。","年来冲圣御龙楼，讲幄文儒礼数优。","金匮两朝徵实录，前席时虚待校雠。","以此征车难久驻，谢传东山起别墅。","行边烟雨五陵花，望里春云万家树。","到日金銮凤翼开，如椽史笔总鸿裁。","谟烈显承光琬琰，始信龙门一代才。","圣明有道勤宵旰，夔龙勋业盈霄汉。","宣麻早晚拜先生，伯仲之间见伊旦。","蹇予夙昔托追游，归来一病狎沧洲。","临岐自怅典型远，飞梦长随入帝州。"]},{"t":"何园灵芝歌","f":"古风","c":["百草皆有根，灵芝有何托。","九光三秀漫传名，谁人曾见神仙药。","吾家咫尺何氏园，水部风流传世泽。","小结临南漪，中产六丹芝。","大芝产堂北，云房叠叠披。","中芝傍左三茎出，彷似三台星并垂。","稍前尺许两芝小，幻出金光逾袅袅。","云气蒙茸湿不飞，长日祥光散林沼。","造化产此岂无缘，君不见汉家元封神雀年。","九茎连叶寻常事，盛明嘉瑞非徒然。","又不见赤松子，青茎赤叶常为饵。","随风往来瑶池里，知昔瑞应总难量。","且对瑶光醉羽觞，他日餐芝上仙去。","应使我辈得学淮南鸡犬，随风共到白云乡。"]},{"t":"送伍国开春试","f":"古风","c":["忆予弱冠时，君额才覆发。","邀欢共里闾，相过忘拱揖。","下榻每连宵，对饮尽一石。","耻随里塾学，咿唔姓名不挂人齿颊。","里中小儿多早贵，里人腐鼠易相嚇。","我也大笑君亦嘻，相对长松双眼白。","从他呼马与呼牛，终须还我一李伯。","弹冠君岂为浮名，要知一片肝肠热。","去年今上正龙飞，乡国羡君先决策。","岂难连第掇公车，稍嫌官早妨挑达。","我在闱中不得君，却讶他人按剑掷。","饶君三载孝廉船，浪子风流人所适。","此事能容久借君，驱君复走长安陌。","杏花有情寄语君，待汝春风已三易。","赚君去作探花人，脱却青绦系牛革。"]},{"t":"赠何龙友游古冈圭峰","f":"古风","c":["我生双足可三尺，每思踏遍天下名山与奇石。","我生双眼不盈寸，又思览穷八荒九州罡风灏气之汗漫。","男儿堕地各有为，那能处覆类醯鸡。","曾向罗浮窥日观，曾向西樵蹑彩霓。","太行九折支策寻常度，越水吴山洞壑处处恣。","扳跻虽然未尽济，胜之双足未惬览。","胜之双目已从云水订风期，肯复人间受羁刺。","独有咫尺古冈门，负郭圭峰烟雾屯。","游人不用裹粮去，世外烟霞世内村。","几度欲游游未得，让君羽盖早翩翻。","传闻昔自一行去，白云无复金光吐。","山灵有待已千年，只今重与真人遇。","君到峰头捡翠微，玉台寺下款柴扉。","破茗亲尝瀑布水，长啸一声催落晖。","送君行，酌君酒，此事有缘兼有候。","肯容世路轻挥手，任君山水兴偏饶。","骨相封侯也未消，黄石赤松他日事，笑他猿鹤早相招。"]},{"t":"峡山留别何龙友邓伯乔陈彝庚朱惟四诸子","f":"古风","c":["平生性僻耽山水，意气兼怀方外士。","生长何郎共里闾，密缔风期亦如此。","社结词林盟邓君，酒德诗情称并美。","于时中宿有朱生，相逢肝胆便相倾。","为予首道中宿之高士，山人复得陈彝庚。","物外交游怀既洽，遂厌中区何窘窄。","五岳三山已订缘，无心误走长安陌。","牛革宁堪系懒身，投閒几作归欤客。","白云松台杖屦无不到，罗浮西樵秘箓灵文俱搜索。","荏苒皇华三阅秋，驱车强复蓟门游。","何郎情深桃花水，为轻千里送行舟。","因过峡口停兰桨，三子联翩来命访。","振衣未异昔年游，执手真成意外想。","对酒宵宵话素心，探崖处处穷幽赏。","南北分飞叹路岐，岁月催人苦电驰。","我去未应为小草，君还应为念前期。","山灵莫漫悲猿鹤，自识富贵场中烟霞骨相儿。","嘱付山僧暂锁云林与萝牖，待我重来相与共伴赤松师。"]},{"t":"采石登太白楼作","f":"古风","c":["牛渚山前采石矶，回波乱石相撑支。","上开石壁烟霞岛，连峰相向势崄崎。","我来欲访吾家老太白，天风飒飒吹我衣。","白也天上长庚星，偶落人间留姓名。","供奉金銮聊玩世，往往斗酒自沈冥。","凭陵意气山岳折，浩荡胸怀河汉倾。","一从挥手谢金阙，把酒山头问明月。","千秋留此谪仙楼，馀韵流风未销歇。","蛾眉亭碣没蓬蒿，两岸青山片月高。","只见长江汩汩万里送寒涛，极目齐州瀛海渺忽如鸿毛。","楼中之人去不复，楼外斜阳芳草绿。","人生徒苦自结刺，弹丸不及流光速。","奈何不饮，日为浮利浮名成龌龊。","松簧似奏清平曲，长夜岂照金莲烛。","不知何人与公沽酒共夜台，白杨萧萧野花开。","空馀文章千古云汉共昭回，使我今日徘徊瞻眺彷公跨鹤乘云欲下来。","公乎公乎，何不跨鹤乘云遂下来。"]},{"t":"雍署对雪","f":"古风","c":["今年冬暖久无雪，阳回又历小寒节。","道傍差免叹无衣，奈可三农望三白。","城头西夕布玄阴，同云漠漠天欲沈。","帘外初闻声淅沥，阶前瞥见玉尘深。","糁糁向晚声未息，琉璃上下天一色。","枯林尽发瑶林枝，荒山亦剖荆山璧。","辉腾万丈映崔嵬，中天照耀金茎台。","羲和匿彩避青女，翩翩鹤驾羽人来。","登楼一望金陵道，飞薨曲栏压欲倒。","九衢三市没难寻，翠壁丹崖皆素缟。","我不能学袁安僵卧洛阳里，又不能学东郭先生有上无下衣敝履。","纵有诗情在灞桥，一官束缚屋子里。","对兹六出散瑶华，呼童扫取煮松茶。","且醉吴山新熟酒，不从庾岭忆梅花。"]},{"t":"李烟客附舟入北赴袁辽抚招因赠","f":"古风","c":["舟发石头城，初报故人至。","故人故乡来，千里惊喜浑如梦寐里。","金陵三月柳如丝，呼酒同君醉莫辞。","风尘满面未须洗，便复挂帆共北飞。","君来曾几日，我别忽经年。","不愁井里荒松菊，惟愁天地有风烟。","君才自是天生者，何能局龊困椠铅。","一编黄石书，三尺青萍锷。","胸中甲兵万队生，腰间风雨双龙跃。","一顾应酬国士知，千金肯负平生诺。","榆关昨夜传消息，当关有人虏辟易，谁云甲兵满万不可敌。","特自需君借箸筹，知君谈笑取封侯。","不然直斩胡头献，天子功成不受分。","茆玺拂衣仍作鸱夷，游五湖，长与烟波逝。"]},{"t":"舟发石头城","f":"七言律诗","c":["春江水满石头城，三月桃花照眼明。","杨柳枝枝拂官渡，榜人欲发还自停。","白云一片燕山远，迢迢客路如蓬转。","不堪回望金陵山，况复庾关望不见。"]},{"t":"燕子楼","f":"七言古诗","c":["古春年年长不老，春山浥露空芳草。","双翘翠羽为谁扬，泪寒罗袂惊秋早。","楼前夜夜满空月，孤鸾露啼商丝歇。","芙蓉萎绝木兰摧，安得牡丹春后发。","有客春来自洛阳，高冢传闻长白杨。","绿珠岂爱坠楼死，韩朋无地托鸳鸯。","十年深意向谁语，黄泉未晚相随去。","寄语题诗白舍人，休更蛾眉问黄土。"]},{"t":"同烟客登太白酒楼次黄泰泉宫詹韵","f":"七言古诗","c":["高楼临河增硉兀，河光一片青天出。","我来不尽怀贤心，长空濛濛烟拂拂。","风流旧事忆千年，解裘曾向酒家眠。","不知采石江头月，何似金莲午夜天。","宝床宫锦今何在，片月年年照东海。","极目鲸波万顷春，安得随君钓巨鳞。"]},{"t":"冯节妇诗为陆工部作","f":"楚辞体","c":["君不见，红槿终朝媚艳阳，贞柏千秋傲霜雪。","铅华过眼成灰尘，谁与岁寒留劲节。","烈哉少小冯家妇，初生连理风吹折。","连理折兮枝复萎，寄生空长女萝丝。","孤干经春枯不发，女萝新浥露华滋。","鸾镜沈来俄老丑，一生形影同灯守。","报君血泪化碧珠，同穴他年照白首。"]},{"t":"访米仲诏光禄留坐因招同姜仲讱何龙友王季重同集","f":"七言古诗","c":["朔风吹落天河雪，剥我饥肤冻欲裂。","可堪车马日溷人，怀刺纷纷问典谒。","日暮经过御苑傍，惟君风雅登君堂。","相看意气飞扬甚，为我添招旧酒狂。","客来共解衣冠坐，稚子烹茶自爇香。","恢谐亦自关名理，潦倒何妨出肺肠。","须臾明月鉴窗白，霜华片片琉璃色。","空中光怪不得藏，万峰千峦生几席。","几席峰峦实幻多，耳目惶惑醉颜酡。","主人爱客情未已，新词更唤雪儿歌。","歌喉婉转箫声咽，为君更酌金叵罗。","似此为欢不尽赏，明月红尘奈若何。","长安作吏无多味，岁月驱人疾于驶。","故山猿鹤未可期，眼底荣华只如此。","同调吾曹复几人，聚首何能但尔尔。","屈指春花事不遥，与君重理桂丛招。","但得幽期长不负，一官脱屣亦翛翛。"]},{"t":"初秋游西山出郭有怀马伯起戴公纶区启图","f":"古风","c":["城内岂无秋，出郭今方见。","山坳夜月留，草尖晨露泫。","一年两度游西山，宦况虽忙亦自閒。","独恨昔游三四子，兹来强半隔追攀。"]},{"t":"戴安仲过游白下官署相访未几别去取道于浙遍游吴越名山赋此送之","f":"古风","c":["戴生湖海士，意气傲风尘。","不著青衫谒时贵，每横白眼看世人。","伸纸羞为制举义，含毫辄吐淩雪气。","牛耳狎主诃林盟，马蹄踏遍白云里。","兴来每抱方外心，自谓域中山川窘窄耳。","洪厓卢敖是我师，安能局促辕下驹，岁岁年年困乡里。","去秋九月度庾关，梅花万树尽跻攀。","南过荆门上三峡，云梦之泽弄潺湲。","春来复渡章江水，更挂布帆问吴市。","三山二水恣登临，牛首燕矶供杖履。","秦淮柳色变新秋，凉风江上吹飕飕。","乘风欲看西湖月，又浮舴舰下杭州。","身馀双足便称快，囊无一钱未是愁。","嗟馀未挂进贤冠，撒手尘中万事难。","羡君此去同仙驭，恨不淩风生羽翰。","苏公堤、严陵濑，我昔经游逾十载。","君行瓢衲信翱翔，云水云山应未改。","饶君萍迹遍人间，兴尽应知返故山。","我亦拂衣从此去，相与结茆同老罗浮玉女潭。"]},{"t":"送戴公纶南还","f":"七言古诗","c":["戴生翛翛海鹤姿，胸中潇旷雅负奇。","壮心孤往契千古，劲笔凭陵无一时。","平生结交重意气，与余弱冠缔襟期。","兴来白社朝朝会，别去沧波岁岁思。","十年献策未得志，五岳三山寻杖履。","春风偶逐蓟门游，相见惊狂疑梦里。","便解金貂向酒家，论心日日醉流霞。","探胜西山曾并马，乘凉东郭共看花。","自此天涯旅思宽，顿忘沈陆在金门。","祇便雅会长燕市，谁解离期促马鞍。","闻君归路出吴越，秀岭名湖几超忽。","登临好在暮秋时，文藻山川相映发。","兴尽应归五穗城，白云山下学躬耕。","予亦归来赋已就，期君共访安期生。"]},{"t":"送伯乔还粤","f":"七言律诗","c":["燕山仲冬雪皑皑，怜尔初从塞上回。","长筹已见妖氛净，乡心不那白云催。","尔家住在珠江侧，归御潘舆乐何极。","斑衣多暇赋新诗，缄题能到缁尘客。"]},{"t":"送傅寄庵太史册封周府","f":"古风","c":["长安七月天气凉，皛皛银河万里长。","驱车出饯剪桐使，远赋皇华度汴梁。","汴梁形胜称都会，山如龙蟠水如带。","地当天中控上游，百二崤关雄胜概。","君是经闱侍从臣，广厦细旃日讨论。","五夜照归莲炬燄，六时赐出大官玲。","只今暂辍承明席，遥分玉节展周亲。","梁苑平台似畴昔，未少邹枚骚雅客。","赋雪群推马长卿，授简当筵谁与敌。","词臣还计缓王程，休沐翻为锦里行。","此时南浦波初绿，此时匡山月正明。","石镜夜悬青黛合，香炉晓望紫烟轻。","日月湖，龙沙岸，中间窟宅多仙灵。","瑶草琪花满地生玉堂，仙吏归去桃花树底吹鸾笙。","应有旌阳彩鸾诸真，云中来下迎可那。"]},{"t":"赋得碎器瓶","f":"五言古诗","c":["己甘玉共碎，肯藉瓦能全。","漾水纤鳞跃，欹花细锦鲜。","陶成煮白石，炼就补青天。","秋月冰壶裂，春蚕丝茧缠。","珊瑚笼铁网，蝌蚪蚀苔笺。","纹杂罘罳簟，光分玳瑁筵。","质瑩高玉案，晕积近炉烟。","若是词人掷，声同作赋传。"]},{"t":"节寿篇为谢大行寿母","f":"五言古诗","c":["乾坤清淑气，之子禀能全。","同穴心宁负，存孤死未捐。","歌传黄鹄咏，诗诵柏舟篇。","玉貌先时毁，冰心映日妍。","机丝寒夜月，妆匣冷秋烟。","太史风方采，仙郎名已传。","定评舆论合，特命九重宣。","泉壤回阳日，杯捲慰暮年。","中流有柱石，万古砥长川。"]},{"t":"夜登黄龙洞作","f":"五言古诗","c":["出郭若不早，到山日已昏。","阪从灯下陟，草自雾中扪。","未历诸山胜，先寻古洞源。","敢誇济胜健，还藉土人援。","径窄时分队，山欹欲悸魂。","登登路逾窅，望望岭加尊。","遇石频思憩，穿岩或借蹲。","风来时作阵，瀑响听如奔。","俗骨何当换，幽怀暂许论。","一身怜秽浊，双足想腾骞。","稍过流杯石，知为天洞门。","荒祠无卧具，聊共枕松根。"]},{"t":"同陈治甫邓伯乔何龙友朱惟四何伯承游峡山登眺虚岩绝顶得二十韵","f":"五言古诗","c":["神工开佛刹，鬼斧凿虹桥。","两峡攒流小，孤峰抱寺遥。","烟霞低几槛，钟梵落江潮。","洞古云常湿，崖阴雪未消。","昔来望空翠，此日陟岧峣。","萝月诸天近，松风万壑骄。","鸟啼皆说法，霞起尽成标。","灵药芝田供，金绳觉路招。","日车何用驾，风驭似相邀。","鹤度瑶笙响，云开绛节朝。","尘襟思洗涤，仙路隔冥寥。","俯仰成今昔，年华老世嚣。","此身何著落，生趣转萧条。","方外期高尚，区中惬久要。","宁须待婚嫁，且去混渔樵。","服制山中薜，粮收峡口苗。","回头当早早，失路恐迢迢。","有分寻真去，无才免俗谯。","悟来翁失马，梦去鹿蒙蕉。","天明解缆去，又任梗蓬飘。"]},{"t":"林鹤胎司成招同林季翀宗伯游北郭白云深处","f":"五言古诗","c":["眷言佳丽地，花鸟复春时。","堤柳才萦缕，山梅未谢枝。","共违供奉署，不负赏心期。","北寺寻俱遍，东岩胜更披。","画图天写就，杖屦日追随。","槛暖蜂初趁，帘閒燕屡窥。","乍来耳目换，久坐世嚣遗。","斗酒时挥麈，双柑或听鹂。","白门官况好，未羡解缨緌。"]},{"t":"蟠桃春坞","f":"五言古诗","c":["奇姿开露井，仙品说螃螗。","何悟闽山上，逢兹世外芳。","离离垂玉露，灼灼艳朝阳。","汉殿三千阅，扶桑五万长。","紫文悬玉绶，绛蕊杂丹床。","遗核传东海，冰盘出上方。","武陵津乍入，瑶岛宴初张。","若问成溪事，公门望渺茫。"]},{"t":"宝地苍霞","f":"五言古诗","c":["霞山何代辟，宝额昔贤题。","入望诸天近，淩空万象低。","霞光开混沌，亭树倚菩提。","仙侣曾游地，真人比托栖。","为霖占异石，迎日出丹梯。","紫气东山起，高标北斗齐。","衣裳裁散绮，服食掇晴霓。","台岭朝河建，襄城夜不迷。","景光知可仰，敢自隔扳跻。"]},{"t":"金陵归思漫成百韵","f":"古风","c":["俯仰笑寥廓，蹉跎感岁年。","浪游今倦矣，缅想昔依然。","涨海重溟外，驼山数亩廛。","先人遗素业，生计剩青毡。","负笈三城社，论文五穗边。","交亲多慷慨，文酒得周旋。","台上回金勒，花前拾翠钿。","姓名埋市井，歌舞出鞦韆。","有客尊常满，无营磬屡悬。","彩毫从汩没，侧注漫拘挛。","射策收仍罢，焚舟计转坚。","未酬三釜愿，俄及百忧煎。","世事支床失，雄心枕块捐。","馀生存视息，大业久迍邅。","岂复谋衣食，终难谢椠铅。","谬承辟选诏，旋泛孝廉船。","翡翠初来粤，黄金遂市燕。","连城誇十五，奏牍诧三千。","王气瞻宫阙，鸿图陋涧瀍。","北门叨选士，中秘更抽玄。","缓步铜龙署，高谈碣石天。","笔花飞锦绮，文彩吐蜿蜓。","待诏时催草，承恩间赐莲。","阳春矜白雪，清庙奏朱弦。","霄汉身能致，烟霞疾未痊。","主恩宽药里，马鬣扫松阡。","寂寞蓬蒿径，荒芜下噀田。","禄微耕未代，心远地逾偏。","凿沼鱼瀺灂，开林草郁芊。","岁时过父老，伏腊话姻㜕。","霞岛桡从泛，罗浮屐屡穿。","灶寻葛令迹，偈悟慧师禅。","采药供餐饵，留题遍劖镌。","尘心顿濯濯，飙驭欲翩翩。","色借观涛起，怀翻恋阙牵。","莺花蓟北望，猿鹤草堂悁。","吴越随游涉，江湖信溯沿。","武林花澹澹，茂苑柳娟娟。","幽思邮程缓，纡途岁月愆。","鹓行方问侣，龙驭再升軿。","泪与遗弓堕，人同丧考㾓。","重明新出震，万物睹乘乾。","玉帛冠裳集，金鸡诏命宣。","凤仪开景运，河瑞兆清涟。","共喜屯膏沛，还看泰茹连。","赐环旌戆直，搜逸遍陬?。","边羽振飞鹭，峨冠列珥蝉。","礼闱分较士，皇路广登贤。","剖璞期收玉，然犀易照渊。","骨多千里骏，鉴拟九方歅。","虎观春风启，鸡筹晓漏传。","两朝徵实录，内制代宸篇。","禁地容开局，时髦预比肩。","常分法厨粟，亦割大官鲜。","快睹丰亨盛，时防鼎趾颠。","绸缪疏户牖，氛祲动戈鋋。","辽左围方急，西川祸更延。","军符十道出，烽燧九边然。","输挽闾阎竭，膏脂郡邑脧。","逃臣轻国法，悍卒挟金钱。","风鹤皆成敌，旄倪谁为怜。","蚊微山岂负，禽小海思填。","廊庙髀徒拊，干城略孰专。","无繇纡国难，空愧备词员。","欲上千秋鉴，先驰四牡駽。","羊肠轻叱驭，鸟道仰飞鸢。","击楫心逾壮，听鸡舞独先。","藩屏封典重，带砺本支绵。","赋雪实游满，趋风车骑阗。","曳裾疏礼数，授简喜翩翾。","役以皇华竣，程宽昼锦还。","但濡马六辔，遑惜足重趼。","返棹回阳月，宁家寒食前。","客心纷去住，时序忽流迁。","丘壑情偏适，简书迫已遄。","敢言于役瘁，重荷宠光殷。","周道停征旆，桥门拥绛旃。","宫墙瞻肃穆，桃李竞芳妍。","铃铎传宵警，诗书伴昼眠。","化期收棫朴，材不乏楠楩。","虎踞山形壮，龙蟠帝业全。","远臣心自耿，拙宦僻相便。","衰任逢歌凤，升宁兆献鳣。","幽奇多搜历，竿牍懒板缘。","术自疏经世，恩还录讲筵。","诜诜承緌佩，袅袅近炉烟。","微悃惭输曝，虚怀负转圜。","仍辞丹禁席，重理白门鞭。","礼乐彝夔旧，秩宗夙夜虔。","江山还旧识，寮寀尽新铨。","幸值皇威赫，欣闻虏骑跧。","华夷通正朔，天地厌腥膻。","疏散材何补，倡狂性不悛。","何当恋簪绂，祇合老林泉。","松竹开三径，云山访列仙。","鹤台春寂寂，蒲涧水溅溅。","石髓非难遇，朱霞或可搴。","那能甘雉畜，且去学鸿骞。","决计应须早，回头便堕缠。","出门即有路，咫尺昆崙巅。"]},{"t":"初夏泊仪真游汪氏园","f":"五言古诗","c":["眷此邱中赏，名园傍水涯。","偶乘蓝举至，非为主人期。","入户丛花碍，穿林幽鸟疑。","一区藏曲折，叠石得崄崎。","编竹新栽药，通泉小凿池。","荷钱初出水，柳絮乱垂丝。","地僻人来少，园深春驻迟。","凭栏看紫鲤，仰面听黄鹂。","景物原无意，流光若有私。","乘凉且归去，江月照相随。"]},{"t":"元夜同王季重姜仲讱何龙友观灯米仲诏光禄宅","f":"五言古诗","c":["考槃不在远，高馆帝城隅。","乐事时相假，春来景更殊。","鸿钧转邹律，明媚满皇都。","士女新妆炫，侯门锦帐纡。","千金竞一刻，百宝溢交衢。","每上六鳌驾，云中双凤扶。","何如清净地，光现牟尼珠。","树发银花火，屏妆金缕图。","列筵星彩动，番席月轮孤。","大地涵瑶镜，千家坐玉壶。","羁心怜越鸟，新调听吴歈。","楚客捐兰佩，燕人混酒徒。","萍逢缘不偶，星聚事宁诬。","未论千秋事，聊穷五夜娱。","游何须秉烛，饮且恰呼卢。","兴剧愁更促，歌清缓夜徂。","百年聊复尔，七尺胡为乎。","遇景应同惜，寻盟未许逋。","群公自钟鼎，小子渴江湖。","他日怀芳躅，南征雁有无。"]},{"t":"挽萧拙脩年兄","f":"五言古诗","c":["传道螺川信，高天未可呼。","典型捐物望，肝胆失吾徒。","强仕通金马，清心比玉壶。","兰风朋好洽，鼎望野朝孚。","鸥鸟狎相伴，鹓班间一趋。","棘闱收誉髦，玉署想楷模。","燄赫非难致，清贞肯受濡。","鸿冥谢弋慕，鹏徙托南图。","白下虚真气，湘潭有大夫。","朝方新物色，瓯已卜师儒。","赉弼天心杳，修文地下需。","苍茫凶问远，萧瑟客怀孤。","未竟青云业，俄惊白日徂。","相舂绝邻里，流涕满街衢。","忍策巨卿马，聊陈孺子刍。","千秋哪复问，双眼不禁枯。","寂寂高山曲，人琴已两亡。"]},{"t":"寓冲虚观作","f":"七言古诗","c":["浮来蓬岛定何年，秀出芙蓉片片鲜。","世界风尘无此地，山中丘壑别藏天。","遥凭仙路如堪往，初入玄都暂借眠。","丹灶尚留仙令迹，铜龙还自羽人传。","天边鸾鹤霞齐度，洞口桃花秋亦然。","藜杖每扶朝雨后，樵歌多到晚钟前。","纵无仙骨宁甘俗，说甚尘心不尽捐。","朋好洽来无约束，水云到处恣留连。","坐忘雾色侵筵几，静有泉声送枕边。","岁月长留峰四百，沧桑曾阅世三千。","觉来十载长安路，何似兹游数日缘。"]},{"t":"渡江重游燕子矶弘济寺诸胜","f":"七言古诗","c":["片帆风渡大江平，绀宇参差入望明。","旧识名山曾有路，重来迁客不胜情。","烟霏古洞衣裳湿，云拥丹梯杖屦轻。","坐石每移松顶日，步林时听柳阴莺。","满天灏气孤亭矗，万顷湖光一艇横。","望望蜃楼开市远，飞飞燕子结巢成。","禅堂寂寞传钟响，芦岸萧条起篴声。","王谢风流尘土没，齐梁台殿莽烟生。","露薄瑶草春长驻，风落昙花雨亦晴。","自爱江山长不改，只怜人代浪推萍。"]},{"t":"初秋同林少宰罗司成游鸡鸣山","f":"七言古诗","c":["凉雨初收景乍妍，客裳沾洒思翛然。","招携同叩鸡鸣寺，眺望仍登鹫岭巅。","霜落渚莲秋万顷，风归巢鹤树千年。","萧王香殿埋芳草，宋苑经台起暮烟。","两度宦游供汗漫，六朝风物足留连。","金门一别星辰隔，白下同来岁月偏。","簪绂未妨仙吏傲，酒杯宁负远公缘。","尚怜泽雉樊中啄，终儗冥鸿人外骞。","丹灶罗浮砂未改，金书衡岳鸟还传。","武陵不是人间世，好共他年访列仙。"]},{"t":"落第后齿病自嘲","f":"五言律诗","c":["何解唇亡苦，还侵藿食夫。","谈天舌尚在，尝胆事虚无。","嘘吸乾坤妒，呻吟风雨孤。","廿年怜犬马，消渴总江湖。"]},{"t":"黎缜之见过","f":"五言律诗","c":["冲炎劳见访，把臂竹林幽。","岂是陈蕃榻，能令孺子留。","解衣坐竹下，贳酒过墙头。","欲儗逃喧去，风尘可自由。"]},{"t":"欧子建同梁羲年过访","f":"五言律诗","c":["经年劳问讯，快绝此披襟。","旧好怜同病，新知共入林。","衰荷翻雨响，密竹落秋阴。","莫更伤摇落，难逢是会心。"]},{"t":"访欧子建澹圃二首 其一","f":"五言律诗","c":["到来幽意惬，久坐野情长。","有榭皆临水，无轩不极凉。","菊荣抽早蕊，兰晚茁馀芳。","便作吾庐得，高眠到上皇。"]},{"t":"访欧子建澹圃二首 其二","f":"五言律诗","c":["几年鸡黍约，此日访文园。","君自劳招隐，予将偕避喧。","楼台开似画，篱落小成村。","何事投车辖，方留十日尊。"]},{"t":"游鹤楼","f":"五言律诗","c":["结楼仍世境，高敞与云期。","山翠层层拥，霞光面面垂。","凉风纳虚牖，爽气逼平池。","时有吹笙过，空中鹤可骑。"]},{"t":"六如草堂","f":"五言律诗","c":["无复尘中想，真宜居士居。","逃禅参上乘，说偈得真如。","乐意满窗草，閒心一径蔬。","我来忘去住，长日坐清虚。"]},{"t":"玉林别业","f":"五言律诗","c":["小亭依木末，幽绝隔尘氛。","径僻馀黄叶，檐虚只白云。","竹声过暮雨，花气杂朝薰。","欲籍苔阶枕，招呼客又闻。"]},{"t":"十五夜同黎邓欧诸子饮李仲伟席上得星字","f":"五言律诗","c":["雅会逢秋半，词人共此亭。","已怜今夜雨，况是客中听。","天上无流彩，人间亦聚星。","当杯念明发，遮莫付沈冥。"]},{"t":"龙池社集分得阳韵","f":"五言律诗","c":["入坐青山近，开尊属晚凉。","偶来寻白社，因得醉高阳。","露下侵江气，亭虚占月光。","还应怜夜色，鼓枻溯沧浪。"]},{"t":"闰九月朔同集欧子建半竹亭","f":"五言律诗","c":["秋好重留闰，相期过绿阴。","傍檐容坐密，看竹引杯深。","浪谑知狂态，高谈见素心。","为怜佳会少，下榻更披襟。"]},{"t":"馆五羊答伍长卿乡居月夜见怀之作","f":"五言律诗","c":["秋月怀人夜，乡园共此时。","难成羁枕梦，翻系屋梁思。","照水心同皎，登楼望更驰。","清辉不盈手，何以慰相贻。"]},{"t":"冬夜宿邓伯乔三一山房","f":"五言律诗","c":["小搆依城市，清幽绝世缘。","偶因载酒至，便作对床眠。","月出花垂牖，雁声霜满天。","玄谈当永夜，不寐各悠然。"]},{"t":"过梁明叔小楼","f":"五言律诗","c":["羡君城郭里，别自得烟霞。","山色当窗尽，林光绕槛斜。","好音枝上鸟，幽事雨中花。","更披图画好，疑入武陵家。"]},{"t":"韩孟郁李宾廷见过时予将解馆还山 其一","f":"五言律诗","c":["懒性疏逢世，襟期但汝论。","壮心频说剑，凉夜且开尊。","落木城头急，鸣虫竹下喧。","所怜明发别，添烛续清言。"]},{"t":"韩孟郁李宾廷见过时予将解馆还山 其二","f":"五言律诗","c":["莲社飘零后，过逢转自欢。","幽期犹及菊，心赏惬如兰。","短壁低残照，高城起暮寒。","合离今日意，莫厌酒杯宽。"]},{"t":"山溪角与汪三晓行感怀","f":"五言律诗","c":["间关返城市，乍慰旧林栖。","正儗辞舟楫，如何又马蹄。","微风野花落，欲雨海云低。","赖有同心侣，相携逐晓鸡。"]},{"t":"送邓伯乔远游","f":"五言律诗","c":["丘壑那能恋，多君事远游。","清时收国士，词客借前筹。","云含晴日雨，草变夏时秋。","别离看后夜，莲社不堪愁。"]},{"t":"送敏如上人还匡山","f":"五言律诗","c":["衲子浮江返，还疑受钵年。","观空忘物役，到处有人天。","尘梦吾增感，真如性所便。","应知无去住，别尔但茫然。"]},{"t":"早秋同马伯起梁明叔诸子集朱惟四寓馆共赋 其一","f":"五言律诗","c":["一叶飘梧井，高斋坐日斜。","城头过片雨，树杪落残霞。","名岂朋游藉，交怜意气赊。","开尊待秋色，容易负年华。"]},{"t":"早秋同马伯起梁明叔诸子集朱惟四寓馆共赋 其二","f":"五言律诗","c":["客舍逢君日，词人偶并过。","露彫三径柳，风落一池荷。","虫响竹间细，蝉声雨后多。","忘归从路瞑，清啸满烟萝。"]},{"t":"送族叔于垣复之皖城蔡明府官署","f":"五言律诗","c":["七载违乡国，还家岁杪时。","如何春事好，又是别离期。","枳棘栖宁恋，云霄计未迟。","前途争御李，暂许使君私。"]},{"t":"丁未立秋","f":"五言律诗","c":["夏来常抱病，炎暑太相欺。","复此凉飙至，絺衣林外披。","荷衰如怯露，蝉冷乍惊枝。","物色皆秋意，宁关一叶知。"]},{"t":"怀欧子建","f":"五言律诗","c":["病耽高卧稳，寂寂掩柴荆。","远道长怀汝，清秋一寄声。","风尘销翰藻，岁月老时名。","夙昔襟期在，宁终负此生。"]},{"t":"羊城病中七夕","f":"五言律诗","c":["枕簟凉风入，他乡七夕秋。","无朋问沽酒，独坐望牵牛。","延想星河近，微吟风露收。","兹宵病客梦，应傍故山楼。"]},{"t":"初秋邓伯乔招同诸子集梁明府西园","f":"五言律诗","c":["西郊带长薄，一径草亭欹。","野旷秋声早，林空落照迟。","悠然清兴发，共惬白云期。","莫厌归途晚，红尘骑马随。"]},{"t":"初秋同欧子建邓伯乔过朱季美虹冈别业","f":"五言律诗","c":["北郭寻幽赏，名园倚岫开。","风林失午暑，阴壑送秋雷。","洒扫云间石，同倾竹下杯。","酒酣欢未已，欲去更徘徊。"]},{"t":"中秋无月诸从同戴公纶过酌 其一","f":"五言律诗","c":["飘泊经年意，秋来两鬓残。","那期今夜酒，得共故园欢。","明没星河失，朦胧桂影寒。","清光还可待，秉烛话更阑。"]},{"t":"中秋无月诸从同戴公纶过酌 其二","f":"五言律诗","c":["节是吾家会，筵邀上客欢。","流光增感慨，良夜且盘桓。","芳桂迎风冷，残倚怯露漙。","解识清秋意，光辉淡处看。"]},{"t":"初冬同伍国开兄弟雨中寻梅","f":"五言律诗","c":["闻道江梅好，相期江水滨。","不辞微雨湿，为觅淡妆人。","蕊似含情待，枝偷剌眼新。","何须看庾岭，数朵不胜春。"]},{"t":"秋杪再同诸子登落霞峰醉中赠有开","f":"五言律诗","c":["未尽登高兴，重来结伴游。","江山仍旧识，寒意改深秋。","席地妨樵径，扳花作酒筹。","醉忘归路远，还为夕阳留。"]},{"t":"初冬同诸从偕戴公纶泛舟过隔溪矶上坐饮","f":"五言律诗","c":["沿流寻所适，舍艇入林隈。","觅坐全依草，贪眠不避苔。","山禽衔果落，溪月涌潮来。","何事枌榆地，长年负酒杯。"]},{"t":"已酉秋杪还山伍国开有开何景言诸子过访","f":"五言律诗","c":["归来三径在，寂寞见吾真。","谁道无知己，犹能枉故人。","穷途交有态，秋色暮逾新。","已谢尘羁束，青尊肯厌贫。"]},{"t":"大观亭集","f":"五言律诗","c":["十年桑梓地，开社枕溪流。","及此漂零日，狂歌得共游。","望云怜鸟疾，临水羡鱼浮。","乍解风尘色，何妨尽醉留。"]},{"t":"送何龙友北上","f":"五言律诗","c":["忽忆莺花好，乘春集凤池。","风云失计日，湖海送君时。","短鬓怜秋色，穷交少旧知。","功名非俗物，行矣爱前期。"]},{"t":"送黎有道远游","f":"五言律诗","c":["最怜物外侣，磊落几如君。","生计馀诗卷，行踪半水云。","无心恋瓮牖，有路出尘氛。","一别家山去，音书何处闻。"]},{"t":"苦雨","f":"五言律诗","c":["经旬怀不展，积雨笑天痴。","兀坐忘昏晓，閒愁感岁时。","潦田妨稼穑，门巷泛鸬鹚。","徙倚空庭晚，酣歌转自疑。"]},{"t":"邓伯乔远还寄讯二首 其一","f":"五言律诗","c":["念尔频惊梦，欣逢返旧林。","艰危身尚在，去住感何深。","花鸟归人赋，渔樵倦客心。","可能移雪棹，乘兴泛山阴。"]},{"t":"邓伯乔远还寄讯二首 其二","f":"五言律诗","c":["自得淩江信，经年断尺书。","生涯那可问，浪迹竟何如。","岁月潘郎鬓，风烟楚泽渔。","山川修复阻，疑望涕盈袪。"]},{"t":"暮春见新月","f":"五言律诗","c":["经旬愁积雨，乍见吐残规。","照水翻成练，窥妆欲上眉。","闷怀云影散，幽韵草光披。","三匝南飞鸟，栖栖未定枝。"]},{"t":"同诸弟新年游水月庵","f":"五言律诗","c":["行春随所适，少涉即禅林。","花雾分香霭，泉声杂梵音。","云霞如有想，水月本无心。","顿觉劳生久，慈航此地寻。"]},{"t":"贺伍伯翔新婚","f":"五言律诗","c":["春仲融和日，春风啼鸟频。","月怜眉黛巧，花妒绮罗新。","醉益怀中语，欢疑梦后身。","风光有如此，应自爱芳辰。"]},{"t":"冬夜与戴公纶诸子泛月","f":"五言律诗","c":["泛泛定何适，怜幽每驻桡。","得林仍见月，维岸亦听潮。","把酒飘零失，狂歌意气骄。","鸣榔且归去，野寺报钟遥。"]},{"t":"早起","f":"五言律诗","c":["鸡声梦初觉，渐听晓钟稀。","乍惬晨飔爽，犹怜夜色微。","步林栖鸟散，扫径白云飞。","万虑何曾感，焚香未启扉。"]},{"t":"何龙友苦熟患疮见寄二诗赋答 其一","f":"五言律诗","c":["无处堪逃暑，幽居漫掩扉。","雨声来伏枕，兰气染初衣。","念此经时别，还怜问询稀。","浪传君苦热，郢雪冷然飞。"]},{"t":"何龙友苦熟患疮见寄二诗赋答 其二","f":"五言律诗","c":["暑兼杯酒废，懒任故人疏。","尔自思河朔，诗来问敝庐。","烟霞容寄傲，日月老閒居。","未忘千秋事，青山待著书。"]},{"t":"得欧子建书寄答","f":"五言律诗","c":["一卧乡园僻，思君又岁寒。","别来仍落魄，书到慰加餐。","日月虚鸿宝，乾坤负钓竿。","清江秋事好，谁与采芳兰。"]},{"t":"中秋后一日园亭闻蝉","f":"五言律诗","c":["荏苒秋过半，开尊坐暮林。","玄蝉衰柳外，作意送悲音。","露冷声偏苦，风寒响易沈。","听来翻自感，不那岁时心。"]},{"t":"重游瑞虞龙友别业","f":"五言律诗","c":["十年一俯仰，兹地复同游。","偃蹇怜生事，萧条感素秋。","新霜凋蕙草，寒雨散江鸥。","但惬丘中赏，宁悲白日流。"]},{"t":"驼山寻梅重别俞氏兄弟","f":"五言律诗","c":["岁有梅花候，今年开独迟。","长林犹带叶，冷蕊未盈枝。","日暖蜂犹趁，林深鸟屡窥。","归人不可住，攀折有馀思。"]},{"t":"元旦楼中早起","f":"五言律诗","c":["绕槛林霏雾，当窗山送霞。","真疑瑶树长，手自掇三花。","日月催人事，烟云换岁华。","呼童荐椒酒，春意在吾家。"]},{"t":"晚泊西南驿","f":"五言律诗","c":["行程悬万里，傍晚一停桡。","驿号西南古，人怜岐路遥。","冷风侵短褐，新月涌初潮。","去去庾关近，梅香早己飘。"]},{"t":"谒南华","f":"五言律诗","c":["宝地烟霞辟，西天法界开。","谁知偕计日，得及谒师来。","发藏探灵秘，观空上玉台。","所怜明发路，愿借渡江杯。"]},{"t":"清远峡","f":"五言律诗","c":["推蓬望长峡，逆水进扁舟。","夹岸攒江耸，孤泉界壁流。","樵歌传牧竖，山果弄猕猴。","辍棹还登陟，寻幽到上头。"]},{"t":"度庾岭寄同社诸子","f":"五言律诗","c":["庾关初度日，雪色满山春。","乍惬扳梅想，翻怜赠别人。","虹光望白社，龙剑隔延津。","寄尔一枝去，应怀京洛尘。"]},{"t":"皖城舟中立春","f":"五言律诗","c":["滞留怜雨雪，道路喜逢春。","湖海扁舟日，乡园万里人。","尊盘随俗赏，梅柳上枝新。","渐觉风光好，莺花望紫宸。"]},{"t":"赋得山城犬吠云","f":"五言律诗","c":["荒城三五户，篱落自成村。","每觉云惊犬，虚疑客到门。","近窗搅午梦，传谷应空喧。","乐土相闻处，风犹大古存。"]},{"t":"赋得起坐弹鸣琴","f":"五言律诗","c":["夜静群动息，悠然百感侵。","我怀无所托，揽衣调素琴。","掩抑调中恨，凄清弦外心。","松风时扣户，错讶到知音。"]},{"t":"赋得十五颇有馀","f":"五言律诗","c":["丽质本多姿，年光复在兹。","低眉初舞袖，织手学调丝。","佻达何曾惯，骄羞强自持。","清光三五在，团扇未须疑。"]},{"t":"赋得江清月近人","f":"五言律诗","c":["水天秋一色，夜月净涓涓。","似练涵青镜，如轮动碧川。","鱼龙听醉语，鸟鹊绕寒烟。","莫向楼头妇，清宵照独眠。"]},{"t":"赋得归山独鸟迟","f":"五言律诗","c":["为巢原避弋，人外托幽閒。","野旷无朝暮，天空信往还。","乘风犹逐侣，见月始归山。","藜杖忘机者，相随亦掩关。"]},{"t":"赋得客至始梳头","f":"五言律诗","c":["竹径萧森地，逃喧与世违。","僻居无驷马，卒岁懒裳衣。","偶闻幽侣至，理发向斜晖。","岂为妨高枕，翻怜雅会稀。"]},{"t":"赋得冬花","f":"五言律诗","c":["亦随群卉植，不共众葩荣。","质自含冰结，香缘濯雪清。","铅华迟暮思，裘马冶游情。","安得岁寒侣，幽芳共结盟。"]},{"t":"赋得砚","f":"五言律诗","c":["阴山有紫玉，剖璞更多奇。","染墨云生石，濡毫花弄池。","草玄知不负，守黑欲何为。","若作王郎论，应从四璧窥。"]},{"t":"赋得荷露","f":"五言律诗","c":["霏洒何曾见，凝荷始著珠。","日边光乍闪，风际有还无。","瓣湿何郎粉，香浮妃子酥。","若耶溪畔女，双腕几沾濡。"]},{"t":"禁林春望 其一","f":"五言律诗","c":["禁城开晓望，曙色乱晴阴。","柳暗春藏陌，花明暖到林。","条风翻戏蝶，淑景动鸣禽。","最是宸游地，春来雨露深。"]},{"t":"禁林春望 其二","f":"五言律诗","c":["上苑春光早，登台望杳然。","有花皆笑日，无柳不含烟。","绮陌莺初啭，金河雁未旋。","阳和均万户，长与奉尧天。"]},{"t":"五日忆江南","f":"五言律诗","c":["燕台逢午节，转忆故园欢。","艾酒邀邻舍，兰舟竞急湍。","绮罗蘸水影，歌管入云端。","漫说兵堪辟，烽烟道路难。"]},{"t":"早春赠苏汝载山人","f":"五言律诗","c":["十年意气侣，转自帝城亲。","傲骨终成我，浮名肯傍人。","冥鸿千古意，呼马此时身。","为问胡姬酒，春来醉几巡。"]},{"t":"送郭冲甫别驾之任岳州","f":"五言律诗","c":["风流看佐郡，揽辔佩刀新。","谁念缁尘客，分携白社人。","湖光澄浩淼，岳色映嶙峋。","知尔登楼处，临风把酒频。"]},{"t":"立秋先一日同韩寅仲苏汝载罗敦翰集樊孟泰署分赋","f":"五言律诗","c":["留滞京华久，惊心一叶风。","莼鲈乡思远，尊酒故人同。","习懒时名减，谈高夜色空。","惟应同调者，杯底日过从。"]},{"t":"寄怀黎群献","f":"五言律诗","c":["一从江上别，万里各风烟。","去住心宁异，交亲意自怜。","梦归芳草渚，人远白云天。","秋雁南来少，应无只字传。"]},{"t":"中秋后一夕韩太史林广文曾比部汪黎二山人过集寓楼分赋","f":"五言律诗","c":["佳期来胜侣，多是故乡人。","月过三秋半，情怜万里亲。","风飘梧欲尽，露濯桂仍新。","好友连宵赏，尊醪未厌频。"]},{"t":"吴孝廉光卿初至韩绪仲先生招同曾元鲁黎不回夜集分赋 其一","f":"五言律诗","c":["薄宦逢迎少，招寻有弟兄。","何期倾盖客，得惬入林情。","促膝话桑梓，飞杯泛菊英。","迟回怜夜色，新月上高城。"]},{"t":"吴孝廉光卿初至韩绪仲先生招同曾元鲁黎不回夜集分赋 其二","f":"五言律诗","c":["论交无久暂，欢会慰天涯。","情惬邱中赏，言多物外期。","乡心砧杵急，秋色鬓毛知。","拚醉兹宵酒，城头漏下迟。"]},{"t":"吴孝廉光卿初至韩绪仲先生招同曾元鲁黎不回夜集分赋 其三","f":"五言律诗","c":["节序重阳近，篱花数朵新。","所怜今夜会，同是故园人。","下榻情何剧，忘形语自真。","醉听流水弄，一为涤缁尘。"]},{"t":"吴孝廉光卿初至韩绪仲先生招同曾元鲁黎不回夜集分赋 其四","f":"五言律诗","c":["秋色真宜夜，过从地复偏。","谈高催换烛，坐久问装绵。","月影寒移竹，雁声霜满天。","醉来忘潦倒，欲别更留连。"]},{"t":"黄逢一得请还粤同曾元鲁过宿话别 其一","f":"五言律诗","c":["己恨分携促，还能此夜亲。","因谈乡国事，悔作宦游人。","雁掠征帆度，花迎候馆新。","都门明日道，去住各酸辛。"]},{"t":"黄逢一得请还粤同曾元鲁过宿话别 其二","f":"五言律诗","c":["萍梗真无定，天涯又一时。","词人共清夜，归客况临岐。","横被情偏洽，听鸡梦屡迟。","话深天渐曙，谁忍听歌骊。"]},{"t":"雪竹 其一","f":"五言律诗","c":["爱尔便娟质，还堪共岁寒。","湘妃珠积泪，云母玉为冠。","直节淩寒易，清标傅粉难。","王猷恋幽赏，曾否剡溪看。"]},{"t":"雪竹 其二","f":"五言律诗","c":["戛戛鸣残雨，漪漪傲晓阳。","宋人失玉叶，梁苑有霓裳。","扫月寒相映，淩烟黛罩光。","他时郢客曲，应入凤萧长。"]},{"t":"明月照积雪 其一","f":"五言律诗","c":["千门矜瑞雪，一镜映寒空。","世界玲珑里，云山清净中。","交辉逼庭树，隐耀入帘栊。","此夕怀乡国，应迷度岭鸿。"]},{"t":"明月照积雪 其二","f":"五言律诗","c":["阶前纷六出，岂落广寒花。","自照金茎色，平连玉塞沙。","近梅神共媚，浮练影俱斜。","欲拟阳春曲，霓裳未可誇。"]},{"t":"送金德润出宰江阴","f":"五言律诗","c":["送君初出宰，万树发春萌。","柳色辞寒浅，桃花到县明。","庭阴閒吏事，溪水入琴声。","只恐朝天日，难为借冠情。"]},{"t":"署中杂咏 其一","f":"五言律诗","c":["自窃蓬瀛籍，长违丘壑年。","宦途虽险仄，冰署少攀缘。","紬书迎牖旭，载笔傍炉烟。","迂拙真可补，还谈碣石天。"]},{"t":"署中杂咏 其二","f":"五言律诗","c":["明时虽释褐，束带尚青袍。","稍便趋迎少，兼无簿领劳。","署连宫树密，坐对苑云高。","自笑清华署，朝朝濡腐毫。"]},{"t":"署中杂咏 其三","f":"五言律诗","c":["青藜吹太乙，天禄有藏书。","秘欲探鸿宝，讹难辨鲁鱼。","文章惭卤莽，岁月感居诸。","相过同心友，高言间起予。"]},{"t":"署中杂咏 其四","f":"五言律诗","c":["清华供奉署，寂寞草玄庐。","簪绂吾何有，烟霞意未除。","清池花覆槛，白昼鸟窥书。","细捡囊中草，淩云愧不如。"]},{"t":"过荏平县","f":"五言律诗","c":["故人为政地，四野足弦歌。","租吏打门少，耕人驱犊多。","花阴深卧阁，鹤径长垂萝。","为问神仙宰，鸣琴意若何。"]},{"t":"南还途次感怀 其一","f":"五言律诗","c":["三载缁尘意，悠悠那可论。","有官依玉署，无策献金门。","暂适烟霞疾，难忘棫朴恩。","暮云千里色，天际一凭轩。"]},{"t":"南还途次感怀 其二","f":"五言律诗","c":["往来关吏识，景物忆三年。","荣利应何有，行藏信自然。","马头冲毒热，徒驭饱风烟。","计日乡园道，秋风鲈鲙边。"]},{"t":"南还途次感怀 其三","f":"五言律诗","c":["虚传韦杜曲，尺五去天居。","近见丝纶府，还淹痛哭书。","帝阍呼不达，谏院席全虚。","窈有处堂虑，无言杞国愚。"]},{"t":"南还途次感怀 其四","f":"五言律诗","c":["河渡古徐州，淮阳下接流。","宣房筑何日，瓠子决堪忧。","漕使道傍议，冬官传舍谋。","百万东南粟，将无虑咽喉。"]},{"t":"南还途次感怀 其五","f":"五言律诗","c":["经过徐北地，凭轼问兴亡。","王霸千秋气，山川百战场。","圣明开草昧，日月洗洪荒。","卜世金瓯重，何当计彻桑。"]},{"t":"南还途次感怀 其六","f":"五言律诗","c":["驿馆夜沈沈，朝来小雨侵。","望山披爽气，凭轼动微吟。","水近田差润，云归山半阴。","何当一滂沛，处处足甘霖。"]},{"t":"南还途次感怀 其七","f":"五言律诗","c":["经时旱太甚，一雨未为霖。","复此淋漓下，方知天地心。","负槔还野屋，驱犊下高岑。","顿觉烦嚣洗，悠然惬素襟。"]},{"t":"与马元伯及仁伯代骧两弟集梁明叔禅悦楼 其一","f":"五言律诗","c":["清斋三载别，下榻重踌蹰。","壁认曾题字，床披积蠹书。","寒花开曲沼，落叶满庭除。","别有关幽事，篱前一径蔬。"]},{"t":"与马元伯及仁伯代骧两弟集梁明叔禅悦楼 其二","f":"五言律诗","c":["四海交游意，何如旧社怜。","论心多往事，问业出新篇。","奇字推扬子，清言到惠连。","坐来幽意惬，同醉夜灯前。"]},{"t":"和马元伯韵","f":"五言律诗","c":["小雨开新霁，城头隔夕阳。","冬花无雪意，暮色尚秋凉。","喜洽班荆语，劳歌伐木章。","挥杯忘潦倒，莫笑竹林狂。"]},{"t":"读欧子建澹圃诗记寄示","f":"五言律诗","c":["传闻开径地，风物改新观。","未遂剡舟访，先飞郢雪寒。","三年怜雁字，一水忆鱼竿。","期尔秋江上，相将共采兰。"]},{"t":"郭朝谔给谏以建言谪江右幕官诗以讯之","f":"五言律诗","c":["闻上兰台疏，危言批颔鳞。","官宁甘廓落，道岂混风尘。","量谪君恩重，还家客思新。","江湖逾恋阙，伫待拜徵纶。"]},{"t":"丙辰除夕","f":"五言律诗","c":["病废乡园久，明朝又见春。","无闻四十老，有尽百年身。","违俗宁关傲，微官祇益贫。","夜阑望北斗，坐待日华新。"]},{"t":"白广文举子","f":"五言律诗","c":["谁言毡独冷，又见凤毛奇。","绛帐谈经日，明珠入掌时。","鳣堂惬熊梦，芹舍长兰枝。","未论阿罗好，先传白傅诗。"]},{"t":"秋夜梦游一寺得一首醒来失记第五六句因补成之","f":"五言律诗","c":["一入空门静，泠然出世情。","山猫眠暖日，野犬吠秋声。","败衲将云补，疏钟杂涧鸣。","欲儗庞居士，悠悠老未成。"]},{"t":"阴雨久阻看梅因移一株植之斋头招何龙友同诸子过赏","f":"五言律诗","c":["乡落论幽事，探梅酒每赊。","雨天常负约，冰砌特移花。","月下新妆淡，风前冷艳斜。","扬州如有赋，应早过山家。"]},{"t":"挽赵丕振","f":"五言律诗","c":["相思隔穗石，踪迹转堪疑。","仙去骑羊后，书传赋鵩时。","还丹君术误，逝水我心悲。","欲策素车去，寒江阻后期。"]},{"t":"早春杂兴八首 其一","f":"五言律诗","c":["短发经霜后，春来不那梳。","药囊閒自检，瓜地与僮锄。","嗜酒还忧病，逋诗为懒书。","晚天归网集，随意市江鱼。"]},{"t":"早春杂兴八首 其二","f":"五言律诗","c":["翻怜童稚日，嬉戏入春多。","买彩装灯胜，招群共踏歌。","生年嗟老大，情兴与蹉跎。","寂寞花前酒，风光又一过。"]},{"t":"早春杂兴八首 其三","f":"五言律诗","c":["草阁临溪上，溪光颇自宜。","疏林鸣翡翠，暖日晒鸬鹚。","蓑笠还堪问，濠梁谁与期。","倘有山阴棹，能无访戴逵。"]},{"t":"早春杂兴八首 其四","f":"五言律诗","c":["乡园春事好，花柳称幽盟。","地僻堪投老，身閒不用名。","妇倾新酿熟，客至晚香清。","岂敢耽佳句，行吟亦遣情。"]},{"t":"早春杂兴八首 其五","f":"五言律诗","c":["隔年秋半夜，风俗验晴阴。","岂谓灯宵月，微云无处寻。","儿童行乐地，邻曲岁时新。","俯仰成今昔，幽怀付醉吟。"]},{"t":"早春杂兴八首 其六","f":"五言律诗","c":["经旬天不雨，抱汲借溪流。","稍便春游路，将无稼事忧。","三年还卧病，数口可谁谋。","但遣清尊在，酣歌万虑休。"]},{"t":"早春杂兴八首 其七","f":"五言律诗","c":["去年朔气重，煖意早春多。","酒熟花争发，帘开鸟自歌。","懒锄从蔓草，多病称烟萝。","一夜催花雨，朝添池上波。"]},{"t":"早春杂兴八首 其八","f":"五言律诗","c":["岭南无腊梅，爱此春还开。","日暖欺冰影，风柔点绿苔。","几迟仙客梦，如待驿书来。","寄语怜芳侣，哪堪负举杯。"]},{"t":"岁暮漫兴和伍国开韵 其一","f":"五言律诗","c":["晏岁论心事，偏于淡者亲。","阴阳双去鸟，岁月一閒人。","幸假清时沐，何妨野老邻。","焚香发疏磬，又过一清晨。"]},{"t":"岁暮漫兴和伍国开韵 其二","f":"五言律诗","c":["粉墙红蕊吐，已觉春风赊。","窗虚落迟日，山近送明霞。","簪绂真长物，渔樵自一家。","所关心事者，梅树渐飞花。"]},{"t":"秋日伍国开有开定国侄过赏五丫兰 其一","f":"五言律诗","c":["开关迎二仲，始觉秋声回。","落日丛兰里，奇花故故开。","无人涉湘去，有客援琴来。","不作留连赏，零霜恐易催。"]},{"t":"秋日伍国开有开定国侄过赏五丫兰 其二","f":"五言律诗","c":["九畹传幽况，湘皋夙擅名。","几闻开五颖，还得共孤茎。","浥露金光细，摇风朵佩轻。","美人应采撷，投赠不胜情。"]},{"t":"王番禺奏绩 其一","f":"五言律诗","c":["羡君为宰处，彷佛昔河阳。","帘对白云岭，琴鸣珠海傍。","春城桃柳媚，秋郭稻粳香。","满目含哺者，真同帝力忘。"]},{"t":"王番禺奏绩 其二","f":"五言律诗","c":["抚字已三载，心劳政始敷。","最书昨日上，循吏此时无。","美锦辉花县，寒冰映玉壶。","只愁朝汉去，岭外渺双凫。"]},{"t":"寄讯韩绪仲先生南还兼订罗浮之约 其一","f":"五言律诗","c":["长安三载别，如隔五云间。","此日金门客，秋风又远还。","心情恋丘壑，性字领仙班。","咫尺罗山路，能期杖屦攀。"]},{"t":"寄讯韩绪仲先生南还兼订罗浮之约 其二","f":"五言律诗","c":["古循城下路，仙洞敞朱明。","忆我杖藜处，羡君昼锦情。","暂为丹灶往，有待赤松盟。","寄语飞云长，鸾骖倘并迎。"]},{"t":"送何龙友北上","f":"五言律诗","c":["十载公车意，飞腾老擅场。","剑看龙正跃，吾避雁为行。","玉署莺簧早，金河柳线长。","此时客思好，尺素远相望。"]},{"t":"初冬伍国开有开有看梅之约以雨屡阻至十月既望始共探赏分赋二首 其一","f":"五言律诗","c":["花期劳豫约，及此得邀欢。","落日寒山外，开尊坐石栏。","欺春先自放，映月晚逾寒。","未遣愁吹笛，新枝正耐看。"]},{"t":"初冬伍国开有开有看梅之约以雨屡阻至十月既望始共探赏分赋二首 其二","f":"五言律诗","c":["忆归方四载，四赏故园梅。","为爱先春意，同寻泛月杯。","星星冰艳见，细细冷香回。","莫以流光感，翻令怀不开。"]},{"t":"答伍国开雨中见怀之作 其一","f":"五言律诗","c":["量晴空日日，一雨竟连绵。","听处难为夜，愁深况近年。","知君事幽对，闭户有閒缘。","武陵归计好，莫为世人传。"]},{"t":"答伍国开雨中见怀之作 其二","f":"五言律诗","c":["世事屏居断，淋漓亦快人。","所怜陇头树，易负杯中春。","独立望空外，同声限比邻。","冲坭来锦字，一倍见情亲。"]},{"t":"答伍国开雨中见怀之作 其三","f":"五言律诗","c":["小楼依密树，烟雾昼冥迷。","雨叶晴时落，风枝梦里凄。","无由恣欢赏，聊以托幽栖。","乘兴何言远，门前有剡溪。"]},{"t":"步杪何氏听潮阁赏梅同伍国开诸子分赋 其一","f":"五言律诗","c":["造园不相识，吾爱子猷狂。","况是高人宅，招携意倍长。","当门乱竹立，亚水几花香。","何□罗浮梦，居然见澹妆。"]},{"t":"步杪何氏听潮阁赏梅同伍国开诸子分赋 其二","f":"五言律诗","c":["梅花东阁赋，仙侣武陵招。","索笑情何剧，寻源兴不遥。","歌喉清并倚，酒户醉相骄。","未觉年芳晚，风流事事饶。"]},{"t":"早春独坐漫成","f":"五言律诗","c":["非缘耽寂寞，多病称萧閒。","春换枝头色，年催愁里颜。","好眠身习懒，异俗户常关。","赖有嘤嘤鸟，长林日往还。"]},{"t":"送仁伯弟西游觐省","f":"五言律诗","c":["忽动白云思，当春理彩衣。","风烟一弟隔，鸿雁异行飞。","问礼趋庭远，宁亲作吏微。","江蓠芳可撷，莫忘尺书归。"]},{"t":"中秋伍国开同诸弟侄过集建霞楼忆先二年中秋伍俱有约不果至","f":"五言律诗","c":["有约曾三度，良宵此会难。","月中倾小酒，物外得清欢。","轮走云容递，香飘桂影残。","金波浮太液，光彩忆长安。"]},{"t":"秋夜雨后月色太佳中夜起坐漫成二律 其一","f":"五言律诗","c":["有怀中夜起，凉月正当帘。","展卷情俱懒，焚香手自拈。","云疏桂影落，风劲竹声添。","幽意无人解，披衣自绕檐。"]},{"t":"秋夜雨后月色太佳中夜起坐漫成二律 其二","f":"五言律诗","c":["淋漓一雨后，片月洗逾鲜。","懒性虽慵起，清辉耐可怜。","酒难孤影对，茗倩小僮煎。","谁悟尘嚣里，须眉一病禅。"]},{"t":"立冬日寓羊城黎君选何赞侯陶摇光傅贞父彭伯时戴安仲同区启图区叔永诸子携酒见过","f":"五言律诗","c":["客舍怜岑寂，多君问字情。","秋光失落日，朔气入初更。","对酒露狂态，论诗狎主盟。","旧游与新好，兹会亦平生。"]},{"t":"初冬黄元卿园林与黎缜之冯稚谟韩孟郁赵裕子欧子建邓伯乔诸子分赋","f":"五言律诗","c":["旧游疏散后，复此聚园林。","落日迟秋色，空亭称远心。","酒酣黄鸟至，坐久白云深。","不尽兹宵赏，宁堪老病寻。"]},{"t":"客与余话出山事怅然有作","f":"五言律诗","c":["话到出山事，踟蹰思万端。","官贫随仆少，道远挈家难。","人面终难信，余腰不哪酸。","黄粱炊未熟，几欲醒邯郸。"]},{"t":"将游罗浮舟发榄海","f":"五言律诗","c":["为有登山兴，先寻荡桨游。","烟波开积抱，景物况清秋。","缓酌醉多适，微吟趣自由。","兹宵如有梦，应预到丹邱。"]},{"t":"宿黄龙洞早起出坐流杯石","f":"五言律诗","c":["山眠披雾起，选石出林邱。","玉乳千秋漱，云光镇日浮。","放歌来独鹤，争席狎群鸥。","顿觉尘心洗，丹砂不待求。"]},{"t":"问道出黄龙洞","f":"五言律诗","c":["罢饭辞仙洞，下山日未中。","浓烟晴渐减，远树望成空。","认瀑涧多似，扪萝径忽通。","但随樵采往，何用畏途穷。"]},{"t":"白莲池","f":"五言律诗","c":["麻姑仙去后，曾此驻云车。","漾月长悬镜，澄潭不见花。","蓬莱几清浅，古洞自年华。","箫管商风发，犹疑下蔡家。"]},{"t":"出增江与仁伯弟舟中夜酌","f":"五言律诗","c":["晚发增江岸，晴霞片片生。","乱山迎棹出，孤鹤掠舟横。","海阔月先得，天寒酒屡更。","夜阑酬劝罢，横被到天明。"]},{"t":"九日增江舟中与仁伯代骧两弟小酌","f":"五言律诗","c":["何事登高会，翻为荡桨游。","青山曾几日，沧海正宜秋。","落照低鸿影，空江罢钓舟。","举杯兄弟在，不动插萸愁。"]},{"t":"初冬游樵舟中同伍国开有开望新月有赋","f":"五言律诗","c":["江畔看新月，芦汀一系舟。","蟾寒光乍减，兔小练初浮。","未辨云山色，仍怜乌鹊愁。","赠君不盈手，聊共对清幽。"]},{"t":"晚泊大富村 其一","f":"五言律诗","c":["维舟上断岸，曲径石桥斜。","林迥衔残日，湖空宿落霞。","往来见渔艇，三五出人家。","向晚看潮长，桃源或有花。"]},{"t":"晚泊大富村 其二","f":"五言律诗","c":["咫尺西樵路，人家别一村。","山川淳朴处，井里凿耕存。","有客看游艇，呼童问水源。","潮生催解缆，江上正黄昏。"]},{"t":"夜泊观山市海即西樵山下 其一","f":"五言律诗","c":["五岳他年事，孤云此日情。","幽期一以惬，尘累肯相撄。","雁影帆前度，渔灯望里明。","山情兼水意，应入梦魂清。"]},{"t":"夜泊观山市海即西樵山下 其二","f":"五言律诗","c":["去年归橐解，便往访罗浮。","此日烟霞侣，还乘樵岭秋。","湖光双桨入，雨色片帆收。","一夜山前水，潺湲到枕头。"]},{"t":"至云路村作","f":"五言律诗","c":["最怜幽绝处，村落数家通。","犬吠竹声里，鸡鸣茅屋中。","采茶山下妇，伐木荷锄翁。","何事避秦去，居然人外踪。"]},{"t":"宿云路村","f":"五言律诗","c":["舟维山下远，借宿半山扉。","乱石堪支枕，苍苔欲上衣。","晓吟猿狖和，晚饭鹤雏归。","惯客儿童喜，真忘鸥鸟机。"]},{"t":"夜与诸子步月","f":"五言律诗","c":["别有山家月，人间异此明。","望崖霜乍积，照树鹊多惊。","与客踏歌处，偏深独往情。","清辉吾欲拾，河汉隔盈盈。"]},{"t":"聚仙台与诸子坐月","f":"五言律诗","c":["仙是何年聚，荒台旧有铭。","罡风璚佩响，彩雾羽衣明。","呼吸通群帝，迢遥隔五城。","坐来江月上，骊颔万珠瑩。"]},{"t":"谒白沙先生祠 其一","f":"五言律诗","c":["衣冠留王气，昭代挺真儒。","绝学谁应续，微言幸不孤。","瞽宗垂俎豆，幽谷想师模。","瞻谒徘徊久，庭前下夕乌。"]},{"t":"谒白沙先生祠 其二","f":"五言律诗","c":["圣宗传主静，疑信乃犹繁。","月旦于今定，宫墙百代尊。","山非紫水路，俗儗白沙村。","五世瞻遗泽，真怜未及门。"]},{"t":"晓发故园","f":"五言律诗","c":["卧里却忘适，出山愿始遗。","聊同蕉鹿梦，岂负冥鸿飞。","何物尘簪绂，抛吾旧钓矶。","儿童填巷口，问客几时归。"]},{"t":"留别诸从弟","f":"五言律诗","c":["五年池草梦，忍别故园春。","薄禄何关弟，长途累送人。","云山乡思远，梅柳客怀新。","莫数天边雁，同行万里亲。"]},{"t":"夜泊峡山寺下","f":"五言律诗","c":["入夜看山罢，怜幽未解桡。","卧云身倍稳，醉月量偏饶。","上界传清梵，长江咽暮潮。","榜人休促发，吾意任萍飘。"]},{"t":"花朝怀故园花事","f":"五言律诗","c":["三春看已半，去去路逾赊。","未厌长征棹，空怀故里花。","风中飘柳絮，雨后长兰芽。","兄弟传觞处，宁忘天一涯。"]},{"t":"登叫岩山寺","f":"五言律诗","c":["推蓬望空翠，舍棹一扳跻。","林密幽藏寺，峰危不受梯。","帆飞江雨后，客到夕阳西。","无限雍门恨，扪苔读旧题。"]},{"t":"同潘使君游龙井","f":"五言律诗","c":["晚舍湖边棹，言登湖上台。","片云孤石立，小雨万山开。","客有逃禅意，僧容入社杯。","啸歌群谷响，疑动蛰龙来。"]},{"t":"过携李陈当时明府招饮烟雨楼 其一","f":"五言律诗","c":["西湖相别后，复此湖亭幽。","不是神仙宰，谁招汗漫游。","江清天似洗，林爽夏疑秋。","顿解风尘色，何妨入夜留。"]},{"t":"过携李陈当时明府招饮烟雨楼 其二","f":"五言律诗","c":["楼阁敞湖中，蓬瀛四望通。","席分孤浦月，林响隔溪风。","夜久烟初散，谈高酒数空。","归来还荡桨，渔火数星红。"]},{"t":"雨中张舒日招游北固山 其一","f":"五言律诗","c":["帆过京口路，停棹一跻扳。","掩映江心寺，微茫云外山。","烟汀鸥鸟浴，暮雨钓舟还。","何事驱车客，劳劳不暂閒。"]},{"t":"雨中张舒日招游北固山 其二","f":"五言律诗","c":["名山宿有约，肯复思冲坭。","兴为探奇鼓，尊兼话旧携。","楼高吞海远，云密压天低。","便醉山中酒，禅床好共栖。"]},{"t":"经沛县 其一","f":"五言律诗","c":["排空淹浊浪，四望失田畴。","国似依龙子，人疑住蜃楼。","歌风遗迹没，逐鹿莽烟收。","今古战场地，漂沦劫未休。"]},{"t":"经沛县 其二","f":"五言律诗","c":["几夜怜淫雨，河流益渺漫。","鱼龙游第宅，舟楫出林峦。","禾黍平畴尽，人烟野戍寒。","差便征客艇，天上坐同看。"]},{"t":"都门立秋 其一","f":"五言律诗","c":["入秋随一日，应候到秋风。","日月双飞鸟，乾坤一转蓬。","凉飔彫蕙草，清露落梧桐。","惆怅乡园梦，迢迢隔楚枫。"]},{"t":"都门立秋 其二","f":"五言律诗","c":["客久偏怜节，天涯又见秋。","宦情仍卤莽，岁月袛优游。","露下蝉吟苦，风前燕语愁。","西山朝气爽，应许马曹收。"]},{"t":"都门立秋 其三","f":"五言古诗","c":["□□□□□，徵调自年年。","闻道榆关上，防秋事杳然。","征衣经岁隔，鼓角得寒先。","无事听鸡起，谁能稳夜眠。"]},{"t":"都门立秋 其四","f":"五言律诗","c":["使节经三夏，淹留秋已生。","身怜羁薄禄，心愧请长缨。","此夜关山月，何人怅望情。","鬓蓬搔已短，不待晓霜惊。"]},{"t":"挽樊孟泰督学 其一","f":"五言律诗","c":["水部为郎日，长安联署时。","相过不作客，对饮或论诗。","人望熊车远，书传鵩赋迟。","归来空一水，音问杳难期。"]},{"t":"挽樊孟泰督学 其二","f":"五言律诗","c":["恩光豸绣重，儒望斗山尊。","何事苍梧署，空开桃李门。","不应为异物，定有未招魂。","千古传灯地，真疑衣钵存。"]},{"t":"挽樊孟泰督学 其三","f":"五言律诗","c":["帝里承恩去，乡园殁后归。","书缘道路阻，交岂死生违。","遥忆鸰原恨，还怜凤穴非。","此时应宿草，忍泣涕还挥。"]},{"t":"中秋夜同何龙友区启图黎有道集韩太史宅","f":"五言律诗","c":["寻常三五夕，一岁此分秋。","月自看燕市，人还聚粤游。","星河低压席，雁影迥连楼。","尽醉仍呼酒，那能念百忧。"]},{"t":"辛酉元日朝回","f":"五言律诗","c":["有道开天启，龙飞又见春。","钩陈新法座，玉帛会臣邻。","瑞雪三花烂，条风万化均。","朝回花底坐，云气染衣巾。"]},{"t":"初冬何龙友集小寓重送区启图","f":"五言律诗","c":["词人重惜别，把饯入严更。","忽动江鲈思，逾深越鸟情。","扬帆冰乍合，倚剑雁初声。","谁念缁尘客，投簪计未成。"]},{"t":"同陈集生崔芷林守岁何龙友寓 其一","f":"五言律诗","c":["寒色销残腊，条风早已均。","言寻乡国侣，共待帝城春。","绿酒杯传蚁，青烟烛吐银。","商量开岁事，休负柳梅新。"]},{"t":"同陈集生崔芷林守岁何龙友寓 其二","f":"五言律诗","c":["帝里年将换，乡心不自聊。","故人开斗酒，深夜惬清招。","朔雪催传柏，春风欲颂椒。","更阑休问寝，共谒紫宸朝。"]},{"t":"同陈集生崔芷林守岁何龙友寓 其三","f":"五言律诗","c":["官曹冰共冷，爱此岁寒天。","相过无朝暮，惊心动岁年。","飞腾终自解，身世且随缘。","渐喜春风雁，南来有信传。"]},{"t":"送何龙友太史册封便道归省","f":"五言律诗","c":["得归人所羡，况复赋皇华。","彩戏宫中锦，萱明堂背花。","三年游子梦，万里使臣槎。","情剧频驱马，春前应到家。"]},{"t":"夜坐","f":"五言律诗","c":["更阑起夜月，幽思未全孤。","碧汉深于染，微云淡欲无。","风砧树相乱，邻酒夜还沽。","此夕思家梦，迢迢隔五湖。"]},{"t":"上谷遇韩绪仲先生暨赵裕子驿馆夜谈","f":"五言律诗","c":["彤庭分玉节，次第出京华。","未远瞻天地，俱停访汉槎。","月寒逾散彩，雪薄不成花。","且莫谈桑梓，王程路尚赊。"]},{"t":"安肃驿","f":"五言律诗","c":["上将谈兵日，中原逐鹿时。","登坛分楚汉，投足定雄雌。","背水奇谁识，藏弓事可悲。","暮云千里色，犹是闪旌旗。"]},{"t":"晚山","f":"五言律诗","c":["未与此游期，兹山何太奇。","皇华趋远道，烟景豁幽思。","马倦仍知路，鸦喧竞绕枝。","凭轩休极目，正切望乡悲。"]},{"t":"次韵奉酬韩绪仲先生邂逅汝南喜赋之作 其一","f":"五言律诗","c":["班荆曾上谷，把袂复江坟。","共是皇华使，犹怜鸿雁群。","太行驱马倦，南浦待桐分。","何日罗浮上，相期理白云。"]},{"t":"次韵奉酬韩绪仲先生邂逅汝南喜赋之作 其二","f":"五言律诗","c":["使星占两地，萍迹怅参辰。","何意驱疲马，犹能及故人。","咨询藩国礼，慰劳客中身。","前路俱难定，尊醪莫厌频。"]},{"t":"人日奉新道中","f":"五言律诗","c":["雪月衔王命，驰驱及早春。","风尘星是客，江海日为人。","谷暖莺声啭，山晴梅意新。","故园花事好，能否待归轮。"]},{"t":"送族弟代璍游曹溪","f":"五言律诗","c":["曹溪溪上路，两度礼毗卢。","一别空门去，谁怜白日徂。","有缘人独往，出世事宁孤。","为问西来意，菩提树有无。"]},{"t":"七夕集何龙友宅","f":"五言律诗","c":["天阶坐七夕，银汉望虚无。","雅会烦襟涤，新凉暑病苏。","月斜蟾影澹，星返鹊桥孤。","此夕相怜意，人间总未殊。"]},{"t":"谢梁孝廉惠菊","f":"五言律诗","c":["今年秋事晚，十月未篱花。","何处孤芳色，分来处士家。","曲栏编蕊密，小径护枝斜。","采采南山见，餐英酒每赊。"]},{"t":"赠何明公","f":"五言律诗","c":["有美子衿者，家承水部声。","龙云光气色，鸦鬓已成名。","抗志追姚姒，搴芳袭杜蘅。","草玄吾已老，负汝问奇情。"]},{"t":"送区叔永游太学","f":"五言律诗","c":["倦翮依村落，闻君发越台。","长风知破浪，一水隔离杯。","入洛人今似，招贤馆更开。","青云多世讲，宁复叹无媒。"]},{"t":"寄题黄逢永薜蕊斋","f":"五言律诗","c":["之子心元远，城居地亦偏。","袭芳非矫菌，得意已忘筌。","笔墨人生乐，琴书静者缘。","何时重载酒，相过问杨玄。"]},{"t":"国璋游泮后新婚","f":"五言律诗","c":["青杏襟初映，夭桃妆乍新。","同依天上种，暂作洞房春。","花烛俱清韵，风光况令辰。","鸡鸣应记取，未是自由身。"]},{"t":"子建过访夜宿建霞楼","f":"五言律诗","c":["经时不相见，相见倍相怜。","碌碌劳生事，星星在鬓边。","开尊连夜语，听雨恋朝眠。","肯负平原饮，轻回访戴船。"]},{"t":"除夕","f":"五言律诗","c":["万里皇华使，君王予假归。","差便宽岁月，多恐负恩辉。","献节条风暖，辞寒腊意微。","朝来四十九，曾否解知非。"]},{"t":"元旦 其一","f":"五言律诗","c":["乡园风物好，又见一年新。","雪失今朝腊，花知昨夜春。","老添频验镜，懒极畏逢人。","好是开怀处，团圆骨肉亲。"]},{"t":"元旦 其二","f":"五言律诗","c":["任说身差贵，曾何事胜前。","所经都少味，渐老又加年。","礼法归来减，春光静里先。","东邻与西里，相过且流连。"]},{"t":"元旦 其三","f":"五言律诗","c":["去年当此日，楚泽泛扁舟。","可是皇华使，真成汗漫游。","五云瞻晓日，万里隔沧洲。","又忆追趋地，何人侍冕旒。"]},{"t":"元旦 其四","f":"五言律诗","c":["营园将阅岁，半亩尚荒芜。","未就青门隐，空惊白日徂。","儿童嬉爆竹，亲友劝屠苏。","捡点春来事，惟应有荷锄。"]},{"t":"元旦 其五","f":"五言律诗","c":["倚楼清晓望，海岳变春阴。","万里孤臣梦，经年病客心。","宦情妨懒慢，身世阅升沈。","为问檐前柳，春风信几深。"]},{"t":"元旦 其六","f":"五言律诗","c":["近得封章报，能容恋五湖。","久归人事变，多病主恩孤。","春似还家客，年同过隙驹。","总无欢赏事，惟有醉模糊。"]},{"t":"早起闻鸟","f":"五言律诗","c":["耽眠常晏起，鸟雀乱前楹。","求友枝头意，偷春舌底声。","群中疑噪聒，静里自分明。","对汝堪终日，都无客送迎。"]},{"t":"新宁刘明府元夜过访村居","f":"五言律诗","c":["倦翮依村落，门荒雀可罗。","何来双玉舄，风雨亦相过。","礼为通家简，情因话旧多。","祇怜遄别去，一水隔弦歌。"]},{"t":"答何凝生","f":"五言律诗","c":["紫芝犹未挹，题赠两缄情。","不负韦贤业，居然水部名。","临风怀玉举，掷地作金声。","三复新编好，令人畏后生。"]},{"t":"甲子立秋 其一","f":"五言律诗","c":["为园堪避暑，况复此新秋。","银汉初窥户，金飙欲到楼。","无人共尊酒，有梦狎沧洲。","便儗乘风去，菰芦问钓舟。"]},{"t":"甲子立秋 其二","f":"五言律诗","c":["海国知秋早，凉生萍末风。","候虫吟四壁，疏雨落孤桐。","齿任衰迟逼，心怜少壮同。","那能悲髀肉，垂老尚樊笼。"]},{"t":"清明与诸从及何龙友晚泊","f":"五言律诗","c":["扁舟逢节序，晚泊席频移。","渐觉乡园远，犹怜亲旧随。","物情轻小草，吾意恋连枝。","后夜相望处，云山总梦思。"]},{"t":"上巳日泊回岐小饮","f":"五言律诗","c":["客行逢上巳，古驿一维舟。","挟有群贤至，犹宜褉事脩。","春深莺啭柳，日落水明楼。","堪叹长征路，劳劳去末休。"]},{"t":"游南禺载笔亭","f":"五言律诗","c":["南岩望北峡，双掌擘芙蓉。","一自禺阳去，长教鸟篆封。","开山今日事，采药异时逢。","坐久尘心洗，遥闻隔寺钟。"]},{"t":"泊豫章漫怀","f":"五言律诗","c":["十年惭小草，两度豫章游。","胜概开吴楚，寒光望斗牛。","人今谁下榻，赋自儗登楼。","欲寄乡心去，长江但北流。"]},{"t":"晚霁见月","f":"五言律诗","c":["几夜怜阴雨，扁舟系不行。","忽此暮云澹，澄澄皓魄生。","长江练影远，旅客梦魂清。","莫听南飞鸟，枝头三匝声。"]},{"t":"庐山归道","f":"五言律诗","c":["耽游不觉晚，山阁送馀晖。","鸣涧流随马，残霞落满衣。","天空看月小，山近见烟微。","客路有如此，行吟可当归。"]},{"t":"登栖贤寺阁","f":"五言律诗","c":["丹梯依宝地，登陟上青冥。","五老平窥户，千峰低列屏。","罡风生下界，紫雾湿疏棂。","此夜天边望，江湖有客星。"]},{"t":"晚过栖贤寺","f":"五言律诗","c":["济胜非无具，跻攀奈夕何。","归云山欲瞑，留客鸟频歌。","行色风尘减，幽怀水石多。","可能衣衲子，一榻老云窝。"]},{"t":"白鹿洞怀古","f":"五言律诗","c":["昔贤倡道地，形胜表西南。","云影晴临席，天光净照潭。","遗风被逢掖，雅会盍朋簪。","千古鸢鱼意，悠悠未许谈。"]},{"t":"大孤山","f":"五言律诗","c":["长湖天接水，幻出此奇峦。","立壁跻扳断，凭虚法界宽。","乾坤容砥柱，江海岂回澜。","明到小孤望，风烟倘共看。"]},{"t":"彭蠡驿再阻风","f":"五言律诗","c":["北行当夏月，怪又滞扁舟。","风候真难定，前程枉预谋。","微微寒雨洒，漠漠瞑云收。","颇爱柳阴月，朦胧照浅流。"]},{"t":"望小孤山","f":"五言律诗","c":["茫茫波万顷，一柱上天都。","映日摇空霭，笼烟望有无。","峰危愁落雁，岩仄隐浮图。","大小犹相望，山名未称孤。"]},{"t":"磨盘山道中","f":"五言律诗","c":["晚过盘山望，悠然寄远心。","云阴移断壑，牧唱下高岑。","倦马仍寻路，饥乌未返林。","低回叹华发，多向此中侵。"]},{"t":"过临淮","f":"五言律诗","c":["临淮当落日，系马有馀思。","问水失濠濮，临风想惠施。","年华更代谢，井邑有流移。","千古观鱼意，悠悠欲语谁。"]},{"t":"早行","f":"五言律诗","c":["驿馆披得起，鸡声唱乱茅。","露珠凝草尾，日彩吐山坳。","飞萤渐失照，梦鹤乍惊巢。","不为简书畏，微官容易抛。"]},{"t":"大店驿","f":"五言律诗","c":["下车逢驿吏，未诉泪交颐。","禄薄怜家远，途冲苦地疲。","轩车谁体恤，马户半流移。","近复开东路，催呼并一时。"]},{"t":"九日与诸年友游栖霞 其一","f":"五言律诗","c":["金陵三月客，今始试游踪。","节是登高会，人怜话旧逢。","市朝多变态，丘壑暂从容。","物虑此俱寂，时闻云外钟。"]},{"t":"九日与诸年友游栖霞 其二","f":"五言律诗","c":["路遥频息驭，选石听泉鸣。","暂谢区中累，聊深物外情。","乱峰低晚照，一雁过秋声。","何事尘簪绂，悠悠误此生。"]},{"t":"九日与诸年友游栖霞 其三","f":"五言律诗","c":["为怜山色好，向晚更提壶。","选胜还初地，登高属旧都。","秋迟留菊蕊，家远忆茱萸。","共借空门宿，藤萝月影孤。"]},{"t":"偕诸年丈游清凉台 其一","f":"五言律诗","c":["未尽登临意，相携上玉台。","云山千嶂合，井里万家开。","日落寒原迥，风生暮壑哀。","迟回江月上，似涌夜珠来。"]},{"t":"偕诸年丈游清凉台 其二","f":"五言律诗","c":["一引凭高目，居然下界分。","江流如带水，山落乍寒云。","雁影高低度，钟声远近闻。","频来逐仙侣，真气动星文。"]},{"t":"长至先日斋居","f":"五言律诗","c":["雍署尘嚣隔，斋头意颇真。","最怜山色近，兼与圣宫邻。","庭静喧林鸟，官閒少吏人。","朝来风物好，遥望物华新。"]},{"t":"送君晓弟归里 其一","f":"五言律诗","c":["寂寞官斋里，春风一弟行。","披襟谈世事，数驿计乡程。","期尔青云起，怜予白发生。","池塘有春草，偏益梦归情。"]},{"t":"送君晓弟归里 其二","f":"五言律诗","c":["忆共离家日，相将又一年。","风尘伤去住，节序感推迁。","宦况只如此，乡心益杳然。","凭汝归山去，先营负郭田。"]},{"t":"寄何太史","f":"五言律诗","c":["忆别峡山后，飘蓬不自由。","生年百已半，宦计七宜休。","候雁遥珠浦，春风到石头。","东山君早起，物望待相酬。"]},{"t":"与侯司马陈民部游木末亭 其一","f":"五言律诗","c":["春色俄将暮，春游爱夕阴。","雨中花似沐，烟外树如沈。","共有怀贤恨，兼悲歧路心。","酒阑多慷慨，吟眺一沾襟。"]},{"t":"与侯司马陈民部游木末亭 其二","f":"五言律诗","c":["披云遥策杖，木末小亭幽。","松柏萧森处，前贤遗庙留。","忠魂伤十族，蘋藻肃千秋。","瞻拜休增感，云山起暮愁。"]},{"t":"桃源县作兼示李明府","f":"五言律诗","c":["桃源空有县，无复见桃花。","长阪希耕犊，中逵闻噪鸦。","驿惟呵候吏，水不泛胡麻。","为问烹鲜宰，哀鸿集几家。"]},{"t":"阻舟济上与李烟客步月 其一","f":"五言律诗","c":["迢递京华路，艰难济上程。","每逢清月夜，宁忘故山情。","独往知何日，同舟赖友生。","登崖聊缓步，不觉漏三更。"]},{"t":"阻舟济上与李烟客步月 其二","f":"五言律诗","c":["海月生遥浦，轮高望转微。","最怜羁旅影，尚与弟兄依。","照树惊乌绕，横江见练飞。","故园千里外，何处赠清辉。"]},{"t":"同烟客诸子游古南池和壁上杜工部韵","f":"五言律诗","c":["水活仍通洫，堤遥碍进船。","觅凉同坐石，荫柳忽闻蝉。","炎暑销当夏，壶觞待晚天。","醉来还藉草，新绿正如毡。"]},{"t":"新秋","f":"五言律诗","c":["金陵多毒热，一雨送新秋。","夜坐凉生竹，朝登露满楼。","近传辽海捷，稍慰至尊忧。","禄食惭何补，应为三径谋。"]},{"t":"萧瑟","f":"五言律诗","c":["萧瑟频年意，逢秋倍不堪。","无媒通魏阙，有梦到江南。","日报攒眉剌，时修媚客函。","消磨少壮去，短发已毵毵。"]},{"t":"宗伯姜仲讱宫詹何龙友学博王季重廿日再过小斋夜集","f":"五言律诗","c":["雅会还堪续，何嫌鸡黍贫。","君原忘礼数，我已领清真。","月冷疑兼雪，宵长莫虑晨。","时能酬此愿，应不叹缁尘。"]},{"t":"九日太史何龙友文学马伯起暨同丈过集 其一","f":"五言律诗","c":["燕山秋欲暮，摇落思难裁。","共是他乡客，宁忘九日杯。","悲秋翻恨雁，怀土懒登台。","却忆龙山会，狂歌意转哀。"]},{"t":"九日太史何龙友文学马伯起暨同丈过集 其二","f":"五言律诗","c":["重阳怜令节，况值此秋晴。","风急轻鸿翼，霜迟逗菊英。","插萸乡国事，落帽古今情。","聊复凭杯酒，陶然醉友生。"]},{"t":"周玉绳年兄迁居道院屡疏乞身初夏过访漫赋 其一","f":"五言律诗","c":["城东道院静，聊得谢扳援。","易退知臣意，留行哪主恩。","飞花过初夏，伏枕足閒门。","共有冥鸿思，风尘未敢论。"]},{"t":"周玉绳年兄迁居道院屡疏乞身初夏过访漫赋 其二","f":"五言律诗","c":["仕途原少味，所趣在弹冠。","子计欲归去，予情已尽阑。","行藏从所好，非誉总何干。","独有酬知遇，涓埃亦自难。"]},{"t":"周玉绳年兄迁居道院屡疏乞身初夏过访漫赋 其三","f":"五言律诗","c":["岂难轻襆被，难契是恩深。","玉立人嫌洁，金门疏亦沈。","卜居非傲物，扫榻为知音。","若论平生意，应无负此心。"]},{"t":"仲夏同黄玉崙先生暨何龙友韩孟郁二丈游城北园池和黄韵","f":"五言律诗","c":["北郭陂塘迥，西山石乳通。","会怜河朔饮，人儗竹林同。","柳雨飘新翠，荷风落晚红。","坐忘尘组绂，犹系市朝中。"]},{"t":"游定国公园 其一","f":"五言律诗","c":["炎暑无逃处，还来问水滨。","径疑曾到地，花认昨游人。","树密堪移席，林深似有津。","若容长住此，不用叹缁尘。"]},{"t":"游定国公园 其二","f":"五言律诗","c":["荷花京国赏，红萼占横塘。","莫以怜孤艳，翻令念故乡。","碧筒聊作献，绿叶未裁裳。","留宿非难事，归途爱月光。"]},{"t":"送高侍御谪官南归 其一","f":"五言律诗","c":["炎蒸三伏后，一雨欲来秋。","但惜故人别，非关迁客愁。","骊歌易水暮，归路岭云稠。","到日江鱼好，谁同上酒楼。"]},{"t":"送高侍御谪官南归 其二","f":"五言律诗","c":["策蹇辞京国，人还认旧骢。","圣朝无市虎，吾道有冥鸿。","放谪恩原重，浮沈术始工。","家山未相远，好待桂花丛。"]},{"t":"送高侍御谪官南归 其三","f":"五言律诗","c":["已恨交亲少，哪堪尔复还。","清秋焚谏草，白发待斑斓。","臣自欢开网，君原许赐环。","苍生同系望，莫便稳东山。"]},{"t":"野泊","f":"五言律诗","c":["小泊西凉岸，相携上翠微。","天长人独立，江阔雁孤飞。","世路悲戎马，乡心阻钓矶。","故园春酒熟，应亦望予归。"]},{"t":"泊繁昌","f":"五言律诗","c":["晓发芜湖棹，向晚达繁昌。","风便帆樯稳，天空海气凉。","身閒惟问酒，睡醒或焚香。","更听渔歌发，前川下钓航。"]},{"t":"舟中月夜怀韩孟郁","f":"五言律诗","c":["忆别金陵柳，相将又一旬。","每逢吟咏处，难忘和歌人。","雁落孤帆影，花飞夹岸春。","此时雍署里，杯酌与谁亲。"]},{"t":"赠","f":"五言律诗","c":["羡尔考槃者，幽栖不问年。","青云看世业，白雪入朱弦。","看竹辞鸠杖，寻芝伴鹤眠。","玉堂传诰日，谁识地行仙。"]},{"t":"平原舟次逢董思白先生 其一","f":"五言律诗","c":["七年石城下，犹记别时颜。","此日予重往，逢君应召还。","时艰知念切，道路阅头斑。","且惬良辰赏，扁舟共采兰。"]},{"t":"平原舟次逢董思白先生 其二","f":"五言律诗","c":["舟行闻与见，不异在都时。","何意平原道，欣瞻云汉仪。","巢许箕山意，夔龙圣代私。","寸心倾未得，风雨促分歧。"]},{"t":"平原舟次逢董思白先生 其三","f":"五言律诗","c":["至人不碍世，出处亦何情。","闻道纶扉上，于今待老成。","因之怀凤德，敢以付嘤鸣。","自有冥鸿意，无烦猿鹤惊。"]},{"t":"平原舟次逢董思白先生 其四","f":"五言律诗","c":["芳辰凑良会，哪得再寻常。","不尽尘中话，兼多世外商。","龙驯宁自性，鸥狎未飞翔。","安石东山在，苍生引望长。"]},{"t":"同黄石斋宫允阻舟临清黄以四诗见投次和 其一","f":"五言律诗","c":["汪汪黄叔度，千顷幸相依。","浮海谋非拙，乘风愿已微。","烟霞盟有约，时事赋无衣。","得似南来雁，芦汀到处归。"]},{"t":"同黄石斋宫允阻舟临清黄以四诗见投次和 其二","f":"五言律诗","c":["中外鸱鸮剧，谁怀之好音。","未偿蹈海意，惭负济川心。","我去位仍窃，君归山岂深。","风烟闽粤近，招隐好相寻。"]},{"t":"同黄石斋宫允阻舟临清黄以四诗见投次和 其三","f":"五言律诗","c":["岂不畏行役，其如世路何。","人情偏局面，宦籍亦风波。","竭泽游鳞少，寒山哀雁多。","不然终滞此，几欲问行輠。"]},{"t":"同黄石斋宫允阻舟临清黄以四诗见投次和 其四","f":"五言律诗","c":["轮囷万乘器，为有先容根。","任笑徒工瑟，何曾解扫门。","敢言三礼重，还自一邱尊。","幔亭春色好，暂去坐絪缊。"]},{"t":"为王非熊宗伯题天漱亭","f":"五言律诗","c":["小亭天结搆，清迥绝尘氛。","有酒时邀月，无人独卧云。","空泉潴作沼，飞翠自成纹。","颇怪端居懒，何心学离群。"]},{"t":"舟眠夜起","f":"五言律诗","c":["绳床能几许，半被月侵眠。","近暑仍惊露，当林或听蝉。","更长归梦乱，客久得愁偏。","取醉还欹枕，晨钟又到船。"]},{"t":"舟中对酒","f":"五言律诗","c":["舟閒惟对酒，颇快是临流。","水涩风虚顺，崖高日易收。","客盘虾菜美，乡思雁声愁。","更道粮艘急，前途恐滞留。"]},{"t":"济上阻舟","f":"五言律诗","c":["维舟济水次，对酒强微吟。","道路浮生梦，乡园游子心。","未能谢羁束，聊自任浮沉。","应愧南来雁，冥冥孰可寻。"]},{"t":"早春 其一","f":"五言律诗","c":["入春才几日，花草竞抽芳。","对酒风生座，钩帘月满堂。","无书托鸿雁，有梦到江乡。","吏况原兼隐，何妨昼卧长。"]},{"t":"早春 其二","f":"五言律诗","c":["羁思无穷已，风光且绿尊。","雪馀天悔虐，春至鸟多言。","宦以拙增傲，吾兼懒避喧。","礼曹公牍简，吏散任关门。"]},{"t":"早春 其三","f":"五言律诗","c":["春色开年浅，登台百感生。","条风初实柳，淑气欲催莺。","琴剑看无赖，莬裘计未成。","无人共杯酒，小酌亦多情。"]},{"t":"卢原甫与陈孺登过集 其一","f":"五言律诗","c":["客怀长落落，经月罢登台。","忽有高人至，柴荆雨亦开。","青馀霜后竹，春在水边梅。","鹦鹉论词赋，应知属楚才。"]},{"t":"卢原甫与陈孺登过集 其二","f":"五言律诗","c":["经旬不见月，乍喜吐如钩。","不尽酬幽思，因之更上楼。","懒云当槛住，小雨剧谈收。","随意恣欢赏，过从亦胜游。"]},{"t":"李临淮招游清凉台 其一","f":"五言律诗","c":["障空微架椽，眺远洞开窗。","一纵孤亭望，居肽万境降。","山花晴朵朵，江舶暮双双。","暂觅閒身得，何妨倒玉缸。"]},{"t":"李临淮招游清凉台 其二","f":"五言律诗","c":["入户见空翠，登登不了青。","兴趣怜吾党，来游复此亭。","归骖促暮酒，醉眼乱春星。","流连海棠下，未忍别山庭。"]},{"t":"王遂东民部同刘田二兄初夏过集","f":"五言律诗","c":["夏浅仍无暑，昼长乐事全。","论诗过水部，联骑复高贤。","柏古肤留韵，荷新叶已偏。","可堪初月上，不为少流连。"]},{"t":"送卢原浦还家寿母","f":"五言律诗","c":["还家非倦羽，所念在慈闱。","莱綵一以舞，秋云无复飞。","即看庭玉秀，总媚树萱晖。","介母能偕隐，青山计未非。"]},{"t":"送李筼谷以南大廷尉晋少司空 其一","f":"五言律诗","c":["亦同京雒地，差快少缁尘。","以我宦情薄，多君友道真。","眷知偏内简，官未积前薪。","政今将在子，谁当社稷臣。"]},{"t":"送李筼谷以南大廷尉晋少司空 其二","f":"五言律诗","c":["脉脉秦淮道，无言送尔行。","艰危四海阔，去住一身轻。","衮以近需补，官因远易称。","悟来萍梗迹，不作别离情。"]},{"t":"元旦偶成","f":"五言律诗","c":["白门重改岁，爱此晓光鲜。","阁对钟山霭，窗临淮水烟。","贺年仪节简，酌柏性情全。","披拂春枝动，东风莫讶颠。"]},{"t":"王季重董得庵携酒夜过","f":"五言律诗","c":["载酒忘宾主，因谐投辖缘。","客谈高夜色，宦况似冬天。","会喜何勘旧，歌听渭雨传。","坐深有七发，药裹遂堪捐。"]},{"t":"送唐□□操江 其一","f":"五言律诗","c":["亦缘来白下，始得此良朋。","未谢为官累，先倾出世情。","投閒吾尚阻，请乞尔非轻。","顿觉相关切，羞他丛桂盟。"]},{"t":"送唐□□操江 其二","f":"五言律诗","c":["进贤冠未脱，话去几无疑。","似此离尘意，差堪静者知。","畏人难速避，见事已惭迟。","计日分吴越，青山共紫芝。"]},{"t":"送唐□□操江 其三","f":"五言律诗","c":["任说官无累，何如解去时。","随缘事莫试，独往兴何疑。","罗浮已驰檄，云水岂无期。","各自寻生活，难容念别离。"]},{"t":"睡佛寺","f":"五言律诗","c":["娑罗佛前树，闻已阅齐梁。","为问千灯接，何如一睡长。","坛虚无讲席，殿老不焚香。","兴废休关感，吾生总梦场。"]},{"t":"香山寺","f":"五言律诗","c":["山色青无尽，都来入此轩。","观空天变幻，窥磴石飞翻。","客爱跻登险，僧忘应对烦。","绳床容小憩，清绝梦中魂。"]},{"t":"赠黎缜之","f":"七言律诗","c":["物外怜君万虑宽，才名三十旧登坛。","山中采药萝为服，竹里题诗箨作冠。","岂为漂零身转傲，向来肮脏路逾难。","朱弦且莫誇高调，任是沾裳未可弹。"]},{"t":"黎缜之赵丕显丕振欧子建过馆赏紫菊 其一","f":"七言律诗","c":["雪月初移野径芳，还留秋色媚山堂。","丹心晚带晴霞艳，密藿朝含宿雾香。","违世共顷陶令酒，餐英宁学楚臣狂。","江梅尚隔花时远，幽赏那能不尽觞。"]},{"t":"黎缜之赵丕显丕振欧子建过馆赏紫菊 其二","f":"七言律诗","c":["年华惟汝殿芳菲，岂有怜芳赏更违。","病客独留荒径在，故人须醉白衣归。","即看晕日香逾暖，况是淩霜叶未稀。","一掇寒英心自远，肯辞潦倒负秋晖。"]},{"t":"小金山寺同诸子送别张明府","f":"七言律诗","c":["旧识灵洲海上山，金银楼阁出人间。","空中似听吹笙过，定里如闻振锡还。","方丈香分荀令袖，九还丹驻葛洪颜。","凭君取醉东林酒，明发双凫未可攀。"]},{"t":"夏日酌赵氏园亭","f":"七言律诗","c":["一笑风波各路岐，重来未改习家池。","尊开白社同盟地，话到青灯半夜时。","露濯芰荷香泛泛，月临杨柳影垂垂。","与君且恣邱中赏，莫向云霄念别离。"]},{"t":"芒鞋","f":"七言律诗","c":["世上驱驰祇自纷，芒鞋有路出尘氛。","春晴踏遍千郊翠，秋好穿残五岳云。","幽意只同藜杖得，閒踪时趁鹿麋群。","侯门珠履三千客，野外谁堪半席分。"]},{"t":"白鹦鹉为方伯情赋","f":"七言律诗","c":["鹦鹉西来自垄坁，西山霜霰若为姿。","尊前最忆祢衡赋，洲畔空传李白诗。","学语共怜多慧质，垂头如亦解愁思。","雪衣旧羡莲花舌，明月珠宫何处期。"]},{"t":"仲秋日同黎缜之邓伯乔访欧子建饮贻安堂其诸从同集","f":"七言律诗","c":["银烛江乡此夜清，更阑洗酌喜初晴。","交论意气无新故，语洽清狂见弟兄。","正倚纵横诗兴发，莫因萧瑟壮心惊。","月华况近中秋色，肯负平原十日情。"]},{"t":"同诸子过欧虞部蘧园水阁","f":"七言律诗","c":["欲向孤亭问草玄，菟裘犹在赤花边。","空林半入山樵道，曲径平分野犊眠。","槛外潮声翻夕照，篱前秋色散荒烟。","风流顿觉前修尽，徙倚楼头思悄然。"]},{"t":"到锦溪仅得欧经季丈人一晤别后赋寄","f":"七言律诗","c":["十年曾忆紫芝眉，雪夜山阴棹故移。","麈尾乍聆杯底语，虎头犹想画中诗。","花洲露冷江如练，龙社秋深柳尚丝。","翻笑逢君如梦寐，祇赢今日寄相思。"]},{"t":"重过姚约如是庵赏菊","f":"七言律诗","c":["初秋下榻留风雨，餐菊重来秋杪时。","岁月已拚杯底过，芳菲犹喜眼中私。","繁英不用编篱护，密叶从教傍砌披。","自是秋光无早晚，还寻蓬径问花期。"]},{"t":"为李珏甫悼亡","f":"七言律诗","c":["遥忆安仁赋悼亡，断弦难听凤求凰。","愁开绣幌窥秋月，懒卷珠帘任夜霜。","梦里似闻归佩响，招来难觅返魂香。","残机半就鸳鸯锦，不尽伤情拭泪行。"]},{"t":"秋杪同邓伯乔郑宗礼集赵丕振园亭","f":"七言律诗","c":["选地为园小结庐，一邱亦自足樵渔。","久缘意气同开社，岂为漂零赋卜居。","丛竹渐含霜色冷，残荷犹傍晚凉舒。","秋光容易留欢赏，宁遣高阳雅会虚。"]},{"t":"花朝伍国开同其季弟有开见访旋为别席催去","f":"七言律诗","c":["宅枕清流一径斜，美人相过踏飞花。","瑶林乍浥青霄露，玉树双披晓日霞。","灵运旧曾誇令弟，孔融今喜识通家。","烹葵未荐芳辰酒，容易分携隔水涯。"]},{"t":"癸卯秋杪还山作","f":"七言律诗","c":["摇落西风一敝裘，黄花犹及故园秋。","归心正惬蒪鲈思，野性何妨鹿豕游。","世路几人怜白璧，生涯聊自委沧洲。","门前片石清流上，竟日高眠狎海鸥。"]},{"t":"长至后一日伍家珍伍国开见过","f":"七言律诗","c":["萧瑟残年自掩扉，可堪节候与心违。","因逢梅树园边客，始觉阳春坐上归。","贫病故人还共狎，交疏时俗任相非。","藜羹且醉寒宵酒，莫待他时剡雪飞。"]},{"t":"村居得欧子建书寄答","f":"七言律诗","c":["琭玉斋中坐夜分，雄谈孤绝更无群。","尔时肮脏高相许，此日漂零那可闻。","梦后屋梁馀落月，愁来天外失停云。","江乡腊近新醪熟，咫尺何缘一醉君。"]},{"t":"寄怀方生伯情","f":"七言律诗","c":["少年白皙胜王昌，文藻风流更擅场。","一自词坛逢少侠，愈令吾党有辉光。","论交尚忆清秋月，握别俄惊白雁霜。","赋就不堪摇落思，故人曾否念倡狂。"]},{"t":"村斋雨后怀马伯起","f":"七言律诗","c":["高阳旧事可谁论，落落幽居但怆神。","独夜有怀愁听雨，百年多病负逢春。","槛梅欲结枝枝实，堤柳初萦缕缕新。","物色风光俱可赋，祇怜孤唱易沾巾。"]},{"t":"孟总戎生日新膺简命","f":"七言律诗","c":["万里提封建汉旌，貔貅千队振军声。","风清海国春归马，雨过鲸鲵夜洗兵。","简命即看黄钺重，烟霞宁忘赤松盟。","歌钟日暮侯门宴，乞得金浆自露茎。"]},{"t":"寿梁孝廉明一尊人六十","f":"七言律诗","c":["六十栖迟化日长，一区衡泌乐洋洋。","岂凭服食留华发，自任鸿濛到上皇。","遗少黄金籯不满，种多丹桂玉生香。","会稽举案家声在，偕老人疑旧姓梁。"]},{"t":"贺丁大参晋秩掌宪","f":"七言律诗","c":["澄清万里肃冰壶，开府东南亦壮图。","方岳旧臣仍鞅掌，宪台新命更专符。","天连瘴海涛声静，地控罗浮岳色孤。","计日东归怜绣衮，星辰三殿待追趋。"]},{"t":"欧子建邓伯乔戴安仲黎有道诸子枉唁江村别后赋寄","f":"七言律诗","c":["苫块三春伏枕馀，庐前风木耐萧疏。","山河未付支床骨，风雨谁来策素车。","此日匪莪诗转废，十年捧檄事全虚。","怜君易返剡溪棹，夜雪凄其涕满裾。"]},{"t":"送从父于岳谒铨广文","f":"七言律诗","c":["十载文园自草玄，尘冠初拂领青毡。","诸生都讲官非冷，三绝才名世所传。","竹下吾家违笑语，芹宫何处奉櫜鞬。","儒臣早晚多承宠，经术行看奏御前。"]},{"t":"顾别驾以谤解官与诸子饯之归吴","f":"七言律诗","c":["杨柳丝丝江水清，一尊送客怆离情。","粤吟听似阳关调，吴曲翻馀子夜声。","龙性久怜违浪迹，蛾眉一任妒时名。","薜萝正喜还初服，知不重为泽畔行。"]},{"t":"挽唐寅仲先生","f":"七言律诗","c":["处士星高越海隅，姓名长得借江湖。","生无猿鹤移文怨，死有渔樵恨侣孤。","事去千秋心顿折，鸿来两地眼堪枯。","山河未邈人何在，肠断经过旧酒垆。"]},{"t":"夏日张彰之过访村居赋别","f":"七言律诗","c":["懒废幽栖性所偏，故人何意远相怜。","居非戴子山阴道，访是王郎雪夜船。","荔熟千林朝日映，荷香十里晚凉搴。","风光未恶柴桑里，恨少平原十日缘。"]},{"t":"姚仲和以书币来为其亡兄姚约求传赋答","f":"七言律诗","c":["三春村落卧苫茨，尚忆莲池结社时。","我自惨深乌鸟痛，君今谁问鹡鸰悲。","延陵已许生前剑，有道宁辞死后碑。","珍重惠连情好在，转因池草有馀思。"]},{"t":"得黄亮垣先生胪传之报","f":"七言律诗","c":["卿云缭绕散西清，圣主临轩策治平。","一自句胪传内殿，居然声价重连城。","衣冠重王千秋气，词赋群推一代盟。","翻笑白莲同社客，风尘犹自系诸生。"]},{"t":"送区启图游金陵省其尊人官署","f":"七言律诗","c":["梅关春色望中微，送客看花旧帝畿。","腊尽风霜随骑减，春来鸿雁向南稀。","山凭牛首烟霞远，巷过乌衣燕子飞。","览胜况无乡思促，花时应到访庭闱。"]},{"t":"立春日述怀","f":"七言律诗","c":["一啸风尘三十过，浮生踪迹竟如何。","已知幻世同蕉鹿，且拚幽怀洽薜萝。","身贱故应人共弃，门荒兼少雀堪罗。","今朝得荐春盘酒，醉倩阳春发浩歌。"]},{"t":"立春后二日尝新酒贻诸同社","f":"七言律诗","c":["晓看风物媚吾庐，又觉春回两日馀。","迁树莺雏犹怯啭，傍檐桃蕊已纷舒。","惊心岁月劳劳过，屈指交游事事虚。","赖是槽床新酿熟，可能相过共踟躇。"]},{"t":"灯夕寄怀伍国开有开","f":"七言律诗","c":["十里烟花翠欲浮，试灯频逐少年游。","共怜解赠江滨佩，不尽相逢南陌头。","缓夜笙歌方未已，撩人春恨可谁由。","清欢不尽君同醉，梦绕驼山第几楼。"]},{"t":"答谢西粤宪副邓存宇先生","f":"七言律诗","c":["西来书劄慰寒温，感激空馀涕泪痕。","人向夷门身未老，歌翻易水剑犹存。","新贻杂佩江篱结，旧种甘棠雨露繁。","国士肝肠吾欲写，春风桃李自无言。"]},{"t":"寿毛隐君","f":"七言律诗","c":["当年彩笔气如虹，老去逃虚万累空。","异骨鸡群看独鹤，旷怀人外托冥鸿。","瑶池桃结千年实，玉井花开十丈红。","称寿正当清夏日，南薰长挹五弦风。"]},{"t":"送蔡明府升南工部","f":"七言律诗","c":["才子吴兴夙擅奇，还从制锦见清词。","风尘愧我埋名日，月旦怜君校士时。","水部声名兰是省，炎州惠续口为碑。","浮萍聚散宁须问，后会人生总未期。"]},{"t":"九日同诸子游飞驼山","f":"七言律诗","c":["深秋野外足烟萝，佳节招寻共踏歌。","客有清狂同落帽，山看形势拟飞驼。","云连远树千峰合，水落平田独雁过。","容易插萸兄弟会，尊前沈醉且蹉跎。"]},{"t":"村居感怀寄羊城诸旧好","f":"七言律诗","c":["避人聊自掩柴荆，尚忆风尘客舍情。","一别漂零秋已老，寸心愁绝雁初声。","幽居欲著玄经草，旧业空惭白社盟。","独抱龙泉望霄汉，犹馀紫气夜纵横。"]},{"t":"冬夜伍国开有开同天竺上人过宿小楼","f":"七言律诗","c":["窗外梅花映雪枝，小楼清坐二更时。","谈玄稍藉支公偈，玩月无如小谢诗。","幽赏共披尘外语，深盟宁负酒中期。","南州不是陈蕃榻，何物能邀孺子私。"]},{"t":"寄欧子建邓伯乔二子","f":"七言律诗","c":["十年莲社共荷衣，一别风尘万事违。","颉颃尔应齐雁羽，漂零吾自愧雄飞。","梅花带雪攀应满，瑶草含霜拾渐稀。","为念山中栖隐意，好乘春水访渔矶。"]},{"t":"伍国开斋中与诸子分赋怀五岳诗予得恒山","f":"七言律诗","c":["恒岳高凭北极天，泠泠寒色万峰悬。","下临晋代山川尽，远瞩滹沱海势连。","服食千年传异草，有无今日是玄泉。","浪游亦有卢敖杖，婚嫁真怜负胜缘。"]},{"t":"元日独酌","f":"七言律诗","c":["晓日曈曈媚远天，暖云和烟更油然。","陇梅已破残腊放，谷鸟初趁条风迁。","岁月一任隙驹过，姓名何用世人传。","柏尊有酒吾自倒，醉后得趣任高眠。"]},{"t":"送黄太史亮垣先生还期","f":"七言律诗","c":["春潮起色大江平，裘马乘春又远行。","望入彩霞淩玉笋，朝回仙露赐金茎。","衣冠气旧瞻南海，案篆班新侍太清。","敢道弹冠王贡事，沈冥吾已谢时名。"]},{"t":"同俞子旦及其季弟子奭过驼山访戴伍二子山馆","f":"七言律诗","c":["春游不觉路逶迤，野外烟霞面面垂。","花气暖蒸晴日雨，柳条低飏晚风丝。","开尊地僻柴门静，把臂谈深竹影移。","最是弟兄怜臭味，况逢侠少得新知。"]},{"t":"闰三月同俞子奭诸子游驼山晚归","f":"七言律诗","c":["自是东皇爱暮春，不教九十尽芳晨。","看花偶逐同心侣，问竹因逢把臂人。","黄鸟隔林啼尚涩，青山濯雨黛逾新。","春风莫讶归途晚，赢得诗情共醉论。"]},{"t":"游观音岩","f":"七言律诗","c":["石床千尺倚云根，小有清虚敞洞门。","风雨不惊龙卧稳，烟霞长护佛坛尊。","云封鸟道才穿径，日落人家别有村。","何事杖藜天外去，尽饶方内足攀援。"]},{"t":"送郑我淳署教潮州","f":"七言律诗","c":["君才三绝早知名，不忝风流旧郑生。","列宿向高东鲁望，一珠还傍日南明。","横经未厌毡为席，览德惟应凤作城。","莫恋成溪春色好，彩毫方待赋西京。"]},{"t":"驼山冷翠亭为伍国开赋 其一","f":"七言律诗","c":["虚亭遥上翠微边，水石周遭地自偏。","倚剑群峰来雪色，落霞环翠到窗前。","薜萝豫长他年服，松竹初开小有天。","便可容吾高枕得，与君聊结避人缘。"]},{"t":"驼山冷翠亭为伍国开赋 其二","f":"七言律诗","c":["落霞山下结茆庐，疏散真宜避世居。","槛外疏篁新护植，阶前荒蔓颇芟除。","问奇过客频携酒，闭户閒人但著书。","赋就淮南丛桂句，小山招隐意何如。"]},{"t":"驼山冷翠亭为伍国开赋 其三","f":"七言律诗","c":["萧森别似武陵源，竹叶桃花古洞门。","避俗未论秦氏隐，逃虚聊隔世人喧。","白云过户时留润，碧沼浇畦渐耗痕。","一事无营心即水，翛然宁复碍乾坤。"]},{"t":"驼山冷翠亭为伍国开赋 其四","f":"七言律诗","c":["倚剑峰头乱石蹲，烟霞半入野人村。","荒榛久待吾曹辟，丘壑应怜尔道尊。","鸟篆閒扪萝径识，松涛时向石床翻。","只今且说高阳会，白雪留他异代论。"]},{"t":"驼山冷翠亭为伍国开赋 其五","f":"七言律诗","c":["江村何必异蓬莱，竹里疏棂面面开。","雨后花光疑幻出，峰前山势欲飞来。","眠高自稳青萝石，眺远频呼浊酒杯。","草就太玄嘲懒解，汉庭谁识子云才。"]},{"t":"仲秋十二夜戴公纶何龙友过宿小楼","f":"七言律诗","c":["楼前一雨过虚堂，忽有凉飔洒客裳。","抱病经时人事减，因君此夕野情长。","渐怜蟾影分秋色，愁听砧声捣夜霜。","坐久天河浑欲曙，惊呼早雁不成行。"]},{"t":"中秋诸子过集迟何戴伍三子不至","f":"七言律诗","c":["蒹葭秋色夜萧然，白苧歌残思未捐。","华烛半含兰焰吐，浊醪暗倩桂香传。","群星未尽人间会，片月空怜海上圆。","露下天阶浑似水，分明清梦绕婵娟。"]},{"t":"答公纶襄武二子石门舟中见怀","f":"七言律诗","c":["风生江上雁行斜，高枕怀人思未涯。","兴儗山阴飞夜雪，梦悬东阁赋梅花。","风尘不定孤蓬迹，岁月还伤两鬓华。","酒态诗情俱好在，莫教轻负故罗葩。"]},{"t":"饮何隐君西畴别业","f":"七言律诗","c":["青梧翠竹绕回塘，别有风光在草堂。","百亩无如沮溺稳，诸贤谁是阮稽狂。","篱边菊蕊迟秋色，槛外山光到夕阳。","遮莫尊前誇一石，如坭拚付酒人傍。"]},{"t":"高柳新蝉","f":"七言律诗","c":["柳变园林拂暖丝，新蝉初咽最高枝。","寻条未定吟风处，翳叶宁妨饮露时。","摇扬乍飘宫里鬓，凄清如恋画前眉。","豫怜朔吹惊寒后，撩乱章台竞噪迟。"]},{"t":"邓伯乔万伯文欧子建李烟客诸子游罗浮怅余不及从也诗以讯之","f":"七言律诗","c":["矫首朱明洞里仙，十年清梦隔钧天。","观留葛稚烧丹灶，池自麻姑长白莲。","桑海山家仍岁月，壑舟人代几风烟。","输君此日探奇赏，婚嫁宁终负此缘。"]},{"t":"赋得清怨","f":"七言律诗","c":["脉脉幽情欲诉谁，旧怀新恨总难追。","花前有约寒盟后，梦里成欢乍醒时。","夜雨孤窗风自掩，春残虚幌月深垂。","芳心未分同流水，多恐韶华易旧期。"]},{"t":"为何起时赠陶伯友新冠","f":"七言律诗","c":["久从传粉忆清欢，年少风流世共看。","闻道有车仍掷果，遥知新沐正弹冠。","春花迎露香逾媚，丝柳笼烟弱更寒。","莫漫离尘高自倚，暮江还欲采幽兰。"]},{"t":"送何公子之西粤阳朔觐省","f":"七言律诗","c":["苍梧西望白云寒，此去庭闱彩袖宽。","三百滩声喧过掉，万重山色入征鞍。","涉江定解湘妃佩，访古应寻葛令丹。","记取离鸾弦上曲，趋庭閒听署中弹。"]},{"t":"寄讯从父于岳感恩司训","f":"七言律诗","c":["登楼春色望漫漫，紫气朱崖万里宽。","家远最怜三载别，官閒仍拥一毡寒。","黎蛮岛外章缝地，桃李丛中苜蓿盘。","风韵竹林俱正好，一枝吾愧谢家兰。"]},{"t":"人日过伍国开有开与家珍家宝诸从同集","f":"七言律诗","c":["竹下招携意转亲，开尊况复是芳辰。","百年未老烟霞骨，七日能同海国春。","共逐香尘群少侠，谁迟芳草待佳人。","灯前解惜金花胜，便可同君醉浃旬。"]},{"t":"过伍家珍结云楼因赠","f":"七言律诗","c":["小结山楼半岭欹，千盘磴道绕逶迤。","十年混俗劳生过，一日皈心习静时。","伏枕每高朝日影，焚香时惬白云期。","幽居礼数从君简，莫讶元龙湖海姿。"]},{"t":"陈子明托病谢客秋日同诸子过访","f":"七言律诗","c":["清溪曲曲绕茅庐，客自栖真苦著书。","乍可我乘剡曲舫，更堪谁过草玄居。","凉秋未拟观涛赋，生计惟挥种秫锄。","晚月在松天在水，林塘相对领清虚。"]},{"t":"赠淯水刘公 其一","f":"七言律诗","c":["吴楚才名自国工，长杨一赋气何雄。","从知骏骨高燕市，未信蛾眉妒汉宫。","多暇鸣琴调独鹤，有时把剑望双虹。","青云莫道轻相附，不尽论文意气中。"]},{"t":"赠淯水刘公 其二","f":"七言律诗","c":["才子南迁名转高，乍逢意气感绨袍。","宦情淡泊宁鸡肋，宪府萧閒亦马曹。","节驻春城看过雨，梦回兰署待挥毫。","香清茶熟官衙暮，尚有词人载浊醪。"]},{"t":"陈子明同伍有开兄弟过宿眺霞楼重赋言别","f":"七言律诗","c":["踟蹰临发驻行舟，握手还堪信宿留。","未论平原欢十日，居然下榻见千秋。","雄心共按青萍赠，末路人疑白璧投。","击缺唾壶君莫笑，丈夫宁作别离愁。"]},{"t":"岁暮送俞子旦还里因订五羊之约","f":"七言律诗","c":["江村暮色正萧然，月在澄江水在天。","投分两年莲社约，销魂今日木兰船。","梅花腊近含情待，菊蕊寒深著意妍。","期尔穗城春色好，相逢应在百花前。"]},{"t":"夏日黎君献黄逢永邓升仲见过池亭留宿夜谈","f":"七言律诗","c":["闭门长夏听黄鹂，竹下相留晚更宜。","玄赏十年怜臭味，高谈一夕见襟期。","青萍竟为何人合，白雪还应和客知。","兴剧与君拚酩酊，不妨人唤习家池。"]},{"t":"赠黄逢永","f":"七言律诗","c":["赋才江夏自家声，第五还高骠骑名。","一出词坛倾左席，居然斯道破坚城。","神交已见双龙合，星聚应占百里明。","屈指生平俱汗漫，尊前那惜更纵横。"]},{"t":"舟过望匡庐作","f":"七言律诗","c":["仙都万仞接蓬莱，秀结芙蓉面面开。","五老云霞空外举，九江风雨望中回。","洞传白鹿今谁主，社辟东林几客来。","自笑生平耽胜赏，翻从眼底负登台。"]},{"t":"寄欧子建邓伯乔二子","f":"七言律诗","c":["十年曾共理烟萝，白社青灯夜夜过。","花满游堤春屐冷，酒残歌席暮钟多。","谁将小草论生事，终自冥鸿谢网罗。","目极白云天万里，瑶华何日寄沧波。"]},{"t":"送何老师册封河南二首 其一","f":"七言律诗","c":["几载词林供奉中，皇华新跃五花骢。","小山旧赋丛生桂，一叶新秋剪旧桐。","路指岳灵瞻绛节，筵开淇水浥清风。","梁园岂少邹枚在，授简何如上客工。"]},{"t":"送何老师册封河南二首 其二","f":"七言律诗","c":["玉检金坭五色霞，词臣六月赋皇华。","阁中乍别仙人杖，天上先占使者槎。","紫气定知逢令尹，玄经曾否授侯芭。","嵩高瑶草行边拾，能念公门桃李花。"]},{"t":"送梁永连假归","f":"七言律诗","c":["与君同藉献长杨，燕市才名起雁行。","半载旅怀兄弟遣，三秋归梦别离长。","西山爽气虚游屐，穗石秋风待举觞。","莫漫乡园耽胜赏，故人京洛正相望。"]},{"t":"赠杜日章总戎","f":"七言律诗","c":["千秋曾识杜当阳，望重征南奕叶光。","何似承家新虎略，居然束发早膺扬。","谈兵甲第开三辅，说剑星文动七襄。","幕府词人多载笔，功成铙吹有新章。"]},{"t":"答黎有道","f":"七言律诗","c":["岭外论文自昔时，十年踪迹各天涯。","青山旧业应怜我，白雪新篇好和谁。","岁月易销燕市梦，烟霞犹负秣陵期。","道傍肯信无知己，明月投来光陆离。"]},{"t":"甲寅元旦早朝诗二首 其一","f":"七言律诗","c":["禁苑春光引直庐，日华高捧紫宸居。","风回辇道烟光绕，天应钩陈法象舒。","鹓佩万年瞻斗极，龙颜何日御簪裾。","小臣接迹夔龙后，愿拟冈陵颂九如。"]},{"t":"甲寅元旦早朝诗二首 其二","f":"七言律诗","c":["柳外珂鸣紫陌尘，班齐玉笋拜枫宸。","芙蓉露擢金茎晓，阊阖天开玉烛新。","朔雪渐消梅萼暖，条风初入柏尊春。","萧韶九奏传仙乐，曲度云中听未真。"]},{"t":"寿姜翼龙年伯六十","f":"七言律诗","c":["春曹当日几批鳞，主圣能宽折槛臣。","湖海久便鸥鸟狎，云霄今起凤雏新。","书传宛委窥灵笈，籍在华阳纪列真。","不但宫衣誇戏彩，新恩求旧下蒲轮。"]},{"t":"送庄允元太史以赦诏奉使还闽过枣强受室郑明府","f":"七言律诗","c":["马首垂杨拂落晖，都门握别思依依。","金鸡诏捧皇恩渥，玉署人归彩服辉。","禁苑暂违鹓鹭侣，临卬重见凤凰飞。","词臣交戟遥相待，莫恋清泉茗荚肥。"]},{"t":"送麦玄中司教潮阳","f":"七言律诗","c":["才名三绝冠词场，桃李新栽海国芳。","虎豹藏时仍雾窟，凤凰栖处一鳣堂。","西山别酒寒蝉露，南国归人早雁霜。","莫道官贫高马骨，千金台上待飞黄。"]},{"t":"送欧刺史谪西粤别驾","f":"七言律诗","c":["旧识搴帷刺史贤，虔刀仍向粤江边。","潘安拙宦头从白，欧冶新硎气尚悬。","客路星槎浮桂水，署廉山色隔青莲。","到来杂佩如堪赠，沅芷湘兰任意搴。"]},{"t":"同樊孟泰工部吴尔达进士集韩寅仲明府寓分得朝字","f":"七言律诗","c":["西山爽气到崇朝，佳会论心不待招。","客路相逢几乡国，故人生计复渔樵。","秋风华发搔逾短，夜色青萍醉欲骄。","更续兰膏谈往事，浮沈吾亦任蓬飘。"]},{"t":"陈督学转秩潮阳太参捧粤檄入贺赋赠 其一","f":"七言律诗","c":["文星岭外贯三台，为是呼嵩万里来。","合浦采时珠在掌，燕山到日骏登台。","陈诗别奏江南俗，献寿同沾湛露杯。","咫尺新恩隆九列，无烦津吏候江隈。"]},{"t":"陈督学转秩潮阳太参捧粤檄入贺赋赠 其二","f":"七言律诗","c":["王气从瞻牛女墟，三年造士意何如。","閒中几见收龙种，海上新传走鳄鱼。","万国清秋来玉佩，九霄凉月集仙裾。","知君献纳多金鉴，肯向淩云羡子虚。"]},{"t":"赠李皞如比部谪理彰德","f":"七言律诗","c":["五羊相接古端州，近有高人宦辙留。","郁石已无归箧载，隋珠犹讶路人投。","调追正始回风雅，迹任时趋唤马牛。","此去西园飞盖地，风流千古旧应刘。"]},{"t":"送吴进士出宰归安","f":"七言律诗","c":["明光献赋羡青春，一出云霄便致身。","治行词名君并擅，离怀羁思我难论。","风清天目琴鸣远，花发苕溪制锦新。","卧阁正堪娱彩笔，可忘鱼素问缁尘。"]},{"t":"送黄民部逢一南归兼寄怀其弟逢永","f":"七言律诗","c":["惜别柳门共举鹅，客怀去住总茫茫。","经年浪迹嗟萍梗，万里归人羡雁行。","江上黄花晴带雪，故园梅萼暖含霜。","燕山未隔怀人梦，驿使春来倘寄将。"]},{"t":"中秋夜同林水部韩太史待月曾比部宅","f":"七言律诗","c":["三五蟾光隐玉楼，朋尊犹自惬清游。","人从久客偏怜节，月似新寒不耐秋。","重露暗飘青桂落，微云时傍远空收。","坐深彷佛冰壶里，肯惜酬歌永夜留。"]},{"t":"立春前一日韩太史绪仲何进士卜熙黎山人不回过寓赏梅","f":"七言律诗","c":["东风吹暖腊梅知，索笑巡檐得几枝。","春色共怜京国早，芳华犹比故园迟。","含情易入仙郎梦，赠远长违驿使期。","浊酒清灯聊此夜，催残寒雪又花时。"]},{"t":"送何进士卜熙领教镇江","f":"七言律诗","c":["淩云奏罢气翩翩，还向江南领一毡。","岂为清吟妨簿领，自便高座少攀缘。","南朝景物春风外，北固云山晚照前。","马首倘过官阁地，君家词赋有新篇。"]},{"t":"送顾宗伯馆师得请归省四首 其一","f":"七言律诗","c":["春卿法座映三台，诏许宁亲拥传回。","子舍白云吴苑近，关门紫气日边来。","江鱼暖入桃花水，寿酒春分茎露杯。","为问老莱当日彩，可能天上赐亲裁。"]},{"t":"送顾宗伯馆师得请归省四首 其二","f":"七言律诗","c":["秩宗初贰主恩偏，十载龙楼侍讲筵。","手诏暂容归省日，绛帷同恋授经年。","晓钟汉殿违仙仗，昼锦吴江返画船。","任是庭闱多乐事，肯令黄阁负徵贤。"]},{"t":"送顾宗伯馆师得请归省四首 其三","f":"七言律诗","c":["倾都冠盖送仙舟，望望吴江匹练浮。","绿野未教猿鹤喜，青霄旋待凤凰游。","门前桃李阴初合，笼里参苓晚见收。","魏阙江湖心更远，能无清梦绕宸旒。"]},{"t":"送顾宗伯馆师得请归省四首 其四","f":"七言律诗","c":["玉署清深隔俗尘，几回授简得相亲。","千秋忝窃登龙客，短步空惭附骥人。","秘阁藜光怜乍冷，北堂萱树羡长春。","悬知爱日欢无限，曳履还看捧日新。"]},{"t":"除夕感怀和韩绪仲先生韵","f":"七言律诗","c":["守岁孤吟坐寂寥，条风解冻未全消。","八千道路归何日，四十年光逼此宵。","休论作客踪难定，且喜看花兴不遥。","柏叶倾残灯未烬，又随鹓鹭谒清朝。"]},{"t":"送陈翔甫奉使便道归省","f":"七言律诗","c":["飞刍二月出王畿，喜借皇华觐省归。","画省香含兰是草，白云心切彩为衣。","花明驿路听莺过，风便征帆背雁飞。","金马滞留归未得，梦魂随尔到渔矶。"]},{"t":"梦卜求贤","f":"七言律诗","c":["五色卿云灿陆离，黄麻宣诏出彤墀。","天教岩筑调商鼎，人识熊车载帝师。","玉烛乾坤皇祚永，金瓯名姓裔夷知。","千秋鱼水非难事，丙魏同心又一时。"]},{"t":"赋得山意冲寒欲放梅","f":"七言律诗","c":["久向严寒忆旧芳，空林摇落几经霜。","枝疑斗雪将春早，山为迎阳著意忙。","结实未论调国鼎，含情先遣报东皇。","上林次第阳春色，白雪谁应儗和章。"]},{"t":"赋得秋声一雁飞","f":"七言律诗","c":["绿水晴沙两岸明，碧空如洗暮云轻。","长天远写衡阳影，静夜孤传芦渚声。","月冷湘灵和鼓瑟，风清缑岭叶吹笙。","不堪久客还闻汝，欲赋悲秋拟宋生。"]},{"t":"青门祖帐","f":"七言律诗","c":["丝纶十载代龙楼，万国安危掌上筹。","剑履暂违仙仗月，菊松初问故山秋。","歌来羽翮飞鸿鹤，恋向沧波狎白鸥。","回首同心还魏丙，肯从圣世傲巢由。"]},{"t":"阅辽左边图","f":"七言律诗","c":["边城万里开雄镇，百二关河拱帝京。","牧马未容胡虏入，椎牛谁奋健儿情。","天清瘴塞烽烟急，日落西山野戍横。","正是圣明思颇牧，几人年少请长缨。"]},{"t":"过白沟河","f":"七言律诗","c":["一路风光媚眼新，红亭绮陌送征轮。","暂从紫禁宽休沐，渐识青山是故人。","云暗白沟迷古渡，风寒易水隔遥津。","觉来似醒邯郸梦，欲谢长安一片尘。"]},{"t":"过楚项故都","f":"七言律诗","c":["驿馆萧萧万壑中，停车千载问雄风。","草深古戍行人少，木落荒台巢鸟空。","烟雨尚怜迷楚渡，火云犹自恨秦宫。","酒酣一笑俱陈迹，矫首鸿沟有断鸿。"]},{"t":"冯茂山谒五祖 其一","f":"七言律诗","c":["西来五叶法初南，遗蜕千秋尚在龛。","心到空时真不二，教从归处更无三。","山前香雾长疑雨，林里幽花并是昙。","京洛悠悠成底事，何如此地一皈参。"]},{"t":"冯茂山谒五祖 其二","f":"七言律诗","c":["扪萝散步拾阶登，路转山庭始见僧。","龙去尚留听偈石，台荒空长护经藤。","雨声半入山泉泻，雾气潜消海日升。","行役冲炎真火宅，登临聊此濯清冰。"]},{"t":"过吉水同袁文学及族叔于垣饮温尔弼明府私署","f":"七言律诗","c":["官署萧森吏亦仙，坐来真惬薜萝缘。","筵开深径消炎署，山隔春城送晚烟。","乡味渐偿莼鲙思，客怀欢藉竹林贤。","更闻中夜袁郎曲，何异吴江月下船。"]},{"t":"送何似公伍国开就省试","f":"七言律诗","c":["荒径初归秋气清，送君羽翮又南征。","马蹄十里槐风趁，兰楫三江桂月明。","赋就黄金生顾盼，梦中彩笔竞纵横。","北山莫漫惊猿鹤，上国春林待早莺。"]},{"t":"初冬与仁伯代骧弟寓濠上馆有梅一株初露微蕊独一花先放娟好特甚因忆故乡梅园寄怀伍国开兄弟","f":"七言律诗","c":["嫩蕊枝枝总待时，一花何意报春姿。","风摇隔叶浑难见，月映当帘巧自窥。","欢赏转怜时序改，行吟犹喜弟兄私。","故园万树今开否，应有驼山旧主知。"]},{"t":"哭黎君献","f":"七言律诗","c":["艺苑风流几代兴，君才济美自家承。","祇怜异地分雄剑，不谓垂天失大鹏。","侠少有人传草练，酒场无客问如渑。","诃林寂寞莲花社，邻笛听残涕满膺。"]},{"t":"同马伯起及仁伯代骧两弟过梁明叔禅悦斋","f":"七言律诗","c":["森森萝径引纡回，三载寻盟许复来。","篮举每从花外转，笔床多在竹间开。","当尊客爱逃禅醉，挈弟人惭梦草才。","对此风光那可负，分题休畏暮钟催。"]},{"t":"哭黄逢一","f":"七言律诗","c":["薄游曾共帝京尘，前后三年各乞身。","一见岂知成永诀，相期疑是有前因。","鹤飞尚儗归华表，龙跃何年返剑津。","云路赏音流水绝，孤琴虽在不堪论。"]},{"t":"乙卯冬何龙友北上卒卒未及一言为别嗣得其度岭书赋此寄之","f":"七言律诗","c":["浪迹归来恋古欢，故人天路促征鞍。","驼山客去梅初浅，庾岭书回雪未残。","价重千金高自许，名收片玉倚谁看。","清时事业凭君在，饶得东山老谢安。"]},{"t":"寻梅罢归酌伍国开白燕池亭得芬字","f":"七言律诗","c":["薄暮怜欢手重分，山含落照尽成文。","园寻白燕当年地，沼问笼鹅旧日群。","淡月疏钟人共倚，冷风静夜酒微醺。","深谈真惬如兰赏，不辨山梅入座芬。"]},{"t":"欧子建见访","f":"七言律诗","c":["衡门斜枕碧溪流，有客重停访戴舟。","别后尺书南北泪，尊前双鬓古今愁。","当杯黄鸟如相约，移席浓阴也解留。","脱粟故人知不薄，交情如水十年投。"]},{"t":"潘澹明侍御见过江村于伍国开宅夜饮次早迹之已解缆去矣赋寄","f":"七言律诗","c":["久从门下识潘安，得及云霄接羽翰。","夜静星辰回笑语，晓来风雨失追欢。","三春花事幽居过，四海波涛宦计难。","无恙江村双桨在，可能重与采芳兰。"]},{"t":"寄送何卜熙同年由镇江教授之任国子","f":"七言律诗","c":["三载同看上苑花，羡君宦况带烟霞。","东方已待金门诏，董相还披绛帐纱。","六馆秋清悬授简，中泠雨歇忆煎茶。","相闻敢忘弹冠意，暂借衡门傲岁华。"]},{"t":"寄黄进士","f":"七言律诗","c":["捷书飞报粤江干，彩笔纵横剑气寒。","燕馆旧惭虚市骨，南溟今见起飞翰。","上林肯后春花赏，藜阁应分夜火看。","共是郑庄门下士，临风能不念弹冠。"]},{"t":"和何似公登小金山妙高台见怀","f":"七言律诗","c":["问法闻登江上台，长江自度岂浮杯。","月临初地看无色，水落潮音听转猜。","念我肯停浮白兴，怜君犹为踏青来。","便期出世宁容晚，共觅莲花大地开。"]},{"t":"闻毛康侯何洁卿何龙友下第寄怀","f":"七言律诗","c":["淩云虚道动君王，病渴相如复在粱。","眉黛未能容淡扫，市门纷自倚红妆。","正怜归雁音书渺，犹忆思鲈客计忙。","一任道傍多按剑，握中无恙是珠光。"]},{"t":"丙辰初秋六夕何似公伍国开有开同诸弟过集小楼","f":"七言律诗","c":["静夜凉秋欲雨时，共怀幽兴借佳期。","未从机石窥灵匹，且喜风林待妙词。","几处针楼人并倚，阿谁银汉独相思。","狂来搔首青天外，曙色星河到槛垂。"]},{"t":"七夕与国开诸子夜坐分赋","f":"七言律诗","c":["凉风七夕觉秋多，牛女佳期竟若何。","灵媛共传先夕会，星桥曾待此宵过。","白云天外谁骑鹤，清月楼头客放歌。","不用更窥银汉影，溪流当户接明河。"]},{"t":"寄李秘书","f":"七言律诗","c":["都门两载各酸辛，无恙升沈信此身。","旅况共怜官似水，交情真见德为邻。","欣闻凤诏恩波渥，俄道皇华使节新。","一水盈盈非远道，怀人空自采江蘋。"]},{"t":"王总戎镇粤与予未晤比解官归以书见存赋此送之","f":"七言律诗","c":["十年坐镇识轻裘，百粤安危在运筹。","横海阵成鱼鸟夜，故园书到菊松秋。","画麟阁自千秋见，赤舄言从四国流。","独恨论文尊酒负，暮云天外思悠悠。"]},{"t":"送黄与东司理南宁","f":"七言律诗","c":["莲社三年隔古欢，一星遥望法为官。","土风粤徼犹乡语，山色苍梧似画看。","雷雨作时天欲解，阳春歌罢雪仍寒。","汉庭治郡君家事，相府功名晚未难。"]},{"t":"因同年王简之任福清寄呈叶老师 其一","f":"七言律诗","c":["王言早晚代如丝，十载艰危独相时。","遇巷不因中掖阻，回天宁遣外臣知。","黄扉业就夔龙远，绿野人归猿鹤私。","闻道圣明方侧席，未应长与赤松期。"]},{"t":"因同年王简之任福清寄呈叶老师 其二","f":"七言律诗","c":["冥鸿天外杳难攀，天上犹悬曳履班。","共识晋公闻外国，几时安石起东山。","形图画阁麒麟里，家在仙人烟雾间。","云汉望来知有路，乘槎应儗客星还。"]},{"t":"因同年王简之任福清寄呈叶老师 其三","f":"七言律诗","c":["倾都祖道忆当时，怅望贤哉帝者师。","任是凤翔应览德，肯教鸿渐遂为仪。","天清阊阖云霞远，花发平章岁月移。","蒿目时艰忧不细，知公后乐意迟迟。"]},{"t":"因同年王简之任福清寄呈叶老师 其四","f":"七言律诗","c":["竹松三径自萧森，丞相堂开绿野阴。","赐得鉴湖初有宅，散来酒会已无金。","閒看倦鸟还林翼，更想归云出岫心。","天下安危身系久，老臣那便入山深。"]},{"t":"寄萧玄圃少宰学士 其一","f":"七言律诗","c":["后乐江湖岁月新，宣麻早晚出枫宸。","千秋业自看钟鼎，一代人今仰凤麟。","归去欲寻彭泽隐，悟来聊现宰官身。","东山正系苍生望，未许漓江老钓纶。"]},{"t":"寄萧玄圃少宰学士 其二","f":"七言律诗","c":["十载论思侍禁垣，更参钧统望逾尊。","贤劳暂许休元宰，徵诏行看起特恩。","名自云霄惭骥尾，人从桑梓望龙门。","卢傲那得天师遇，稽首临风乞妙言。"]},{"t":"早春漫兴","f":"七言律诗","c":["卜筑原邻野老家，春来几席驻流霞。","栽馀旧竹还抽箨，种得新桃欲试花。","曲径风柔翻戏蝶，隔林烟密隐啼鸦。","风光岁岁还供赏，懒向青铜检鬓华。"]},{"t":"正月十一夜同诸弟子泛过伍子观灯","f":"七言律诗","c":["柳汀桃坞澹澹烟，美人相期西江前。","乡园行乐寻常事，童稚交游二十年。","宛在水中画船稳，闻说陌上春风颠。","长宵一刻俱须醉，莫遣千金价浪传。"]},{"t":"元夕过国开兄弟宅同诸少观灯","f":"七言律诗","c":["碧汉澄澄片月孤，春宵不道秋光殊。","江滨有佩贻交甫，风俗何人祀紫姑。","谱就王家传胜事，光摇交浦出明珠。","兴来那可因人败，卜夜同君倒玉壶。"]},{"t":"寄讯同年杨士载太史 其一","f":"七言律诗","c":["忆同文酒醉词林，意气兼谐物外心。","一向都门分柳色，几从天木望鸾音。","人间素业供贫病，海上丹砂自古今。","寂寞京华尘梦断，十年湖海任浮沈。"]},{"t":"寄讯同年杨士载太史 其二","f":"七言律诗","c":["力疾怜予漫乞归，羡君昼锦有光辉。","扳舆潘岳初游御，鸡骨王戎病已违。","云静罗浮丹灶冷，春深泉洞茗芽肥。","青山旧迹原相望，何日剡溪掉雪飞。"]},{"t":"欧子建新自贼中回过其竹素山房因赠","f":"七言律诗","c":["相闻踪迹几间关，剩有蓬蒿一榻閒。","家为频移疑逆旅，书缘著就即名山。","半林雨过春花落，隔寺钟残暮鸟还。","辛苦未忧惊老瘦，祇怜多病鬓毛斑。"]},{"t":"得伦五知吏部书寄答","f":"七言律诗","c":["缄书久不到长安，何意云霄下尺翰。","桃李春风归启惠，东南王气盛衣冠。","栖迟愧我文园卧，清简怜君水镜寒。","知是臣心浑似水，尽教门撤棘篱看。"]},{"t":"寄同年赵任甫太史","f":"七言律诗","c":["忆别金门岁几徂，闻君新兴亦莼鲈。","罗浮匡岳心同远，酒德琴歌事岂孤。","沈陆祇供长伏枕，飞杨争羡老操觚。","谁怜咫尺丰城剑，犹自雌雄未可呼。"]},{"t":"贺周东莞考绩","f":"七言律诗","c":["三年领邑傍清都，葛令丹砂事有无。","已见政成真下凤，即防仙去便飞凫。","阳回万户冬为日，月映疏帘冰在壶。","欲儗闻歌过偃室，久拚公事谢潜夫。"]},{"t":"送田成叔侍御还朝便道过里 其一","f":"七言律诗","c":["春风先到庾关梅，奏报登车气色开。","一疏九天回雨露，三年五岭净氛埃。","爱同冬日留棠芾，法肃秋霜满柏台。","过里彩衣欢舞处，雁行新起陆机才。"]},{"t":"送田成叔侍御还朝便道过里 其二","f":"七言律诗","c":["骢乘六传入长安，卧辙倾都恋豸冠。","百粤疮痍膏雨沐，中朝风采法皇寒。","城边仙去空留石，江上人归暂采兰。","闻道柏台班落落，朝阳谁不快飞翰。"]},{"t":"赠李烟客","f":"七言律诗","c":["文章作祟已多时，怜尔耽诗近更痴。","艺苑杜门耕自饱，谈锋遇敌战忘疲。","生涯醉醒千杯酒，世事输嬴一局棋。","已向山阴见安道，未教兴尽负相思。"]},{"t":"寄送周大中丞 其一","f":"七言律诗","c":["韶山伐鼓得阗阗，郢客骊歌白雪传。","九命恩光隆赐履，两都输挽重筹边。","朱颜春映宫莺色，华发神淩海鹤烟。","莫更扳留稽画轼，正欢霖雨起中天。"]},{"t":"寄送周大中丞 其二","f":"七言律诗","c":["望里金陵烟树微，长江中划万流依。","帆随淮月春前度，人识台星斗畔辉。","民力久怜皮髓竭，当途未厌茧丝非。","运筹莫道偏劳瘁，汉室论功转饷稀。"]},{"t":"寄讯同年庄允元翰编","f":"七言律诗","c":["马鬣封归泪未乾，闻君椿树亦摧残。","山中岁月虚鸿宝，物外心情付钓竿。","藜杖云深披紫帽，井泉秋好试旃檀。","新诗想瘦支床骨，好寄罗浮洞里看。"]},{"t":"答欧经季丈人见寄","f":"七言律诗","c":["岁晏风尘短日过，乍传双鲤到沧波。","名高硕果风流在，交忆妃兰岁月多。","海上渔竿閒独往，枕中鸿宝秘如何。","从君愿乞还丹术，懒赋金门避世歌。"]},{"t":"寿伍隐君","f":"七言律诗","c":["六叶萱开岁事新，露华初濯八千椿。","里门共聚星为德，灵气先占日是人。","金胜丽分莱袖舞，綵花艳借谢庭春。","称觞尚颂椒盘酒，曲奏琅璈醉几巡。"]},{"t":"答韩绪仲先生罗浮书问","f":"七言律诗","c":["相思三载托瑶华，复喜春鸿到海涯。","人忆玉皇香案吏，书传蓬岛列仙家。","二毛欲儗安仁赋，九转谁逢葛令砂。","闻道罗浮近得长，不禁清梦逐飞霞。"]},{"t":"寿黎别驾七十为其馆甥何似公作","f":"七言律诗","c":["南徐宦迹佩刀游，解绶归来未白头。","道骨炼成将驭鹤，机心忘尽许盟鸥。","庭馀松菊开三径，宅近烟霞老一邱。","欲挹清标无处所，空从尘外想风流。"]},{"t":"送林元培水部还朝","f":"七言律诗","c":["酒垆曾共醉春明，次第归骖五石城。","丘壑我仍淹痼疾，皇华君已迫严程。","星垂大漠双龙拂，冰泮黄河画鹢轻。","最是诗情称水部，彩毫还待赋西京。"]},{"t":"过何似公园亭","f":"七言律诗","c":["为园墙东清心客，春事犹及与客吟。","新径移花植千本，隔墙借树高十寻。","月池共爱好夜色，风林如欲逗春阴。","落落对尔多古意，流连沈醉忘更深。"]},{"t":"送曾元鲁恤刑两浙还朝","f":"七言律诗","c":["含香几载白云司，钦恤还乘四牡騑。","天地解时雷作雨，君王爱日网开围。","书探禹穴千秋秘，奏入虞廷五色辉。","云路故人看藉甚，未妨樗散久渔矶。"]},{"t":"送臧方伯升宁夏巡抚 其一","f":"七言律诗","c":["几年方岳领诸侯，简命新承帝宠优。","三辅云山瞻喜色，九边烽火待持筹。","岩廊肯恤千思咏，锁钥还劳嵩目忧。","独有腐儒丘壑癖，赠君空自揽吴钩。"]},{"t":"送臧方伯升宁夏巡抚 其二","f":"七言律诗","c":["归来习懒谢逢迎，一送君侯画轼行。","掌上莲花开泰华，匣中龙剑出丰城。","笳声夜散榆林燧，柏府秋高细柳营。","拊髀久知劳圣主，即看韩范播威名。"]},{"t":"王明府生日","f":"七言律诗","c":["郎星初耀粤江涯，令尹关前紫气赊。","赋就春深岐海锦，望来标建赤城霞。","白云近荐安期枣，丹灶长邻葛令砂。","未遣双凫天上去，暂从冰署醉莲花。"]},{"t":"建霞楼前盘中白莲花带绿色采贻国开伍子异之曰佛家有青莲仙家有碧莲何来此绿莲花也次日伍子过又抽一花则又白如雪或红如朱叠瓣相间有一瓣而中分红白者花神之变幻极矣各赋一诗","f":"七言律诗","c":["青莲西士碧莲仙，几向人间见此莲。","杂佩半含苍玉色，裁霞中界雪花妍。","并头漫纪元嘉代，千叶虚传太华巅。","欲制衣裳贻楚客，恐令颜色妒芳荃。"]},{"t":"夏日园居偶成效长庆体 其一","f":"七言律诗","c":["此身消受觉无多，何用劳劳逐世波。","日饭两升嫌过饱，晚斟三盏适微酡。","行随竹下宁须杖，听到枝头亦当歌。","独有顽儿不解事，随人犹赴孝廉科。"]},{"t":"夏日园居偶成效长庆体 其二","f":"七言律诗","c":["北窗复得傲羲皇，入夏园林日渐长。","寥寂每因得句破，多閒犹觉种花忙。","时开异卉誇为圃，便向同声索和章。","莫问升沈身外事，邯郸吾已熟黄梁。"]},{"t":"中秋先一夕浮邱社集同黎君选传贞父陶摇光何龙友彭伯时戴安仲从弟代骧赋","f":"七言律诗","c":["白社分携忆岁时，招邀此地即蓬池。","山家几变仙灵在，秋色将分鸟鹊知。","大药不传丹灶火，远心应共白云期。","清光容易留杯底，肯惜更阑席更移。"]},{"t":"送冼觐之任武昌","f":"七言律诗","c":["五羊西望古荆州，此去褰帷亦壮游。","几载理曹瞻执法，一麾江汉想登楼。","主恩卧治原非薄，时事论兵待借筹。","身系安危公等在，可容樗散老丹邱。"]},{"t":"送张君弼大参捧贺","f":"七言律诗","c":["六月天南暑雨收，嵩呼万里觐宸旒。","玉盘可更承仙露，绛帻将无报晓筹。","北极衣裳垂五位，曲江金鉴上千秋。","悬知九列还虚左，朝罢新恩出凤楼。"]},{"t":"寄讯欧子建邓伯乔伍国开三子下第","f":"七言律诗","c":["相将鹏翮起天池，怪底图南有后期。","吾道未堪歌凤日，秋风不那忆鲈时。","怀中白璧投曾否，梦里黄梁熟转疑。","早晚江村丛桂发，可能同擘小山枝。"]},{"t":"戊午九日同诸弟及奇儿泛舟","f":"七言律诗","c":["寻常竞逐登高伴，懒厌逢人此避喧。","短发不缘风落帽，病怀聊借节开尊。","江光鸥鹭晴相狎，秋色芙蓉暮正繁。","何事插萸兄弟会，菰芦生计一家存。"]},{"t":"赠韩孟郁","f":"七言律诗","c":["堂开背郭旧论文，坛坫谁人不让君。","造物有灵供彩笔，声名何意借青云。","山中宦带烟霞色，南海归寻鸥鹭群。","相过未须言兴尽，剡溪春雪正纷纷。"]},{"t":"送梁民部雅倡还朝","f":"七言律诗","c":["投君意气自莲池，云路弹冠惬后期。","踪迹几年相约略，羽毛今日有参差。","行边雨雪随车满，到日莺花与客私。","闻道军储辽左急，司农应是借筹时。"]},{"t":"答周玉绳见寄 其一","f":"七言律诗","c":["书来字字见襟期，尚忆藜灯共署时。","敢向宦情论寂寞，所怜踪迹有参差。","秋风落木愁俱远，水国听鸿梦每迟。","见说出山心自懒，烟霞痼疾赖君医。"]},{"t":"答周玉绳见寄 其二","f":"七言律诗","c":["自乞閒身去帝乡，别君几度易星霜。","幸从春水烹鱼腹，怕向秋风数雁行。","经岁懒无朝省梦，六时翻尽法华香。","灰心未遣情痴断，极目三江练影长。"]},{"t":"寿李景天北堂八十开帙","f":"七言律诗","c":["寿酒欣陪竹下游，星明宝婺照机头。","朝逢海上桃三熟，霜老怀中橘正秋。","绕膝斑衣纡彩袖，承家紫气识青牛。","御舆捧檄俱欢事，舒日萱堂百不忧。"]},{"t":"再与何似公伍国开有开探梅","f":"七言律诗","c":["忆昨探梅梅乍放，芳菲数日竟难支。","春疑太早输寒改，花自含情斗后期。","当眼已无迎客朵，别园犹有避人枝。","殷勤更订重开日，留得青尊为汝迟。"]},{"t":"送大廷尉何公任南少司寇","f":"七言律诗","c":["新恩初拜贰秋卿，风采人争仰旧京。","大老晨星怜近事，苍生霖雨赖兹行。","风流六代凭高尽，王气千秋入望明。","何但东南占执法，还从北斗见持衡。"]},{"t":"送叶吏部赴朝","f":"七言律诗","c":["赐金循吏著高名，官拜仙郎美且清。","物望中朝推简要，主恩一旦重钧衡。","帆前曙拂千花影，马首宵随独雁声。","转石丝纶怜此日，何当启事佐升平。"]},{"t":"上元后二日韩孟郁李烟客同吴人卢一清过访江村有赋","f":"七言律诗","c":["江村春事太无聊，有客诗停访戴桡。","兰佩喜逢吴苑士，桂丛不负小山招。","开尊尚逗灯前月，欹枕同听雨后潮。","鸡黍故人如不薄，吟堂还共对良宵。"]},{"t":"赠卢一清","f":"七言律诗","c":["夫君高韵带烟霞，枝底生涯阅岁华。","世事总无婚嫁累，旅游还到野人家。","形容濯濯风中柳，踪迹遥遥汉上槎。","便欲从君采真去，春风洞口问桃花。"]},{"t":"寄讯韩寅仲","f":"七言律诗","c":["几年归卧罗浮阿，丘壑情知吏隐多。","我自一瓢游汗漫，君今双足健如何。","新诗容易将瑶草，初服谁同制芰荷。","世外襟期应不负，可能相待理烟萝。"]},{"t":"寄陆贞吾座师","f":"七言律诗","c":["海上三惊蕙草残，閒身赢得水云宽。","绛帷一别频飞梦，白日相欺疾跳丸。","雁字正怜烟树渺，凤鸣新向柏台看。","燕山处处多烽火，欲儗追风道路难。"]},{"t":"送黄亮垣先生还朝","f":"七言律诗","c":["客逐春鸿又北征，垂扬难系远游旌。","玉皇香案还仙吏，粤社词坛别主盟。","冻解交河春水满，天空碣石暮云横。","官僚到日应推长，共望前星少海明。"]},{"t":"舟中送别诸子","f":"七言律诗","c":["送客逢春倍黯然，片帆如练湿江烟。","来时喜命相思驾，回日仍同尽兴船。","中岁每伤亲友别，剧谈还借酒杯延。","知君未厌江乡色，荔子丹时订后缘。"]},{"t":"王明府过访村居赋赠","f":"七言律诗","c":["三月河阳花事繁，荒村犹儗百花村。","乍瞻天外来双舄，旋向萝阴布一尊。","竹马儿童争伺驾，□罗太尉未书门。","莫疑春服成偏早，笑语阳春入坐温。"]},{"t":"入省越日即返棹韩孟郁傅贞甫欧子建李烟客诸子见留余不能待别后舟中有怀寄之","f":"七言律诗","c":["乡落一枝栖渐安，入城偏怯送迎难。","相留白社情何剧，可奈山阴兴己阑。","海气蒸霞帆外落，江流样月夜深寒。","不堪欹枕听潮处，杯酒怀人强自宽。"]},{"t":"送杨学宪升任江右参藩","f":"七言律诗","c":["儒宗雅望似君稀，瓜代山公启不违。","大庾东西看赐履，两藩风采识褰帷。","怀中南海珠光满，望里丰城剑气辉。","燮理从需方岳长，玺书行召入彤扉。"]},{"t":"初冬载酒陶摇光宅与诸子夜集分赋","f":"七言律诗","c":["陶家三径肯常开，酒伴招携问胜来。","节已过秋仍看菊，客缘探旧剧为杯。","诗怀清比花枝瘦，酒政严同更漏催。","况是风尘怜去住，可能分手不徘徊。"]},{"t":"楼中检阅古迹忽得刘仲起寄来兰卷赋谢兼复有索","f":"七言律诗","c":["品画临书亦自忙，得君兰卷喜如狂。","墨花淡洒湘皋雨，彩笔纷披大国香。","怀托风光秋色泛，韵含幽谷野情长。","美人倘许重贻赠，何物还誇杂佩芳。"]},{"t":"驾海仙坛","f":"七言律诗","c":["环海丹邱镇上头，七闽佳气望中收。","蜃楼晴挟千峰出，鳌柱雄争万壑流。","鞭石欲看天际日，乘槎应趁海门秋。","白云东去三山近，矫首骖鸾事可求。"]},{"t":"作霖石","f":"七言律诗","c":["削成奇石倚芙蓉，乳注沧溟别有宫。","地拟傅岩霜更早，天疑娲氏补无功。","蛟龙在伏犹吹雾，石燕将飞似掠风。","共向东山占起色，谢公忧乐与人同。"]},{"t":"山中示周日贞黄应晖应远及仁伯代骧两从弟","f":"七言律诗","c":["归来万事兴从慵，云水惟耽访逸踪。","累日可能从叔度，移文应不到周颙。","自惭诸谢传池草，得似三茅驾玉龙。","多恐尘缘消未尽，息心还听定林钟。"]},{"t":"登飞云绝顶","f":"七言律诗","c":["绝嶪淩空一振衣，草眠兼傍石为扉。","罡风不作人间籁，仙驭如逢天外归。","四面星芒手可拾，三更海气日含晖。","蓬莱未隔当年梦，回首风尘愿已违。"]},{"t":"玉女峰","f":"七言律诗","c":["玉女峰头坐翠微，仙郎曾此度灵妃。","空岩光映如珠黍，古洞坛遗化蝶衣。","振袂每看晴雾举，罢妆时有落霞飞。","商风向晚垂垂发，天外应逢环佩归。"]},{"t":"出山留题冲虚观","f":"七言律诗","c":["玄都楼阁倚云边，与客探奇几借眠。","蓬岛飞来峰未稳，丹砂炼后灶仍传。","壑舟不用悲人代，桑海终难变列仙。","四百清缘知有待，重来吾欲结茅椽。"]},{"t":"增江送陆老师入觐 其一","f":"七言律诗","c":["闽粤勋名在芾棠，春花栽得遍河阳。","单车行县长随雨，两袖朝天尚带香。","岘首遗思留片石，云间仙籁忆鸣珰。","近闻天上开阊阖，应得簪毫侍帝裳。"]},{"t":"增江送陆老师入觐 其二","f":"七言律诗","c":["蓬岛飞来第几山，山城如在赤城间。","开云客自工裁锦，求令人非学驻颜。","桃李日边栽并倚，鹤琴天路去难攀。","忧时鞅掌还封事，莫向飞凫羡独閒。"]},{"t":"陆老师招同湛仲立酌流杯亭","f":"七言律诗","c":["为政风流羡我师，閒同秋郭步凉飔。","亭非玄草经还授，山近朱明景自奇。","面面飞霞纷入酒，山山漱玉胜鸣丝。","千秋沂水成孤赏，此日登临又一时。"]},{"t":"大科峰是西樵绝顶","f":"七言律诗","c":["磴道穷跻杳霭间，中天陡绝隔人寰。","千岩风起猿馨乱，上界云归鹤驭閒。","独表层台疑碍汉，下窥群岫似非山。","何当高揖烟霞侣，天外三山任往还。"]},{"t":"游九龙洞","f":"七言律诗","c":["层层磴道上淩空，气结真龙别有宫。","幻出峰峦天上下，閟开岩洞各西东。","瀑帘竟日纷鸣雨，鹤驭何年稳御风。","向夕息徒无处所，山家应在白云中。"]},{"t":"山中赠彭伯时兼索其为图西樵游巷","f":"七言律诗","c":["夫君风雅擅词场，山水情兼胜具强。","埋照阮公原鉴识，餐霞中散是清狂。","琴心雪调寒相和，画里诗情写更长。","为简烟霞归素巷，不须身恋白云乡。"]},{"t":"喷玉岩","f":"七言律诗","c":["一路沿溪听水声，寻来偏称看山情。","巨灵不记何年辟，乌利空传白日升。","始识神仙真洞府，别开天地见虚明。","瀑泉晚潴深潭黑，恐跃蛟龙驾雾行。"]},{"t":"戴公纶彭伯时李烟客三子先归与伍国开有开扶醉夜起送出云路村头怅然赋别","f":"七言律诗","c":["看山期久住山乡，怪底青山有别忙。","野旷乱松作风雨，夜寒清露满衣裳。","任拚去住孤云迹，恨照分携素月光。","残醉未醒天未曙，鸡声茅屋几家霜。"]},{"t":"樵归欧子建书来见讯以予不约偕游为恨赋此谢之兼期见访","f":"七言律诗","c":["丘壑归来意独存，孤云野鹤共飞翻。","岂缘丛桂歌招隐，偶见桃花便问源。","世累暂凭游屐遣，幽期还待社莲论。","一区未谢人间世，春水君能访荜门。"]},{"t":"五羊诸子招饯留别","f":"七言律诗","c":["忆从谢病去长安，五见江南芳蕙残。","一出未应为小草，同心空自惜如兰。","尊开子夜仍灯宴，歌有阳春破暮寒。","何日离亭无送别，可能词客满江干。"]},{"t":"春日王侍御君衡招同韩孝廉孟郁饯别珠江晚移舟重酌海印东楼席上分赋得更渔二字 其一","f":"七言律诗","c":["三年岭海见澄清，多暇还深恋别情。","风采君元千法象，才华吾愧梦长庚。","潮生岛屿千帆转，日暖烟花万壑明。","春服莫疑成太早，阳春先自和歌声。"]},{"t":"春日王侍御君衡招同韩孝廉孟郁饯别珠江晚移舟重酌海印东楼席上分赋得更渔二字 其二","f":"七言律诗","c":["久从湖海乱樵渔，乍别烟霞思未舒。","愧向社莲论小草，漫劳骢马秣征车。","春流鼓棹搴芳杜，夜月登楼啸绮疏。","胜会千秋良不易，可能杯酒不踟蹰。"]},{"t":"席上次韵答王侍御赠别","f":"七言律诗","c":["半壁东南一柱支，三年按部入瓜期。","芾棠南国真千古，鸣凤朝阳又一时。","望里烟云浮玉阙，帆前春色满江湄。","霜威未少澄清意，得和阳春是我私。"]},{"t":"石门留别五弟","f":"七言律诗","c":["归来姜被正依依，惜别珠江又落晖。","自笑味同鸡肋恋，却令人异雁行归。","诗中梦草愁俱远，客里看云泪易挥。","豫约他年春酒熟，劝酬相待未相违。"]},{"t":"石门留示珍奇两儿","f":"七言律诗","c":["汝父南归岁五新，汝仍黄吻未成人。","官怜薄禄耕难代，架有残编业岂贫。","匹马渐销庾岭雪，双龙遥指帝城春。","疏慵报国非吾事，谁为联翩起后尘。"]},{"t":"予壬子岁过峡山正当冲圯兹出山重过阻风两日获登焉胜迹多新颇复旧观则邑人朱惟四所捐赀也朱与予别亦十年馀矣留题二首 其一","f":"七言律诗","c":["十载名山旧试登，兹来重得策枯藤。","漫怜剑气分难合，且喜山灵废复兴。","古洞花深驯野鹿，上方钟罢卧閒僧。","天边极目飞黄鹤，帝子云中第几层。"]},{"t":"予壬子岁过峡山正当冲圯兹出山重过阻风两日获登焉胜迹多新颇复旧观则邑人朱惟四所捐赀也朱与予别亦十年馀矣留题二首 其二","f":"七言律诗","c":["石尤风急驻兰桡，两夜扁舟独听潮。","山水生来元有分，云霞天际忽相招。","风归羽驾闻环佩，峡约江声咽洞箫。","未信出山为小草，随缘何地不逍遥。"]},{"t":"游峡山憩云樊书屋有怀朱惟四","f":"七言律诗","c":["闻说幽栖峡里峰，到来三径碧苔封。","疏林时见窥帘鸟，古洞空归听法龙。","两度经游怜浪迹，十年交好恨萍踪。","知君尚有淩云赋，此地留将伴赤松。"]},{"t":"谒南华宿方丈","f":"七言律诗","c":["弭棹寻幽上翠微，人间宝地此应稀。","偈从顿教参无树，灯自相传授有衣。","月满经堂僧入定，天清卓锡鹤俱飞。","悠悠萍梗宁须问，暂借空门悟息机。"]},{"t":"舟过张曲江丞相墓","f":"七言律诗","c":["山下春江走浊流，山边丞相古坟留。","天成怪石供香火，风递仙韶到寝邱。","陵谷岂知人代改，蘋蘩空荐粤江秋。","低回此际怀风度，拟挟晴霞访十洲。"]},{"t":"予先傅贞父发五羊傅尚饯予珠江及淩江相晤欢然有赋","f":"七言律诗","c":["曾劳祖道唱骊驹，不谓征途再揽袪。","以我浮云閒出岫，逢君野鹤乍淩虚。","尊醪暂解风尘色，诗草新探秘简书。","后会路岐俱不定，驲楼深夜各踟蹰。"]},{"t":"雨后泊小蓼滩见新月","f":"七言律诗","c":["画舫初停小蓼滩，忽看新月挂林端。","先生雨后空如洗，照向江心夜转寒。","乡思正怜鸿影断，客怀联借酒杯宽。","清歌此际无人和，长笛一声起钓竿。"]},{"t":"登曲江龙头山江天阁","f":"七言律诗","c":["崚嶒高阁倚江边，胜迹前贤俎豆传。","一水远盘山势曲，双龙遥拥剑光连。","窗虚面面浮青霭，地迥层层出紫烟。","日暮倚阑频极目，五云天际寸心悬。"]},{"t":"新建苏明府招饮龙沙会","f":"七言律诗","c":["郭外仙宫一径斜，千年人说是龙沙。","地因幽胜心同远，客为枌榆话转赊。","南浦片云归暮雨，天涯浪迹任浮槎。","相逢且醉如渑酒，莫遣春光负落花。"]},{"t":"南昌黄太守招饮滕王阁","f":"七言律诗","c":["滕王遗阁瞰江流，文酒招携识胜游。","台殿已非歌舞旧，风烟犹带古今愁。","斗间剑气双龙合，槛外湖光片雨收。","下榻纵应惭孺子，故人今已重南州。"]},{"t":"南昌阅邸报有感","f":"七言律诗","c":["北来消息到龙沙，时事关心祇自嗟。","辽左几时传露布，纶扉依旧滞宣麻。","边筹谁定帷中画，疏草犹多纸上哗。","惭愧腐儒空扼腕，疏慵何以报王家。"]},{"t":"过兰溪曾令公招饮金兰书院夜复移席山楼","f":"七言律诗","c":["强出青山逐世尘，登临有地即逡巡。","何期浮海逢关尹，却喜通家是故人。","濲水云霞延落照，兰溪花柳逗馀春。","当筵未可轻相负，更醉山楼明月新。"]},{"t":"发兰溪午泊严州登北高峰","f":"七言律诗","c":["早发兰阴兴未穷，高峰又复蹑晴空。","婺华西隔应分彩，岳帝东来别有宫。","烟树倒悬江影出，春花犹映夕阳红。","客怀正判逢僧话，莫遣征帆促晚风。"]},{"t":"初泛西湖","f":"七言律诗","c":["夙昔游情作画图，居然今日到蓬壶。","四天凉籁松围寺，十里烟光水满湖。","日落钟声三竺近，风回鹤吹一山孤。","酒阑未遣催归棹，月映波心纵所如。"]},{"t":"虎丘","f":"七言律诗","c":["西丘日落坐氤氲，吴越山川掌上分。","霸气已荒金虎迹，江涛犹壮水犀军。","离宫雨歇馀芳草，别墅春残起暮云。","独有生公台畔石，吴侬长日醉醺醺。"]},{"t":"史来黄来虞计玄仲去非四文学招同顾上客莫文学游石湖 其一","f":"七言律诗","c":["日落长江紫雾消，篮舆还上碧岧峣。","烟霞旧僻终难改，山水相逢定不饶。","佐酒青蔬分佛供，烹茶活火借僧寮。","吴山好更穷幽赏，未遣邮情促画桡。"]},{"t":"史来黄来虞计玄仲去非四文学招同顾上客莫文学游石湖 其二","f":"七言律诗","c":["年来误戴进贤冠，犹幸官閒束缚宽。","所至送迎俱谢遣，但逢名胜得盘桓。","湖光倒影千山出，雨色阴连万井寒。","几日清游为地主，尽劳寒士供壶餐。"]}]};